(* [local] *)
let gc_move_data_refs_split = prove
 (`(gen_gc_gc_move cc s x = (x1,s1)) /\ (!t r. isRef cc (t,r) <=>
  isMutTag t) /\
    EVERY isDataElement (gc_state_h2 s) /\ EVERY (\x.
      ~(data_to_word_memoryProof_isRef x)) (gc_state_h2 s) /\ EVERY
      data_to_word_memoryProof_isRef (gc_state_r4 s) ==>
    EVERY isDataElement (gc_state_h2 s1) /\
    (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h2
      s1) /\ EVERY data_to_word_memoryProof_isRef (gc_state_r4 s1)`,
  (* a move of the gc keeps the data in h2 and the references in
     r4: of a Data it changes nothing, of a Pointer at a
     DataElement it puts the element in r4 when its tag is a
     mutable one and at the end of h2 when it is not, and the
     statement's hypothesis says that isRef of the configuration
     is exactly that.  `record_simps` (ml/lib/tactics.ml) is what
     HOL4's record simp set does: the accessors of gc_state over
     its updates, which HOL Light's define_record does not give *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
   let gcsimps = record_simps "gc_state" ["h2"; "r4"] in
   (* a DataElement is a reference when its tag is a mutable one *)
   let isref = prove
    (`!ys l tag qs.
        data_to_word_memoryProof_isRef (DataElement ys l (tag,qs)) <=>
        isMutTag tag`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[isRef_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[injectivity "heap_element"; PAIR_EQ] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL]) in
   let isdata = prove
    (`!ys l d. isDataElement (DataElement ys l d)`,
     REWRITE_TAC[isDataElement_def] THEN MESON_TAC[]) in
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "gen_gc_gc_move" (lhs (concl th))
         with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   CASES_BY_NAME "x" THEN
   REWRITE_TAC[gen_gc_gc_move_def] THEN
   EVERY_CASE_TAC THEN
   TRY(CASES_BY_NAME "a2") THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   TRY COND_CASES_TAC THEN
   TRY(W(fun (asl,w) ->
     let t = find_term (fun u ->
       hd_is "gc_forward_ptr" u &&
       length (snd(strip_comb u)) = 5) w in
     MP_TAC(ISPEC t PAIR_SURJECTIVE)) THEN
     DISCH_THEN(CHOOSE_THEN(CHOOSE_THEN SUBST1_TAC))) THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   STRIP_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[PAIR_EQ]) THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
   VAR_EQ_TAC THEN
   ASM_REWRITE_TAC(gcsimps @
                   [K_DEF; ALL_APPEND; ALL; isdata; isref]) THEN
   TRY(FIRST_X_ASSUM(fun h ->
     if is_forall (concl h) then RULE_ASSUM_TAC(REWRITE_RULE[h])
     else fail())) THEN
   ASM_REWRITE_TAC[]));;

(* [local] *)
let gc_move_list_data_refs_split = prove
 (`!x x1 s s1.
   (gen_gc_gc_move_list cc s x = (x1,s1)) /\
    (!t r. (isRef cc (t,r) <=> isMutTag t)) /\ EVERY isDataElement
      (gc_state_h2 s) /\ (EVERY (\x. ~(data_to_word_memoryProof_isRef
      x))) (gc_state_h2 s) /\ EVERY data_to_word_memoryProof_isRef
      (gc_state_r4 s) ==>
    EVERY isDataElement (gc_state_h2 s1) /\ (EVERY (\x.
      ~(data_to_word_memoryProof_isRef x))) (gc_state_h2 s1) /\ EVERY
      data_to_word_memoryProof_isRef (gc_state_r4 s1)`,
  (* the move of a list is the move of its head and then of its
     tail, and each of them keeps the three invariants, which is
     what the theorem about one move says *)
  (let gmd = GEN_ALL gc_move_data_refs_split in
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[gen_gc_gc_move_list_def; PAIR_EQ] THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (CONJUNCTS_THEN2 (K ALL_TAC) (SUBST1_TAC o SYM))
       STRIP_ASSUME_TAC) THEN
     ASM_REWRITE_TAC[];
     REWRITE_TAC[gen_gc_gc_move_list_def] THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[PAIR_EQ] THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (CONJUNCTS_THEN2 (K ALL_TAC) (SUBST1_TAC o SYM))
       STRIP_ASSUME_TAC) THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_EXISTS_TAC THEN
     ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC gmd THEN ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[]]));;

(* [local] *)
let gc_move_refs_data_refs_split = prove
 (`!cc s s1.
   (gc_move_refs cc s = s1) /\
    (!t r. (isRef cc (t,r) <=> isMutTag t)) /\ EVERY isDataElement
      (gc_state_h1 s ++ gc_state_h2 s) /\ (EVERY (\x.
      ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s ++
      gc_state_h2 s) /\
    EVERY data_to_word_memoryProof_isRef (gc_state_r1 s ++
      gc_state_r2 s ++ gc_state_r3 s ++ gc_state_r4 s) ==>
    EVERY isDataElement (gc_state_h1 s1 ++ gc_state_h2 s1) /\
    (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s1
      ++ gc_state_h2 s1) /\
    EVERY data_to_word_memoryProof_isRef (gc_state_r1 s1 ++
      gc_state_r2 s1 ++ gc_state_r3 s1 ++ gc_state_r4 s1)`,
  (* the move of the references takes r2 apart element by element,
     so the induction is on the list that r2 is; the port has no
     induction theorem of the definition.  Of a DataElement the
     element moves into r3 and its list is moved, which is where
     the two theorems about the move of a list come in; of anything
     else the collector only takes the ok flag away *)
  (let gcsimps = record_simps "gc_state"
     ["h1"; "h2"; "r1"; "r2"; "r3"; "r4"] in
   (* a DataElement is a reference when its tag is a mutable one *)
   let isref = prove
    (`!ys l tag qs.
        data_to_word_memoryProof_isRef (DataElement ys l (tag,qs)) <=>
        isMutTag tag`,
     REPEAT GEN_TAC THEN REWRITE_TAC[isRef_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[injectivity "heap_element"; PAIR_EQ] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL]) in
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   (* an equation that says what a field of the state was *)
   let is_fld th =
     is_eq(concl th) &&
     (try let h = fst(dest_const(fst(strip_comb(lhs(concl th))))) in
          String.length h > 9 && String.sub h 0 9 = "gc_state_"
      with Failure _ -> false) in
   (* the statement generalised over the list that r2 is, built from
      the goal: the recursion takes that list apart, and the port
      has no induction theorem of the definition *)
   let r2_induct =
     W(fun (asl,w) ->
       let vs,bod = strip_forall w in
       let s = el 1 vs in
       let r2s = find_term
         (fun t -> hd_is "gc_state_r2" t && rand t = s) bod in
       let l = variant (vs @ frees bod) (mk_var("l",type_of r2s)) in
       let gen = list_mk_forall(l :: vs, mk_imp(mk_eq(r2s,l),bod)) in
       SUBGOAL_THEN gen (fun th ->
         MAP_EVERY X_GEN_TAC vs THEN
         ACCEPT_TAC(MP (SPECL (r2s :: vs) th) (REFL r2s)))) in
   (* an empty r2 moves r3 in front of r1 and stops *)
   let base =
     DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
       STRIP_ASSUME_TAC) THEN
     ASM_REWRITE_TAC(K_DEF :: gcsimps) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[ALL_APPEND; ALL]) THEN
     ASM_REWRITE_TAC[ALL_APPEND; ALL] THEN CONV_TAC TAUT in
   (* and an r2 that is no DataElement only takes the ok flag away *)
   let step_common =
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     ONCE_REWRITE_TAC[gc_move_refs_def] THEN ASM_REWRITE_TAC[] THEN
     MATCH_REDUCE_TAC THEN CASES_ON_NAME "h" THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[injectivity "heap_element";
                 distinctness "heap_element"] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL] THEN
     TRY(DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
           STRIP_ASSUME_TAC) THEN
         ASM_REWRITE_TAC(K_DEF :: gcsimps) THEN NO_TAC) in
   (* a DataElement moves into r3: what the move of its list leaves
      in h2 and r4 is what the induction hypothesis asks of them,
      and the other fields are the ones the move did not touch *)
   let data =
     CASES_ON_NAME "a2" THEN PAIRARG_TAC THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
       STRIP_ASSUME_TAC) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[ALL_APPEND; ALL]) THEN
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
     FIRST_ASSUM(fun a1 ->
       if not(is_pair(rhs(concl a1))) then fail() else
       MP_TAC(MATCH_MP
                (REWRITE_RULE[IMP_CONJ]
                   (GEN_ALL gc_move_list_data_refs_split)) a1) THEN
       MP_TAC(MATCH_MP gc_move_list_IMP a1)) THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN ASM_REWRITE_TAC[] THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN
     REWRITE_TAC[ALL_APPEND] THEN
     FIRST_ASSUM(fun ih ->
       MATCH_MP_TAC(REWRITE_RULE[GSYM IMP_CONJ] ih)) THEN
     W(fun (asl,w) ->
       let vs,bod = strip_exists w in
       let tm = rhs (el 1 (conjuncts bod)) in
       MAP_EVERY EXISTS_TAC [lhand tm; rand tm]) THEN
     ASSUM_LIST(fun ths ->
       RULE_ASSUM_TRY(REWRITE_RULE(filter is_fld ths))) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[isref]) THEN
     ASM_REWRITE_TAC(K_DEF :: gcsimps @ [ALL_APPEND; ALL; isref]) in
   r2_induct THEN LIST_INDUCT_TAC THENL
    [REPEAT GEN_TAC THEN DISCH_TAC THEN
     ONCE_REWRITE_TAC[gc_move_refs_def] THEN ASM_REWRITE_TAC[] THEN
     MATCH_REDUCE_TAC THEN base;
     step_common THEN data]));;

(* [local] *)
let gc_move_data_data_refs_split = prove
 (`!cc s s1.
   (gen_gc_gc_move_data cc s = s1) /\
    (!t r. (isRef cc (t,r) <=> isMutTag t)) /\ (EVERY (\x.
      ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s ++
      gc_state_h2 s) /\
    EVERY isDataElement (gc_state_h1 s ++ gc_state_h2 s) /\
    EVERY data_to_word_memoryProof_isRef (gc_state_r1 s ++
      gc_state_r2 s ++ gc_state_r3 s ++ gc_state_r4 s) ==>
    EVERY isDataElement (gc_state_h1 s1 ++ gc_state_h2 s1) /\
    (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s1
      ++ gc_state_h2 s1) /\
    EVERY data_to_word_memoryProof_isRef (gc_state_r1 s1 ++
      gc_state_r2 s1 ++ gc_state_r3 s1 ++ gc_state_r4 s1)`,
  (* the move of the data takes the head of h2 -- of the state
     after the move of its list, not of the state it started from,
     so the induction is not on a list but on the measure of the
     definition: the room that is left under the limit, which the
     element that moves into h1 makes smaller *)
  (let gcsimps = record_simps "gc_state"
     ["h1"; "h2"; "r1"; "r2"; "r3"; "r4"] in
   (* a DataElement is a reference when its tag is a mutable one,
      and is a data element whatever it holds *)
   let isref = prove
    (`!ys l tag qs.
        data_to_word_memoryProof_isRef (DataElement ys l (tag,qs)) <=>
        isMutTag tag`,
     REPEAT GEN_TAC THEN REWRITE_TAC[isRef_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[injectivity "heap_element"; PAIR_EQ] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL]) in
   let isdata = prove
    (`!ys l d. isDataElement (DataElement ys l d)`,
     REWRITE_TAC[isDataElement_def] THEN MESON_TAC[]) in
   (* what the recursion moves is the tail of h2, and the port's TL
      is HOL4's, which is the empty list of the empty list *)
   let all_tl = prove
    (`!p (l:(A)list). ALL p l ==> ALL p (TL l)`,
     GEN_TAC THEN LIST_INDUCT_TAC THEN
     REWRITE_TAC[hol4_TL; ALL] THEN CONV_TAC TAUT) in
   let hlen = [heap_length_APPEND; heap_length_CONS; heap_length_NIL;
               el_length_def] in
   (* an equation that says what a field of the state was *)
   let is_fld th =
     is_eq(concl th) &&
     (try let h = fst(dest_const(fst(strip_comb(lhs(concl th))))) in
          String.length h > 9 && String.sub h 0 9 = "gc_state_"
      with Failure _ -> false) in
   (* the statement generalised over the measure of the definition,
      built from the goal: what the recursion makes smaller is the
      room that is left under the limit, and the port has no
      induction theorem of the definition *)
   let meas_induct =
     W(fun (asl,w) ->
       let vs,bod = strip_forall w in
       let cc = el 0 vs and s = el 1 vs in
       let meas =
         mk_binop `(-):num->num->num`
           (list_mk_icomb "gen_gc_conf_limit" [cc])
           (list_mk_icomb "heap_length"
              [list_mk_icomb "gc_state_h1" [s]]) in
       let n = variant (vs @ frees bod) (mk_var("n",`:num`)) in
       let gen = list_mk_forall(n :: vs,
                   mk_imp(mk_binop `(<=):num->num->bool` meas n,
                          bod)) in
       SUBGOAL_THEN gen (fun th ->
         MAP_EVERY X_GEN_TAC vs THEN
         ACCEPT_TAC(MP (SPECL (meas :: vs) th)
                       (SPEC meas LE_REFL)))) in
   (* the states that the collector gives back without recursing:
      the state itself, or the state with the ok flag taken away *)
   let triv =
     DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
       STRIP_ASSUME_TAC) THEN
     ASM_REWRITE_TAC(K_DEF :: gcsimps) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[ALL_APPEND; ALL]) THEN
     ASM_REWRITE_TAC[ALL_APPEND; ALL] THEN TRY(CONV_TAC TAUT) in
   let common =
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     ONCE_REWRITE_TAC[gc_move_data_def] THEN EVERY_CASE_TAC THEN
     REWRITE_TAC[COND_ID] THEN TRY COND_CASES_TAC THEN
     TRY(triv THEN NO_TAC) in
   (* of a measure that is 0 there is no room for the element that
      the recursion moves, so the branch cannot be taken *)
   let absurd =
     SUBGOAL_THEN `F` CONTR_TAC THEN
     RULE_ASSUM_TRY(REWRITE_RULE hlen) THEN ASM_ARITH_TAC in
   (* and the element moves into h1, which leaves the room under the
      limit smaller by its own length: what the move of its list
      leaves in h2 and r4 is what the induction hypothesis asks of
      them, and the other fields are the ones the move did not
      touch *)
   let data =
     CASES_ON_NAME "a2" THEN PAIRARG_TAC THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
       STRIP_ASSUME_TAC) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[ALL_APPEND; ALL]) THEN
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th
       else fail())) THEN
     FIRST_ASSUM(fun a1 ->
       if not(is_pair(rhs(concl a1))) then fail() else
       MP_TAC(MATCH_MP
                (REWRITE_RULE[IMP_CONJ]
                   (GEN_ALL gc_move_list_data_refs_split)) a1) THEN
       MP_TAC(MATCH_MP gc_move_list_IMP a1)) THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN
     ASM_REWRITE_TAC[ALL; ALL_APPEND] THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN
     ASSUM_LIST(fun ths ->
       RULE_ASSUM_TRY(REWRITE_RULE(filter is_fld ths))) THEN
     ASSUM_LIST(fun ths ->
       MAP_EVERY ASSUME_TAC (mapfilter (MATCH_MP all_tl) ths)) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[isref]) THEN
     REWRITE_TAC[ALL_APPEND] THEN
     FIRST_ASSUM(fun ih ->
       MATCH_MP_TAC(REWRITE_RULE[GSYM IMP_CONJ] ih)) THEN
     W(fun (asl,w) ->
       let vs,bod = strip_exists w in
       let tm = rhs (el 1 (conjuncts bod)) in
       MAP_EVERY EXISTS_TAC [lhand tm; rand tm]) THEN
     ASM_REWRITE_TAC(K_DEF :: gcsimps @
                     [ALL_APPEND; ALL; isref; isdata]) THEN
     RULE_ASSUM_TRY(REWRITE_RULE hlen) THEN
     REWRITE_TAC hlen THEN ASM_ARITH_TAC in
   meas_induct THEN INDUCT_TAC THENL
    [common THEN absurd; common THEN data]));;

(* [local] *)
let gc_move_loop_data_refs_split = prove
 (`!clock cc s s1.
   (gen_gc_gc_move_loop cc s clock = s1) /\
   (!t r. (isRef cc (t,r) <=> isMutTag t)) /\
   EVERY isDataElement (gc_state_h1 s ++ gc_state_h2 s) /\
   (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s
     ++ gc_state_h2 s) /\
   EVERY data_to_word_memoryProof_isRef (gc_state_r1 s ++ gc_state_r2
     s ++ gc_state_r3 s ++ gc_state_r4 s) ==>
   EVERY isDataElement (gc_state_h1 s1 ++ gc_state_h2 s1) /\
   (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s1
     ++ gc_state_h2 s1) /\
   EVERY data_to_word_memoryProof_isRef (gc_state_r1 s1 ++
     gc_state_r2 s1 ++ gc_state_r3 s1 ++ gc_state_r4 s1)`,
  (* the loop moves the refs or the data and goes round again, and
     each step keeps the three invariants: the clock is the
     induction, the two theorems above are the step, and an update
     of the ok, the r2 or the r4 field leaves the heaps alone *)
  (let okf = prove
     (`!f (s:('a,'b)gc_state).
         (gc_state_h1 (gc_state_ok_fupd f s) = gc_state_h1 s) /\
         (gc_state_h2 (gc_state_ok_fupd f s) = gc_state_h2 s) /\
         (gc_state_r1 (gc_state_ok_fupd f s) = gc_state_r1 s) /\
         (gc_state_r2 (gc_state_ok_fupd f s) = gc_state_r2 s) /\
         (gc_state_r3 (gc_state_ok_fupd f s) = gc_state_r3 s) /\
         (gc_state_r4 (gc_state_ok_fupd f s) = gc_state_r4 s)`,
      REPEAT GEN_TAC THEN RECORD_CASES_TAC `s:('a,'b)gc_state`) in
    let fupds = prove
     (`!(x:(('a,'b)heap_element)list) (s:('a,'b)gc_state).
         (gc_state_h1 (gc_state_r2_fupd (K x) s) = gc_state_h1 s) /\
         (gc_state_h2 (gc_state_r2_fupd (K x) s) = gc_state_h2 s) /\
         (gc_state_r1 (gc_state_r2_fupd (K x) s) = gc_state_r1 s) /\
         (gc_state_r2 (gc_state_r2_fupd (K x) s) = x) /\
         (gc_state_r3 (gc_state_r2_fupd (K x) s) = gc_state_r3 s) /\
         (gc_state_r4 (gc_state_r2_fupd (K x) s) = gc_state_r4 s) /\
         (gc_state_h1 (gc_state_r4_fupd (K x) s) = gc_state_h1 s) /\
         (gc_state_h2 (gc_state_r4_fupd (K x) s) = gc_state_h2 s) /\
         (gc_state_r1 (gc_state_r4_fupd (K x) s) = gc_state_r1 s) /\
         (gc_state_r2 (gc_state_r4_fupd (K x) s) = gc_state_r2 s) /\
         (gc_state_r3 (gc_state_r4_fupd (K x) s) = gc_state_r3 s) /\
         (gc_state_r4 (gc_state_r4_fupd (K x) s) = x)`,
      REPEAT GEN_TAC THEN RECORD_CASES_TAC `s:('a,'b)gc_state`) in
    let gmrd = GEN_ALL gc_move_refs_data_refs_split in
    let gmdd = GEN_ALL gc_move_data_data_refs_split in
    let refl_exists (asl,w as gl) =
      let vs,bod = strip_exists w in
      let l,r = dest_eq (hd (conjuncts bod)) in
      let i = term_match [] l r in
      MAP_EVERY EXISTS_TAC (map (instantiate i) vs) gl in
    INDUCT_TAC THEN REPEAT GEN_TAC THEN
    GEN_REWRITE_TAC (LAND_CONV o LAND_CONV o LAND_CONV)
      [gen_gc_gc_move_loop_def] THEN
    EVERY_CASE_TAC THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[NOT_SUC; ARITH_RULE `SUC n - 1 = n`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM) STRIP_ASSUME_TAC) THEN
    REWRITE_TAC[okf] THEN
    TRY(ASM_REWRITE_TAC[] THEN NO_TAC) THEN
    TRY(FIRST_X_ASSUM MATCH_MP_TAC THEN refl_exists THEN
        ASM_REWRITE_TAC[]) THEN
    TRY(MATCH_MP_TAC gmdd THEN refl_exists THEN ASM_REWRITE_TAC[]) THEN
    TRY(MATCH_MP_TAC gmrd THEN refl_exists THEN
        REWRITE_TAC[fupds] THEN
        RULE_ASSUM_TAC(REWRITE_RULE[ALL_APPEND]) THEN
        ASM_REWRITE_TAC[ALL_APPEND; ALL])));;

(* [local] *)
let gen_gc_data_refs_split = prove
 (`!cc roots heap.
   (gen_gc cc (roots,heap) = (roots1,s)) /\
   (!t r. (isRef cc (t,r) <=> isMutTag t)) ==>
   (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s
     ++ gc_state_h2 s) /\
   EVERY isDataElement (gc_state_h1 s ++ gc_state_h2 s) /\
   EVERY data_to_word_memoryProof_isRef (gc_state_r1 s ++
     gc_state_r2 s ++ gc_state_r3 s ++ gc_state_r4 s)`,
  (* the collector starts from a state whose six heaps are empty,
     moves the roots and then runs the loop: what the move of a
     list leaves in h2 and r4 is what the loop asks of them, and
     the fields that the move does not touch are the empty ones of
     the state it started from *)
  (let rt = record_thms "gc_state" in
   (* the witnesses of a lemma about a step of the collector, which
      the equation of the goal gives *)
   let refl_exists (asl,w as gl) =
     let vs,bod = strip_exists w in
     let l,r = dest_eq (hd (conjuncts bod)) in
     let i = term_match [] l r in
     MAP_EVERY EXISTS_TAC (map (instantiate i) vs) gl in
   (* and the fields that the move of a list leaves alone, put
      back: a rewrite with the equations is slow, where the
      substitution is not *)
   let subst_imp =
     FIRST_ASSUM(fun a1 ->
       let imp = MATCH_MP gc_move_list_IMP a1 in
       MAP_EVERY (fun e -> SUBST1_TAC (SYM e))
         (filter (fun th -> is_eq(concl th)) (CONJUNCTS imp))) in
   REPEAT GEN_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
   REWRITE_TAC[gen_gc_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN PAIRARG_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[PAIR_EQ] THEN
   DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (SUBST1_TAC o SYM)) THEN
   MATCH_MP_TAC(TAUT `b /\ a /\ c ==> a /\ b /\ c`) THEN
   MATCH_MP_TAC(GEN_ALL gc_move_loop_data_refs_split) THEN
   refl_exists THEN REWRITE_TAC[] THEN subst_imp THEN
   REWRITE_TAC(empty_state_def :: rt) THEN REWRITE_TAC[APPEND] THEN
   CONJ_TAC THENL
    [FIRST_ASSUM MATCH_ACCEPT_TAC;
     MATCH_MP_TAC(GEN_ALL gc_move_list_data_refs_split) THEN
     ASM_EXISTS_TAC THEN
     ASM_REWRITE_TAC(empty_state_def :: rt) THEN REWRITE_TAC[ALL]]));;

let heap_expand_not_isRef = prove
 (`EVERY (\x. ~(data_to_word_memoryProof_isRef x)) (heap_expand n)`,
  (REWRITE_TAC[heap_expand_def] THEN COND_CASES_TAC THEN
   REWRITE_TAC[ALL; isRef_def] THEN
   MATCH_REDUCE_TAC THEN REWRITE_TAC[]));;

let reset_gens_def = cake_define
  `reset_gens conf a =
     (match data_to_word_config_gc_kind conf with
       data_to_word_Generational sizes -> GenState 0 (MAP (K a)
       sizes) | _25 -> GenState 0 [])`;;

let gen_state_ok_reset = prove
 (`heap_ok (h ++ heap_expand n ++ r) l ==>
    gen_state_ok (heap_length h) (n + heap_length h)
      (h ++ heap_expand n ++ r) (reset_gens conf (heap_length h))`,
  (* the generations that reset_gens makes all start where the first
     heap ends, and nothing of that heap points into the space that
     the expansion leaves: a pointer of a DataElement points at a
     DataElement, and what is in the expansion is an Unused *)
  (let notin = prove
    (`!(hh:((A,B)heap_element) list) rr n p.
        heap_length hh <= p /\ p < n + heap_length hh
        ==> ~(isSomeDataElement
                (heap_lookup p (hh ++ heap_expand n ++ rr)))`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND] THEN
     ASM_SIMP_TAC[ARITH_RULE `(h:num) <= p ==> ~(p < h)`;
                  gen_gc_heap_length_heap_expand] THEN
     SUBGOAL_THEN `p - heap_length (hh:((A,B)heap_element) list) < n`
       ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN `~(n = 0)` ASSUME_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[heap_expand_def] THEN
     REWRITE_TAC[heap_lookup_def; el_length_def] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[isSomeDataElement_def;
                     injectivity "option"; distinctness "option";
                     distinctness "heap_element"] THEN
     ASM_SIMP_TAC[ARITH_RULE
       `p - h < n /\ ~(n = 0) ==> p - h < (n - 1) + 1`] THEN
     REWRITE_TAC[isSomeDataElement_def; distinctness "option"]) in
   STRIP_TAC THEN
   REWRITE_TAC[reset_gens_def] THEN
   STRUCT_CASES_TAC (ISPEC `data_to_word_config_gc_kind conf`
     (cases "gc_kind")) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[gen_state_ok_def; ALL] THEN
   REWRITE_TAC[GSYM ALL_MEM; MEM_MAP; K_DEF] THEN
   REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[LE_REFL] THEN
   REWRITE_TAC[gen_start_ok_def] THEN
   ONCE_REWRITE_TAC[heap_split_APPEND_if] THEN
   REWRITE_TAC[LT_REFL; SUB_REFL; heap_split_0] THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[APPEND_NIL] THEN
   W(fun (asl,w) ->
     let bod = snd(strip_exists w) in
     let pr = rand(lhs(lhand bod)) in
     let a,b = dest_pair pr in
     MAP_EVERY EXISTS_TAC [a; b]) THEN
   REWRITE_TAC[] THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   MATCH_MP_TAC(TAUT `(~a /\ ~b ==> F) ==> a \/ b`) THEN
   STRIP_TAC THEN
   W(fun (asl,w) ->
     let ths = map snd asl in
     let hd_is n th =
       (try fst(dest_const(fst(strip_comb(concl th)))) = n
        with Failure _ -> false) in
     let arg_is n th =
       (try fst(dest_const(fst(strip_comb(
              el 0 (snd(strip_comb(concl th))))))) = n
        with Failure _ -> false) in
     let okth = find (hd_is "heap_ok") ths in
     let memd = find (fun th ->
       hd_is "MEM" th && arg_is "DataElement" th)
                  ths in
     let memp = find (fun th -> hd_is "MEM" th &&
                                arg_is "gc_shared_Pointer" th) ths in
     let dargs = snd(strip_comb(el 0 (snd(strip_comb(concl memd))))) in
     let pargs = snd(strip_comb(el 0 (snd(strip_comb(concl memp))))) in
     let cl = CONJUNCT2(CONJUNCT2
       (REWRITE_RULE[heap_ok_def] okth)) in
     MP_TAC(SPECL (dargs @ pargs) cl)) THEN
   ASM_REWRITE_TAC[MEM_APPEND] THEN
   DISCH_TAC THEN
   W(fun (asl,w) ->
     let ths = map snd asl in
     let hd_is n th =
       (try fst(dest_const(fst(strip_comb(concl th)))) = n
        with Failure _ -> false) in
     let sde = find (hd_is "isSomeDataElement") ths in
     let heap = rand(el 0 (snd(strip_comb(concl sde)))) in
     let hh = lhand heap in
     let rr = rand(rand heap) in
     MP_TAC(ISPECL [hh; rr] notin)) THEN
   ASM_SIMP_TAC[] THEN
   DISCH_THEN(fun th -> MP_TAC(SPEC_ALL th)) THEN
   ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC));;

(* gen_gc_thm *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let data_to_word_memoryProof_gen_gc_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,heap,be,a,sp,sp1,gens) limit ts
  ==>
      (?roots2 state2.
        (gen_gc (make_gc_conf limit) (roots,heap) =
          (roots2,state2)) /\
        abs_ml_inv conf stack refs
          (roots2,gc_state_h1 state2 ++ heap_expand (gc_state_n
            state2) ++ gc_state_r1 state2,be,gc_state_a
           state2,gc_state_n state2,0,reset_gens conf (gc_state_a
             state2)) limit ts /\ gc_state_ok state2 /\
        (heap_length (gc_state_h1 state2 ++ gc_state_r1 state2) =
         heap_length (heap_filter (reachable_addresses roots heap)
           heap)) /\
        EVERY isDataElement (gc_state_h1 state2) /\
        EVERY isDataElement (gc_state_r1 state2) /\
        all_reachable_from_roots roots2
          (gc_state_h1 state2 ++ heap_expand (gc_state_n state2)
            ++ gc_state_r1 state2))`),
  (* the attempt: the proof of the source names abs_ml_inv_def,
     make_gc_conf_def, gen_gc_def, heap_ok_def, gen_gc_related,
     gen_gc_ok.  What is here rewrites with them and closes by
     arithmetic, and the cheat is behind it until the proof is
     written.  A MESON over them is what the next round adds; it
     costs a load ten minutes to have it in every attempt and it
     closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[abs_ml_inv_def; make_gc_conf_def;
       gen_gc_def; heap_ok_def; gen_gc_related; gen_gc_ok] THEN
     TRY ASM_ARITH_TAC)));;

let has_gen_def = cake_define
  `has_gen (GenState _26 xs) <=> ~(xs = [])`;;

let heap_split_heap_split = prove
 (`!heap n1 n2 h1 h2 h3 h4.
      heap_split n2 heap = SOME (h3,h4) /\
      heap_split n1 heap = SOME (h1,h2) /\ n1 <= n2 ==>
      (?m.
        h2 = m ++ h4 /\ h3 = h1 ++ m /\ heap = h1 ++ m ++ h4 /\
        heap_split (n2 - heap_length h1) h2 = SOME (m,h4))`,
  (* the split at the later point goes through the earlier one: the
     middle piece is what the split of the second half gives, and
     the induction follows the two splits down the heap, one element
     at a time *)
  (let exwit = W(fun (asl,w) ->
     EXISTS_TAC (lhs (el 1 (conjuncts (snd(strip_exists w)))))) in
   let stripconj =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) in
   let aux = prove
    (`!(heap:((A,B)heap_element) list) n1 n2 h1 h2 h3 h4.
        heap_split n2 heap = SOME (h3,h4) /\
        heap_split n1 heap = SOME (h1,h2) /\ n1 <= n2
        ==> ?m. h2 = m ++ h4 /\ h3 = h1 ++ m /\
                heap = h1 ++ m ++ h4 /\
                heap_split (n2 - heap_length h1) h2 = SOME (m,h4)`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[heap_split_def] THENL
      [ASM_CASES_TAC `n2 = 0` THEN
       ASM_REWRITE_TAC[distinctness "option"] THEN
       ASM_CASES_TAC `n1 = 0` THEN
       ASM_REWRITE_TAC[distinctness "option"] THEN
       REWRITE_TAC[injectivity "option"; PAIR_EQ] THEN
       STRIP_TAC THEN VAR_EQ_TAC THEN
       EXISTS_TAC `[]:((A,B)heap_element) list` THEN
       REWRITE_TAC[APPEND; heap_length_NIL; SUB_0] THEN
       ASM_REWRITE_TAC[heap_split_def];
       ALL_TAC] THEN
     ASM_CASES_TAC `n2 = 0` THEN
     ASM_REWRITE_TAC[distinctness "option"] THENL
      [STRIP_TAC THEN
       SUBGOAL_THEN `n1 = 0` SUBST_ALL_TAC THENL
        [ASM_ARITH_TAC; ALL_TAC] THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option"; PAIR_EQ]) THEN
       stripconj THEN VAR_EQ_TAC THEN
       EXISTS_TAC `[]:((A,B)heap_element) list` THEN
       REWRITE_TAC[APPEND; heap_length_NIL; SUB_0;
                   heap_split_def];
       ALL_TAC] THEN
     ASM_CASES_TAC `n2 < el_length (h:(A,B)heap_element)` THEN
     ASM_REWRITE_TAC[distinctness "option"] THEN
     ASM_CASES_TAC `n1 = 0` THEN ASM_REWRITE_TAC[] THENL
      [EVERY_CASE_TAC THEN
       REWRITE_TAC[distinctness "option"; injectivity "option";
                   PAIR_EQ] THEN
       STRIP_TAC THEN stripconj THEN VAR_EQ_TAC THEN
       REWRITE_TAC[APPEND; heap_length_NIL; SUB_0] THEN
       exwit THEN
       FIRST_X_ASSUM(fun ih ->
         FIRST_ASSUM(fun a1 ->
           MP_TAC(MATCH_MP ih (CONJ a1 (CONJ
             (ISPEC `t:((A,B)heap_element) list`
                (GEN_ALL heap_split_0))
             (SPEC `n2 - el_length (h:(A,B)heap_element)`
                LE_0)))))) THEN
       REWRITE_TAC[APPEND] THEN
       DISCH_THEN(X_CHOOSE_THEN `mm:((A,B)heap_element) list`
         STRIP_ASSUME_TAC) THEN
       VAR_EQ_TAC THEN
       ASM_REWRITE_TAC[APPEND; CONS_11; heap_split_def] THEN
       MATCH_REDUCE_TAC THEN REWRITE_TAC[];
       ALL_TAC] THEN
     ASM_CASES_TAC `n1 < el_length (h:(A,B)heap_element)` THEN
     ASM_REWRITE_TAC[distinctness "option"] THEN
     EVERY_CASE_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option";
                 PAIR_EQ] THEN
     STRIP_TAC THEN stripconj THEN VAR_EQ_TAC THEN
     SUBGOAL_THEN `n1 - el_length (h:(A,B)heap_element) <=
                   n2 - el_length (h:(A,B)heap_element)`
       ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     FIRST_X_ASSUM(fun ih ->
       FIRST_ASSUM(fun a1 -> FIRST_ASSUM(fun a2 -> FIRST_ASSUM(fun a3 ->
         MP_TAC(MATCH_MP ih (CONJ a1 (CONJ a2 a3))) THEN
         DISCH_THEN(X_CHOOSE_THEN `mm:((A,B)heap_element) list`
           STRIP_ASSUME_TAC) THEN
         VAR_EQ_TAC THEN
         EXISTS_TAC `mm:((A,B)heap_element) list` THEN
         ASM_REWRITE_TAC[APPEND; CONS_11;
                         heap_length_CONS] THEN
         REWRITE_TAC[ARITH_RULE `a - (b + c) = (a - b) - c`] THEN
         ASM_REWRITE_TAC[]))))) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let heap_split_LESS_EQ = prove
 (`!heap n x. heap_split n heap = SOME x ==> n <= heap_length heap`,
