   ASM_REWRITE_TAC[distinctness "option"; LE_0] THEN
   DISCH_TAC THEN USE_IH THEN ASM_ARITH_TAC));;

(* [local] *)
let isRef_heap_expand = prove
 (`!x. EVERY (\x. ~(data_to_word_memoryProof_isRef x)) (heap_expand x)`,
