let all_ts_append = prove
 (`!refs x y. all_ts refs (x ++ y) = all_ts refs x UNION all_ts refs y`,
  (REPEAT GEN_TAC THEN REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM; MEM_APPEND] THEN
   MESON_TAC[]));;

let all_ts_head = prove
 (`!refs x xs. all_ts refs (x :: xs) = all_ts refs [x] UNION all_ts
  refs xs`,
  (REPEAT GEN_TAC THEN REWRITE_TAC[GSYM all_ts_append; APPEND]));;

let v_all_vs_MEM = prove
 (`!l ts tag xs.
     MEM (Block ts tag xs) (v_all_vs l) ==> (?x y. v_all_vs l = x
       ++ (Block ts tag xs :: v_all_vs xs) ++ y)`,
  (* the values of a list are the values of its head followed by
     the ones of its tail, and a Block among them is followed by
     the values of its payload: the induction of the type gives
     both halves at once, and what each case does to the two
     pieces of the append is what the three lemmas say *)
  (let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let ext0 = prove
    (`!b:dataSem_v list. ?p q. b = p ++ b ++ q`,
     GEN_TAC THEN EXISTS_TAC `[]:dataSem_v list` THEN
     EXISTS_TAC `[]:dataSem_v list` THEN
     REWRITE_TAC[APPEND; APPEND_NIL]) in
   let extc = prove
    (`!(h:dataSem_v) t b. (?p q. t = p ++ b ++ q)
                          ==> (?p q. CONS h t = p ++ b ++ q)`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(X_CHOOSE_THEN `p:dataSem_v list`
       (X_CHOOSE_THEN `q:dataSem_v list` SUBST1_TAC)) THEN
     EXISTS_TAC `CONS (h:dataSem_v) p` THEN
     EXISTS_TAC `q:dataSem_v list` THEN REWRITE_TAC[APPEND]) in
   let extl = prove
    (`!(s:dataSem_v list) t b. (?p q. t = p ++ b ++ q)
                               ==> (?p q. s ++ t = p ++ b ++ q)`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(X_CHOOSE_THEN `p:dataSem_v list`
       (X_CHOOSE_THEN `q:dataSem_v list` SUBST1_TAC)) THEN
     EXISTS_TAC `s ++ p:dataSem_v list` THEN
     EXISTS_TAC `q:dataSem_v list` THEN
     REWRITE_TAC[GSYM APPEND_ASSOC]) in
   let extr = prove
    (`!(s:dataSem_v list) t b. (?p q. t = p ++ b ++ q)
                               ==> (?p q. t ++ s = p ++ b ++ q)`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(X_CHOOSE_THEN `p:dataSem_v list`
       (X_CHOOSE_THEN `q:dataSem_v list` SUBST1_TAC)) THEN
     EXISTS_TAC `p:dataSem_v list` THEN
     EXISTS_TAC `q ++ s:dataSem_v list` THEN
     REWRITE_TAC[APPEND_ASSOC]) in
   let triv = REPEAT GEN_TAC THEN
     REWRITE_TAC[vsing; MEM; distinctness "dataSem_v"] in
   SUBGOAL_THEN
     `(!x ts tag xs.
         MEM (Block ts tag xs) (v_all_vs [x])
         ==> (?p q. v_all_vs [x] =
                    p ++ (Block ts tag xs :: v_all_vs xs) ++ q)) /\
      (!l ts tag xs.
         MEM (Block ts tag xs) (v_all_vs l)
         ==> (?p q. v_all_vs l =
                    p ++ (Block ts tag xs :: v_all_vs xs) ++ q))`
     (fun th -> MATCH_ACCEPT_TAC(CONJUNCT2 th)) THEN
   MATCH_MP_TAC (dataSem_v_induct ()) THEN REPEAT CONJ_TAC THENL
    [triv; triv;
     REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[vsing; MEM; injectivity "dataSem_v"] THEN
     DISCH_THEN(DISJ_CASES_THEN2
       (fun eq -> STRIP_ASSUME_TAC eq THEN ASM_REWRITE_TAC[] THEN
                  MATCH_ACCEPT_TAC ext0)
       (fun m -> FIRST_ASSUM(fun ih ->
                   MATCH_ACCEPT_TAC(MATCH_MP extc (MATCH_MP ih m)))));
     triv; triv;
     REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[vcons] THEN REWRITE_TAC[MEM_APPEND] THEN
     DISCH_THEN(DISJ_CASES_THEN2
       (fun m -> FIRST_ASSUM(fun ih ->
                   MATCH_ACCEPT_TAC(MATCH_MP extr (MATCH_MP ih m))))
       (fun m -> FIRST_ASSUM(fun ih ->
                   MATCH_ACCEPT_TAC(MATCH_MP extl
                     (MATCH_MP ih m)))))]));;

let v_in_all_vs = prove
 (`!x y stack' refs.
     x IN all_vs refs stack' /\ MEM y (v_all_vs [x]) ==> y IN
       all_vs refs stack'`,
  (* a value of a value of what the refs and the stack hold is one
     of them as well: each of the four parts of all_vs is a list
     and the values of a list are transitively closed *)
  (REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   REPEAT GEN_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC ASSUME_TAC) THEN
   FIRST_ASSUM(fun mx -> FIRST_ASSUM(fun my ->
     ASSUME_TAC(MATCH_MP (snd (v_all_vs_trans_thm ()))
                         (CONJ mx my)))) THEN
   ASM_MESON_TAC[]));;

let v_all_vs_MEM2 = prove
 (`!l ts tag xs.
     MEM (Block ts tag xs) (v_all_vs l) ==> (?x. MEM x l /\ MEM
       (Block ts tag xs) (v_all_vs [x]))`,
  (* the values of v_all_vs (x::xs) are x itself, the values of its
     payload where it is a Block, and the values of v_all_vs xs: the
     first two are the values of v_all_vs [x] and the third is what
     the induction hypothesis is about *)
  (let vav = v_all_vs_def in
   let vnil = prove
    (`v_all_vs ([]:dataSem_v list) = []`,
     GEN_REWRITE_TAC LAND_CONV [vav] THEN MATCH_REDUCE_TAC THEN
     REWRITE_TAC[]) in
   let vsing = prove
    (`!t tag xs y. MEM y (v_all_vs [Block t tag xs]) <=>
        y = Block t tag xs \/ MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [vav] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[vnil; APPEND_NIL; MEM; MEM_APPEND]) in
   LIST_INDUCT_TAC THENL
    [REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN CASES_ON_NAME "h" THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [vav] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[MEM; MEM_APPEND; distinctness "dataSem_v"] THEN
     ASM_MESON_TAC[vsing]]));;

let v_all_vs_ts = prove
 (`!x ts tag xs. MEM (Block ts tag xs) (v_all_vs [x]) ==> MEM ts
  (v_all_ts x)`,
  (* induction on the value and on a list of values at once, which
     is what define_datatype gives for a type that nests a list of
     itself: the timestamp of a Block among the values of a value is
     one of the timestamps of that value *)
  (let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let triv = REPEAT GEN_TAC THEN
     REWRITE_TAC[vsing; MEM; distinctness "dataSem_v"] in
   SUBGOAL_THEN
     `(!x ts tag xs.
         MEM (Block ts tag xs) (v_all_vs [x]) ==> MEM ts (v_all_ts x))
      /\
      (!l ts tag xs.
         MEM (Block ts tag xs) (v_all_vs l)
         ==> MEM ts (FLAT (MAP v_all_ts l)))`
     (fun th -> MATCH_ACCEPT_TAC(CONJUNCT1 th)) THEN
   MATCH_MP_TAC dataSem_v_INDUCT THEN REPEAT CONJ_TAC THENL
    [triv; triv;
     REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[vsing; vats; MEM; injectivity "dataSem_v"] THEN
     ASM_MESON_TAC[];
     triv; triv;
     REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[vcons] THEN
     REWRITE_TAC[MEM_APPEND; MAP; FLAT] THEN
     ASM_MESON_TAC[]]));;

let MEM_v_all_vs = prove
 (`!l v. MEM v l ==> MEM v (v_all_vs l)`,
  (let vav = v_all_vs_def in
   LIST_INDUCT_TAC THEN REWRITE_TAC[MEM] THEN GEN_TAC THEN
   CASES_ON_NAME "h" THEN
   GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [vav] THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[MEM_APPEND; MEM] THEN ASM_MESON_TAC[]));;

let MEM_stack_all_vs = prove
 (`!v stack' refs. MEM v stack' ==> v IN all_vs refs stack'`,
  (REPEAT STRIP_TAC THEN
   REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   REPEAT DISJ2_TAC THEN MATCH_MP_TAC MEM_v_all_vs THEN
   ASM_REWRITE_TAC[]));;

let v_all_vs_ts_MEM = prove
 (`!x y ts. MEM ts (v_all_ts x) /\ MEM x (v_all_vs [y]) ==> MEM ts
  (v_all_ts y)`,
  (* the induction that ml/lib/tactics.ml does for the proofs that
     need this before the file states it *)
  (let (c1,_) = v_all_vs_ts_thm () in
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun a2 -> FIRST_ASSUM(fun a1 ->
     MATCH_ACCEPT_TAC(MATCH_MP c1 (CONJ a1 a2))))));;

let v_all_vs_trans = prove
 (`!x y z. MEM y (v_all_vs x) /\ MEM z (v_all_vs [y]) ==> MEM z
  (v_all_vs x)`,
  (* the induction that ml/lib/tactics.ml does for the proofs that
     need this before the file states it *)
  (MATCH_ACCEPT_TAC (snd (v_all_vs_trans_thm ()))));;

let MEM_in_all_ts = prove
 (`!x ts stack' refs.
     x IN all_vs refs stack' /\ MEM ts (v_all_ts x) ==> ts IN
       all_ts refs stack'`,
  (* only a Block has a timestamp, and a Block among the values of
     what the refs and the stack hold is among the values of one of
     the values that a ref holds or of one on the stack, whose
     timestamps are therefore timestamps of the stack *)
  (let (c1,_) = v_all_vs_ts_thm () in
   let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let fr = prove
    (`(!l x. find_ref (bvlSem_ValueArray l) x <=> MEM x l) /\
      (!m v x. find_ref (Thunk m v) x <=> (v = x)) /\
      (!tg fin l c r x. find_ref (bvlSem_MutBlock tg fin l c r) x <=>
         MEM x (l ++ [c] ++ r))`,
     REPEAT CONJ_TAC THEN REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [find_ref_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   SUBGOAL_THEN `?t tag l. (x:dataSem_v) = Block t tag l`
     STRIP_ASSUME_TAC THENL
    [CASES_ON_NAME "x" THEN
     RULE_ASSUM_TAC(REWRITE_RULE[vats; MEM]) THEN
     TRY(FIRST_ASSUM CONTR_TAC) THEN MESON_TAC[];
     ALL_TAC] THEN
   FIRST_X_ASSUM SUBST_ALL_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[all_vs_def; IN_UNION;
                               IN_ELIM_THM]) THEN
   REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[IN_ELIM_THM] THEN
   ASM_MESON_TAC[v_all_vs_MEM2; c1; fr; MEM_APPEND]));;

let MEM_in_all_vs = prove
 (`!x y refs stack'. x IN all_vs refs stack' /\ MEM y (v_all_vs [x])
  ==> y IN all_vs refs stack'`,
  (REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   REPEAT STRIP_TAC THEN ASM_MESON_TAC[v_all_vs_trans]));;

(* NOT USED *)
let v_all_vs_ts_list = prove
 (`!x y ts. MEM x (v_all_vs y) /\ MEM ts (v_all_ts x) ==> MEM ts (FLAT
  (MAP v_all_ts y))`,
  (* the other half of that induction: the timestamps of a value
     among the values of a list are timestamps of the list *)
  (let (_,c2) = v_all_vs_ts_thm () in
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun a2 -> FIRST_ASSUM(fun a1 ->
     MATCH_ACCEPT_TAC(MATCH_MP c2 (CONJ a1 a2))))));;

let v_inv_tf_update_thm_lemma = prove
 (`!ck v refs y f tf heap ts' a.
     v_inv conf v refs (y,f,tf,heap) /\ ~(ts' IN FDOM tf) ==>
       v_inv_ck ck conf v refs (y,f,tf |+ (ts',a),heap)`,
  (* the same complete induction as v_inv_SUBMAP_lemma, but only the
     map of the timestamps changes and by an update at a timestamp
     that is not in its domain: a Block of the invariant has its
     timestamp in that domain, so its lookup is the one it was *)
  (let (vr,_,_) = v_inv_ck in
   let rl = CONJUNCTS vr in
   let vdef = v_inv_def in
   let NOT_VAR_TAC =
     FIRST_ASSUM(fun nb ->
       if is_neg(concl nb) && is_var(rand(concl nb))
       then SUBST_ALL_TAC(EQF_INTRO nb) else fail()) in
   let FLU_TAC =
     ASM_REWRITE_TAC[FLOOKUP_UPDATE] THEN COND_CASES_TAC THEN
     ASM_REWRITE_TAC[] THEN
     FIRST_ASSUM(fun fl -> MP_TAC(MATCH_MP FLOOKUP_IN_FDOM fl)) THEN
     ASM_REWRITE_TAC[] in
   let lt1 = ARITH_RULE `~(ck = 0) ==> ck - 1 < ck` in
   let setup =
     MATCH_MP_TAC num_WF THEN X_GEN_TAC `ck:num` THEN DISCH_TAC THEN
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     CASES_ON_NAME "v" THEN USE_CHANGED [vdef] in
   setup THENL
    [COND_CASES_TAC THEN STRIP_TAC THEN SUBST_LHS_TAC THENL
      [MATCH_MP_TAC(el 0 rl) THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC(el 1 rl) THEN ASM_REWRITE_TAC[]];
     STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
     MATCH_MP_TAC(el 2 rl) THEN ASM_REWRITE_TAC[];
     COND_CASES_TAC THEN STRIP_TAC THEN REPEAT SUBST_LHS_TAC THENL
      [MATCH_MP_TAC(el 7 rl) THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC(el 8 rl) THEN REPEAT CONJ_TAC THENL
        [FIRST_ASSUM MATCH_ACCEPT_TAC;
         DISCH_TAC THEN
         FIRST_ASSUM(fun a2th ->
           if can (term_match [] `EVERY2 (p:A->B->bool) l m`)
                  (concl a2th)
           then MP_TAC a2th else fail()) THEN
         MATCH_MP_TAC MONO_ALL2 THEN BETA_TAC THEN
         REPEAT STRIP_TAC THEN CK_IH_TAC;
         FLU_TAC;
         FIRST_ASSUM MATCH_ACCEPT_TAC]];
     STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
     MATCH_ACCEPT_TAC(el 3 rl);
     DISCH_THEN(DISJ_CASES_THEN2 STRIP_ASSUME_TAC
       (DISJ_CASES_THEN2 STRIP_ASSUME_TAC STRIP_ASSUME_TAC)) THENL
      [REPEAT SUBST_LHS_TAC THEN MATCH_MP_TAC(el 4 rl) THEN
       REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
       ASM_REWRITE_TAC[];
       NOT_VAR_TAC THEN
       FIRST_ASSUM(fun ih ->
         ASM_MESON_TAC[el 5 rl; SPEC `ck - 1` ih; lt1]);
       NOT_VAR_TAC THEN
       FIRST_ASSUM(fun ih ->
         ASM_MESON_TAC[el 6 rl; SPEC `ck - 1` ih; lt1])]]));;

let v_inv_tf_update_thm = prove
 (`!conf v refs y f tf heap ts' a.
     v_inv conf v refs (y,f,tf,heap) /\ ~(ts' IN FDOM tf) ==>
     v_inv conf v refs (y,f,tf |+ (ts',a),heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_tf_update_thm_lemma]));;

(* the port's own: what the lemmas about a change of the refs
   share.  Each of them says that the clocked relation holds of a
   value after a cell of the refs is put in or changed, and each is
   the same complete induction on the clock, with the same four
   facts about the lookups of the new refs to be proved of the cell
   in question. *)

(* the port's own: a key that the refs do not have has no lookup *)
let no_lk = prove
 (`~(ptr IN domain (refs:(A)spt)) ==> lookup ptr refs = NONE`,
  REWRITE_TAC[domain_lookup] THEN
  STRUCT_CASES_TAC(ISPEC `lookup ptr (refs:(A)spt)`
    (cases_of `:(A)option`)) THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  MESON_TAC[]);;

(* and a key of f is a key of the refs, so it is not one that the
   refs do not have *)
let notptr = prove
 (`lookup ptr refs = NONE /\
   (!x. x IN FDOM f ==> x IN domain refs) /\ k IN FDOM f
   ==> ~(k = ptr)`,
  REWRITE_TAC[domain_lookup] THEN
  MESON_TAC[distinctness "option"]);;

let v_inv_ck_rules = CONJUNCTS (let (vr,_,_) = v_inv_ck in vr);;

(* the b of a RefPtr that the two thunk rules ask to be false *)
let NOT_VAR_TAC =
  FIRST_ASSUM(fun nb ->
    if is_neg(concl nb) && is_var(rand(concl nb))
    then SUBST_ALL_TAC(EQF_INTRO nb) else fail());;

(* the four facts that such a lemma proves of its own refs -- the
   lookup of a thunk, the annotation of a pointer, the dest_thunk
   of a value and the condition of a plain reference, of the new
   refs against the old ones -- which its own `same` gives when it
   is applied to the assumption that says what the refs are *)
let v_inv_refs_parts same lk =
  let s = MATCH_MP same lk in
  (CONJUNCT1 s,CONJUNCT1(CONJUNCT2 s),
   CONJUNCT1(CONJUNCT2(CONJUNCT2 s)),
   CONJUNCT2(CONJUNCT2(CONJUNCT2 s)));;

(* the case of a plain reference, whose annotation is the one it
   was *)
let V_INV_REFS_PLAIN same =
  REPEAT SUBST_LHS_TAC THEN
  FIRST_ASSUM(fun lk ->
    let (t_eq,a_eq,_,m_imp) = v_inv_refs_parts same lk in
    REWRITE_TAC[GSYM a_eq] THEN
    MATCH_MP_TAC(el 4 v_inv_ck_rules) THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM MATCH_ACCEPT_TAC;
      ASM_REWRITE_TAC[t_eq];
      MATCH_MP_TAC m_imp THEN FIRST_ASSUM MATCH_ACCEPT_TAC]);;

(* and the case of a thunk, whose value and heap element the rule
   names and not its conclusion, so MESON applies the rule *)
let V_INV_REFS_THUNK same n =
  let lt1 = ARITH_RULE `~(ck = 0) ==> ck - 1 < ck` in
  NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
  FIRST_ASSUM(fun lk ->
    let (t_eq,_,dt,_) = v_inv_refs_parts same lk in
    FIRST_ASSUM(fun ih ->
      ASM_MESON_TAC[el n v_inv_ck_rules; t_eq; dt;
                    SPEC `ck - 1` ih; lt1]));;

(* the three cases of a RefPtr where the refs do not change and the
   heap does: a plain reference reads nothing of the heap, and the
   heap element of a thunk is the one that the lemma's own
   hypothesis about the two heaps carries over, which is the
   argument.  The witnesses of the two thunk rules are the ones
   that the assumptions name: the thunk of the refs and the
   element of the heap. *)

let V_INV_HEAP_PLAIN =
  REPEAT SUBST_LHS_TAC THEN
  MATCH_MP_TAC(el 4 v_inv_ck_rules) THEN ASM_REWRITE_TAC[];;

let V_INV_HEAP_THUNK hp n =
  let wit =
    W(fun (asl,w) ->
      let thunk = tryfind (fun (_,th) ->
        let t = concl th in
        if is_eq t && hd_is "bvlSem_Thunk" (rand(rhs t))
        then rand(rhs t) else fail()) asl in
      if n = 5 then
        let x = tryfind (fun (_,th) ->
          let t = concl th in
          if is_eq t && hd_is "ThunkBlock" (rand(rhs t))
          then rand(rand(rhs t)) else fail()) asl in
        MAP_EVERY EXISTS_TAC [lhand thunk; rand thunk; x]
      else EXISTS_TAC (rand thunk)) in
  NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
  MATCH_MP_TAC(el n v_inv_ck_rules) THEN wit THEN
  REPEAT CONJ_TAC THEN
  FIRST [FIRST_ASSUM MATCH_ACCEPT_TAC; hp;
         DISCH_TAC THEN CK_IH_TAC];;

(* the induction that the lemmas about a change of the refs share.
   It is the complete induction on the ck of the relation that
   v_inv_SUBMAP_lemma does by hand: the value is taken apart with
   v_inv_def and the rule of the relation for that shape is
   applied, where the maps are the ones they were and what a Block
   asks of its elements is the induction hypothesis at ck - 1.  The
   arguments are the tactic that applies the induction hypothesis
   (CK_IH_TAC where it takes the assumptions as they stand), the
   one that proves the FLOOKUP of tf of a Block (an assumption
   where tf does not change), the tactic that derives from the
   lemma's own hypothesis what its cases use, the one that proves a
   heap_lookup of the new heap (ALL_TAC where the heap does not
   change), and the three of a RefPtr: a plain reference and the
   two thunks. *)
let V_INV_REFS_TAC_IH ih tp prep hp d5 d6 d7 =
  let rl = v_inv_ck_rules in
  let VAL_CASES_TAC (asl,w) =
    CASES_ON_TAC (el 2 (snd(strip_comb w))) (asl,w) in
  let setup =
    MATCH_MP_TAC num_WF THEN X_GEN_TAC `ck:num` THEN
    DISCH_TAC THEN REPEAT GEN_TAC THEN
    (DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) ORELSE
     DISCH_TAC) THEN
    prep THEN VAL_CASES_TAC THEN USE_CHANGED [v_inv_def] in
  (* a Number is a small one or a Bignum of the heap *)
  let c1 =
    COND_CASES_TAC THEN STRIP_TAC THEN SUBST_LHS_TAC THENL
     [MATCH_MP_TAC(el 0 rl) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(el 1 rl) THEN ASM_REWRITE_TAC[] THEN hp] in
  let c2 =
    STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
    MATCH_MP_TAC(el 2 rl) THEN ASM_REWRITE_TAC[] THEN hp in
  (* a Block is a BlockNil or a BlockRep whose elements the
     induction hypothesis carries over one by one *)
  let c3 =
    COND_CASES_TAC THEN STRIP_TAC THEN REPEAT SUBST_LHS_TAC THENL
     [MATCH_MP_TAC(el 7 rl) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(el 8 rl) THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM MATCH_ACCEPT_TAC;
        DISCH_TAC THEN
        FIRST_ASSUM(fun a2th ->
          if can (term_match [] `EVERY2 (p:A->B->bool) l m`)
                 (concl a2th)
          then MP_TAC a2th else fail()) THEN
        (* the elements come with their membership of the two
           lists, which the hypothesis of a lemma about the
           timestamps asks for *)
        ONCE_REWRITE_TAC[LIST_REL_MEM] THEN
        MATCH_MP_TAC MONO_ALL2 THEN BETA_TAC THEN
        REPEAT STRIP_TAC THEN
        TRY(FIRST_ASSUM(fun imp ->
          FIRST_ASSUM(fun m1 -> FIRST_ASSUM(fun m2 ->
            ASSUME_TAC(MP imp (CONJ m1 m2)))))) THEN
        ih;
        tp;
        ASM_REWRITE_TAC[] THEN hp]] in
  let c4 = STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
           MATCH_ACCEPT_TAC(el 3 rl) in
  let c5 =
    DISCH_THEN(DISJ_CASES_THEN2 STRIP_ASSUME_TAC
      (DISJ_CASES_THEN2 STRIP_ASSUME_TAC STRIP_ASSUME_TAC)) THENL
     [d5; d6; d7] in
  setup THENL [c1; c2; c3; c4; c5];;

(* and the induction as the lemmas whose hypothesis the induction
   hypothesis takes as it stands use it *)

let V_INV_REFS_TAC =
  V_INV_REFS_TAC_IH CK_IH_TAC (FIRST_ASSUM MATCH_ACCEPT_TAC);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_tf_update_thm_alt_lemma = prove
 (cake_as_vars (fun () ->
    `!ck v refs y f tf heap ts' a.
       v_inv conf v refs (y,f,tf,heap) /\ ~(ts' IN (all_ts refs
         stack)) /\ ~(ts' IN set_of_list (v_all_ts v)) ==>
           v_inv_ck ck conf v refs (y,f,tf |+ (ts',a),heap)`),
  (* tf is what changes, and only a Block reads it: of the Block
     itself the timestamp of the update is not its own (the
     hypothesis says so), and of an element the induction
     hypothesis asks for the timestamps of the element, which are
     the Block's.  Of the value that a thunk of the refs holds they
     are the refs' (MEM_in_all_ts) *)
  (let rl = v_inv_ck_rules in
   let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let nlt = ARITH_RULE `!n. ~(n = 0) ==> n - 1 < n` in
   (* the value that a thunk of the refs holds is a value of the
      refs, so its timestamps are the refs' *)
   let in_av = prove
    (cake_as_vars (fun () ->
       `lookup n refs = SOME (Thunk ev v)
        ==> v IN all_vs refs stack`),
     DISCH_TAC THEN
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
     DISJ2_TAC THEN DISJ1_TAC THEN
     MAP_EVERY EXISTS_TAC
       [`n:num`; `ev:thunk_mode`; `v:dataSem_v`] THEN
     ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC MEM_v_all_vs THEN REWRITE_TAC[MEM]) in
   (* the assumption that says that the timestamp of the update is
      none of a value's *)
   let is_tsc c =
     is_neg c &&
     (try hd_is "set_of_list" (rand(rand c)) with Failure _ -> false) in
   (* the hypothesis of the lemma, conjunct by conjunct *)
   let prep =
     FIRST_ASSUM(fun c ->
       if is_conj (concl c) then MAP_EVERY ASSUME_TAC (CONJUNCTS c)
       else fail()) in
   (* the induction hypothesis at ck - 1, with the condition of the
      value it is applied to proved by the argument *)
   let ih_by tac =
     FIRST_ASSUM(fun nz ->
       let c = concl nz in
       if not(is_neg c) then fail() else
       let e = rand c in
       if not(is_eq e) || not(type_of(lhs e) = `:num`) ||
          not(rhs e = `0`) then fail() else
       let lt = MP (SPEC (lhs e) nlt) nz in
       FIRST_ASSUM(fun ihth ->
         let ih' = MP (SPEC (mk_binop `(-):num->num->num` (lhs e) `1`)
                         ihth) lt in
         MATCH_MP_TAC ih' THEN REPEAT CONJ_TAC THEN
         TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN tac)) in
   (* of an element of a Block its timestamps are the Block's *)
   let ih =
     ih_by
      (FIRST_ASSUM(fun tsc ->
         if not (is_tsc (concl tsc)) then fail() else
         MP_TAC(REWRITE_RULE[IN_SET_OF_LIST; vats; MEM; MEM_FLAT;
                             MEM_MAP] tsc)) THEN
       REWRITE_TAC[IN_SET_OF_LIST] THEN ASM_MESON_TAC[]) in
   (* and of the value of a thunk they are the refs' *)
   let ih_thunk =
     ih_by
      (REWRITE_TAC[IN_SET_OF_LIST] THEN DISCH_TAC THEN
       FIRST_ASSUM(fun m ->
         FIRST_ASSUM(fun lk ->
           MP_TAC(MATCH_MP MEM_in_all_ts
             (CONJ (MATCH_MP in_av lk) m)))) THEN
       ASM_REWRITE_TAC[]) in
   (* the timestamp of the update is no timestamp of the Block *)
   let tp =
     REWRITE_TAC[FLOOKUP_UPDATE] THEN COND_CASES_TAC THENL
      [FIRST_ASSUM(fun tsc ->
         if not (is_tsc (concl tsc)) then fail() else
         MP_TAC(REWRITE_RULE[IN_SET_OF_LIST; vats; MEM] tsc)) THEN
       ASM_REWRITE_TAC[];
       FIRST_ASSUM MATCH_ACCEPT_TAC] in
   let NOT_VAR_TAC =
     FIRST_ASSUM(fun nb ->
       if is_neg(concl nb) && is_var(rand(concl nb))
       then SUBST_ALL_TAC(EQF_INTRO nb) else fail()) in
   let wit n =
     W(fun (asl,w) ->
       let thunk = tryfind (fun (_,th) ->
         let t = concl th in
         if is_eq t && hd_is "bvlSem_Thunk" (rand(rhs t))
         then rand(rhs t) else fail()) asl in
       if n = 5 then
         let x = tryfind (fun (_,th) ->
           let t = concl th in
           if is_eq t && hd_is "ThunkBlock" (rand(rhs t))
           then rand(rand(rhs t)) else fail()) asl in
         MAP_EVERY EXISTS_TAC [lhand thunk; rand thunk; x]
       else EXISTS_TAC (rand thunk)) in
   let d_thunk n =
     NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
     MATCH_MP_TAC(el n rl) THEN wit n THEN REPEAT CONJ_TAC THEN
     FIRST [FIRST_ASSUM MATCH_ACCEPT_TAC;
            DISCH_TAC THEN ih_thunk] in
   V_INV_REFS_TAC_IH ih tp prep ALL_TAC V_INV_HEAP_PLAIN
     (d_thunk 5) (d_thunk 6)));;

let v_inv_tf_update_thm_alt = prove
 (`!conf v refs y f tf heap ts' a stack'.
     v_inv conf v refs (y,f,tf,heap) /\ ~(ts' IN (all_ts refs
       stack')) /\ ~(ts' IN set_of_list (v_all_ts v)) ==>
     v_inv conf v refs (y,f,tf |+ (ts',a),heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_tf_update_thm_alt_lemma]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_tf_update_lemma = prove
 (cake_as_vars (fun () ->
    `!ck v1 refs v2.
       v_inv conf v1 refs v2 ==>
         (!ts tag xs y f tf heap.
           v1 = (Block ts tag xs) /\
           v2 = (y,f,tf,heap) /\
           v1 IN (all_vs refs stack) /\ ~(ts' IN all_ts refs stack)
             ==>
             v_inv_ck ck conf v1 refs (y,f,tf |+ (ts',a),heap))`),
  (* a Block of the refs and the stack: its timestamps are among
     the stack's (MEM_in_all_ts), so the new one is none of them
     and v_inv_tf_update_thm_alt applies *)
  (let no_ts = prove
    (cake_as_vars (fun () ->
       `x IN all_vs refs stack /\ ~(ts' IN all_ts refs stack)
        ==> ~(ts' IN set_of_list (v_all_ts x))`),
     REWRITE_TAC[IN_SET_OF_LIST] THEN REPEAT STRIP_TAC THEN
     FIRST_ASSUM(fun m ->
       if not (hd_is "MEM" (concl m)) then fail() else
       FIRST_ASSUM(fun av ->
         if not (hd_is "all_vs" (rand(concl av))) then fail() else
         MP_TAC(MATCH_MP MEM_in_all_ts (CONJ av m)))) THEN
     ASM_REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
   (* the two equations of the antecedent are substituted, and the
      first of them in the two hypotheses that follow it *)
   DISCH_THEN(fun th ->
     let e1 = CONJUNCT1 th and r1 = CONJUNCT2 th in
     let e2 = CONJUNCT1 r1 in
     SUBST_ALL_TAC e1 THEN SUBST_ALL_TAC e2 THEN
     STRIP_ASSUME_TAC(REWRITE_RULE[e1] (CONJUNCT2 r1))) THEN
   FIRST_ASSUM(fun av ->
     if not (hd_is "all_vs" (rand(concl av))) then fail() else
     FIRST_ASSUM(fun nts ->
       if not (is_neg (concl nts)) then fail() else
       let ts = MATCH_MP no_ts (CONJ av nts) in
       FIRST_ASSUM(fun vi ->
         if not (hd_is "v_inv" (concl vi)) then fail() else
         MATCH_ACCEPT_TAC(SPEC_ALL(REWRITE_RULE[v_inv_eq]
           (MATCH_MP v_inv_tf_update_thm_alt
             (CONJ vi (CONJ nts ts))))))))));;

let v_inv_tf_update = prove
 (`!conf refs y f tf heap heap1 a stack' ts ts' tag xs.
      (Block ts tag xs) IN (all_vs refs stack') /\ ~(ts' IN all_ts
        refs stack') /\
      v_inv conf (Block ts tag xs) refs (y,f,tf,heap) ==> v_inv
        conf ((Block ts tag xs)) refs (y,f,tf |+ (ts',a),heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_tf_update_lemma]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_tf_restrict_lemma = prove
 (cake_as_vars (fun () ->
    `!ck v1 refs y f tf heap.
       v_inv conf v1 refs (y,f,tf,heap) ==>
           (!x. MEM x (v_all_ts v1) ==> x IN P) /\
           (!x. x IN (all_ts refs stack) ==> x IN P) ==>
             v_inv_ck ck conf v1 refs (y,f,DRESTRICT tf P,heap)`),
  (* the same of a tf whose domain is restricted: a Block keeps its
     timestamp, which the hypothesis says is in the set, and of an
     element the induction hypothesis asks for the timestamps of
     the element (the Block's) -- of the value of a thunk for the
     refs' (MEM_in_all_ts) *)
  (let rl = v_inv_ck_rules in
   let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let nlt = ARITH_RULE `!n. ~(n = 0) ==> n - 1 < n` in
   (* the value that a thunk of the refs holds is a value of the
      refs, so its timestamps are the refs' *)
   let in_av = prove
    (cake_as_vars (fun () ->
       `lookup n refs = SOME (Thunk ev v)
        ==> v IN all_vs refs stack`),
     DISCH_TAC THEN
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
     DISJ2_TAC THEN DISJ1_TAC THEN
     MAP_EVERY EXISTS_TAC
       [`n:num`; `ev:thunk_mode`; `v:dataSem_v`] THEN
     ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC MEM_v_all_vs THEN REWRITE_TAC[MEM]) in
   (* the two conditions of the lemma *)
   let prep = DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) in
   (* the induction hypothesis at ck - 1, with the condition of the
      value it is applied to proved by the argument *)
   let ih_by tac =
     FIRST_ASSUM(fun nz ->
       let c = concl nz in
       if not(is_neg c) then fail() else
       let e = rand c in
       if not(is_eq e) || not(type_of(lhs e) = `:num`) ||
          not(rhs e = `0`) then fail() else
       let lt = MP (SPEC (lhs e) nlt) nz in
       FIRST_ASSUM(fun ihth ->
         let ih' = REWRITE_RULE[GSYM IMP_CONJ]
                     (MP (SPEC (mk_binop `(-):num->num->num`
                                  (lhs e) `1`) ihth) lt) in
         MATCH_MP_TAC ih' THEN REPEAT CONJ_TAC THEN
         TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN tac)) in
   (* the assumption about the timestamps of the value and the one
      about the timestamps of the refs *)
   let is_val a =
     let c = concl a in
     is_forall c &&
     (let b = snd(strip_forall c) in
      is_imp b &&
      (try hd_is "MEM" (lhand b) with Failure _ -> false)) in
   let is_refs a =
     let c = concl a in
     is_forall c &&
     (let b = snd(strip_forall c) in
      is_imp b &&
      (try hd_is "all_ts" (rand(lhand b)) with Failure _ -> false)) in
   (* the timestamps of an element of a Block are the Block's *)
   let ih =
     ih_by
      (GEN_TAC THEN DISCH_TAC THEN
       FIRST_ASSUM(fun a ->
         if not (is_val a) then fail() else MATCH_MP_TAC a) THEN
       REWRITE_TAC[vats; MEM; MEM_FLAT; MEM_MAP] THEN
       ASM_MESON_TAC[]) in
   (* and those of the value of a thunk are the refs' *)
   let ih_thunk =
     ih_by
      (GEN_TAC THEN DISCH_TAC THEN
       FIRST_ASSUM(fun b ->
         if not (is_refs b) then fail() else MATCH_MP_TAC b) THEN
       FIRST_ASSUM(fun m ->
         FIRST_ASSUM(fun lk ->
           MATCH_ACCEPT_TAC(MATCH_MP MEM_in_all_ts
             (CONJ (MATCH_MP in_av lk) m))))) in
   (* a Block keeps its timestamp, so the restriction keeps it *)
   let tp =
     REWRITE_TAC[FLOOKUP_DRESTRICT] THEN COND_CASES_TAC THENL
      [FIRST_ASSUM MATCH_ACCEPT_TAC;
       FIRST_ASSUM(fun nin ->
         if not (is_neg (concl nin)) then fail() else
         let t = lhand(rand(concl nin)) in
         if not (type_of t = `:num`) then fail() else
         FIRST_ASSUM(fun a ->
           if not (is_val a) then fail() else
           MP_TAC(SPEC t a))) THEN
       REWRITE_TAC[vats; MEM] THEN ASM_REWRITE_TAC[]] in
   let NOT_VAR_TAC =
     FIRST_ASSUM(fun nb ->
       if is_neg(concl nb) && is_var(rand(concl nb))
       then SUBST_ALL_TAC(EQF_INTRO nb) else fail()) in
   let wit n =
     W(fun (asl,w) ->
       let thunk = tryfind (fun (_,th) ->
         let t = concl th in
         if is_eq t && hd_is "bvlSem_Thunk" (rand(rhs t))
         then rand(rhs t) else fail()) asl in
       if n = 5 then
         let x = tryfind (fun (_,th) ->
           let t = concl th in
           if is_eq t && hd_is "ThunkBlock" (rand(rhs t))
           then rand(rand(rhs t)) else fail()) asl in
         MAP_EVERY EXISTS_TAC [lhand thunk; rand thunk; x]
       else EXISTS_TAC (rand thunk)) in
   let d_thunk n =
     NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
     MATCH_MP_TAC(el n rl) THEN wit n THEN REPEAT CONJ_TAC THEN
     FIRST [FIRST_ASSUM MATCH_ACCEPT_TAC;
            DISCH_TAC THEN ih_thunk] in
   V_INV_REFS_TAC_IH ih tp prep ALL_TAC V_INV_HEAP_PLAIN
     (d_thunk 5) (d_thunk 6)));;

let v_inv_tf_restrict = prove
 (`!conf v refs stack' y f tf heap P.
      v_inv conf v refs (y,f,tf,heap) /\
      (!x. MEM x (v_all_ts v) ==> x IN P) /\
      (!x. x IN (all_ts refs stack') ==> x IN P) ==>
        v_inv conf v refs (y,f,DRESTRICT tf P,heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_tf_restrict_lemma]));;

let v_all_vs_append = prove
 (`!x y. v_all_vs (x ++ y) = v_all_vs x ++ v_all_vs y`,
  (let vav = v_all_vs_def in
   let vnil = prove
    (`v_all_vs ([]:dataSem_v list) = []`,
     GEN_REWRITE_TAC LAND_CONV [vav] THEN MATCH_REDUCE_TAC THEN
     REWRITE_TAC[]) in
   LIST_INDUCT_TAC THENL
    [REWRITE_TAC[APPEND; vnil];
     GEN_TAC THEN REWRITE_TAC[APPEND] THEN CASES_ON_NAME "h" THEN
     GEN_REWRITE_TAC LAND_CONV [vav] THEN MATCH_REDUCE_TAC THEN
     GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [vav] THEN
     MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[APPEND; GSYM APPEND_ASSOC]]));;

let MEM_v_all_vs_split = prove
 (`!x v xs. MEM x (v_all_vs (v :: xs)) ==> MEM x (v_all_vs [v]) \/ MEM
  x (v_all_vs xs)`,
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   REPEAT GEN_TAC THEN
   GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV) [cons_app] THEN
   REWRITE_TAC[v_all_vs_append; MEM_APPEND]));;

let MEM_v_all_vs_split2 = prove
 (`MEM x (v_all_vs (v :: y :: xs)) ==>
     MEM x (v_all_vs (v :: xs)) \/ MEM x (v_all_vs [y])`,
  (* v_all_vs of a cons splits into the values of the head and the
     values of the tail (v_all_vs_append, as the source has it), and
     the three parts of v :: y :: xs go where they belong *)
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   let vcons = prove
    (`!(v:dataSem_v) xs y. MEM y (v_all_vs (CONS v xs)) <=>
        MEM y (v_all_vs [v]) \/ MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [cons_app] THEN
     REWRITE_TAC[v_all_vs_append; MEM_APPEND]) in
   MESON_TAC[vcons]));;

let MEM_v_all_vs_extend_tl = prove
 (`!x v xs. MEM x (v_all_vs [v]) ==> MEM x (v_all_vs (v :: xs))`,
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   REPEAT GEN_TAC THEN
   GEN_REWRITE_TAC (RAND_CONV o RAND_CONV o RAND_CONV) [cons_app] THEN
   REWRITE_TAC[v_all_vs_append; MEM_APPEND] THEN CONV_TAC TAUT));;

let MEM_v_all_vs_extend_hd = prove
 (`!x v xs. MEM x (v_all_vs xs) ==> MEM x (v_all_vs (v :: xs))`,
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   REPEAT GEN_TAC THEN
   GEN_REWRITE_TAC (RAND_CONV o RAND_CONV o RAND_CONV) [cons_app] THEN
   REWRITE_TAC[v_all_vs_append; MEM_APPEND] THEN CONV_TAC TAUT));;

let MEM_v_all_vs_extend_append = prove
 (`MEM x (v_all_vs xs) ==> MEM x (v_all_vs (xs ++ ys))`,
  (REWRITE_TAC[v_all_vs_append; MEM_APPEND] THEN CONV_TAC TAUT));;

let MEM_v_all_vs_EL = prove
 (`!xs i x.
     i < LENGTH xs /\
     MEM x (v_all_vs [EL i xs]) ==>
       MEM x (v_all_vs xs)`,
  (LIST_INDUCT_TAC THENL
    [REWRITE_TAC[LENGTH; LT];
     GEN_TAC THEN STRUCT_CASES_TAC (SPEC `i:num` num_CASES) THEN
     REWRITE_TAC[EL; HD; TL; LENGTH; LT_SUC; LT_0] THEN
     ASM_MESON_TAC[MEM_v_all_vs_extend_hd; MEM_v_all_vs_extend_tl]]));;

let MEM_v_all_vs_LUPDATE = prove
 (`!xs i v x.
     MEM x (v_all_vs (LUPDATE v i xs)) ==>
       MEM x (v_all_vs [v]) \/ MEM x (v_all_vs xs)`,
  (* the LUPDATE puts v where the index says and leaves the rest,
     so a value of the result is one of v or one of the list *)
  (let vnil = prove
    (`v_all_vs ([]:dataSem_v list) = []`,
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   LIST_INDUCT_TAC THEN REWRITE_TAC[LUPDATE] THENL
    [REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN COND_CASES_TAC THEN
     DISCH_THEN(fun th -> MP_TAC(MATCH_MP MEM_v_all_vs_split th)) THEN
     STRIP_TAC THEN
     FIRST [DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
            DISJ2_TAC THEN MATCH_MP_TAC MEM_v_all_vs_extend_hd THEN
            FIRST_ASSUM ACCEPT_TAC;
            DISJ2_TAC THEN MATCH_MP_TAC MEM_v_all_vs_extend_tl THEN
            FIRST_ASSUM ACCEPT_TAC;
            FIRST_ASSUM(fun ih -> MP_TAC(SPECL
              [`i - 1`; `v:dataSem_v`; `x:dataSem_v`] ih)) THEN
            ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
            MATCH_MP_TAC(TAUT `(b ==> c) ==> (a \/ b ==> a \/ c)`) THEN
            MATCH_ACCEPT_TAC MEM_v_all_vs_extend_hd]]));;

let all_vs_Block = prove
 (`all_vs refs ((Block t tag xs:dataSem_v) :: ys) =
   Block t tag xs INSERT all_vs refs (xs ++ ys)`,
  (let vav_block = prove
    (`!t tag xs ys.
        v_all_vs (CONS (Block t tag xs) ys) =
        APPEND (CONS (Block t tag xs) (v_all_vs xs)) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   REWRITE_TAC[all_vs_def; v_all_vs_append; vav_block] THEN
   REWRITE_TAC[EXTENSION; IN_INSERT; IN_UNION; IN_ELIM_THM;
               MEM_APPEND; MEM] THEN
   MESON_TAC[]));;

let blocks_unique_cons_thm = prove
 (`blocks_unique ts s ==>
   blocks_unique (ts + 1) (Block ts tag xs INSERT s)`,
  (* the four cases of the two Blocks: both the new one (the goal is
     then an equation of the arguments), one of them the new one (the
     other has a timestamp below ts, so the two cannot be equal), or
     both in the set (which is what the hypothesis is about).  The
     instance of the hypothesis is written down, because its
     antecedent has to be discharged by the assumptions as they
     stand: rewriting with t = ts first would put the antecedent out
     of reach of them. *)
  (let inst a b c d =
     FIRST_ASSUM(fun h -> MP_TAC(SPECL [`t:num`; a; b; c; d] h)) THEN
     ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] in
   let a1 = `a1:num` and x1 = `xs1:dataSem_v list`
   and a2 = `a2:num` and x2 = `xs2:dataSem_v list` in
   REWRITE_TAC[blocks_unique_def; IN_INSERT;
               injectivity "dataSem_v"] THEN
   DISCH_TAC THEN REPEAT GEN_TAC THEN DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST
    [ASM_REWRITE_TAC[] THEN ARITH_TAC;
     inst a1 x1 a2 x2 THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     ASM_ARITH_TAC;
     inst a2 x2 a2 x2 THEN STRIP_TAC THEN
     SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC;
     inst a1 x1 a1 x1 THEN STRIP_TAC THEN
     SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let cons_thm_alt = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ stack) refs (roots,heap,be,a,sp,sp1,gens)
  limit ts /\
      LENGTH xs < sp /\ ~(xs = []) ==>
      (?rs roots2 heap2.
        (roots = rs ++ roots2) /\ (LENGTH rs = LENGTH xs) /\
        (heap_store_unused_alt a (sp + sp1) (BlockRep tag rs) heap
          = (heap2,T)) /\
        abs_ml_inv conf
          ((Block ts tag xs) :: stack) refs
          (gc_shared_Pointer a (wordLang_Word (ptr_bits conf tag
            (LENGTH xs))) :: roots2,
           heap2,be,a + el_length (BlockRep tag rs),
           sp - el_length (BlockRep tag rs),sp1,gens) limit (ts +
             1))`),
  (* the attempt: the proof of the source names abs_ml_inv_def,
     bc_stack_ref_inv_def, FDOM, LIST_REL_SPLIT1,
     unused_space_inv_def, IMP_heap_store_unused_alt.  What is here
     rewrites with them and closes by arithmetic, and the cheat is
     behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def; FDOM;
       LIST_REL_SPLIT1; unused_space_inv_def;
       IMP_heap_store_unused_alt] THEN
     TRY ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let cons_thm_EMPTY = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,(heap:(('a
  word_loc,data_to_word_memoryProof_tag#('a word_loc) list)heap_element)
  list),be,a,sp,sp1,gens) limit ts /\
      tag < dimword (:'a) DIV 16 ==>
      abs_ml_inv conf ((Block 0 tag []) :: stack) refs
        (gc_shared_Data (wordLang_Word (BlockNil tag)) ::
          roots,heap,be,a,sp,sp1,gens) limit ts`),
  (* the empty Block is a Data root, so the heap does not change at
     all: what the invariant asks of the new stack is what it asked
     of the old one, because blocks_unique says nothing of a Block
     whose payload is empty, the timestamps only grow, and the
     Block holds no reference *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   (* the witness that an assumption names *)
   let gv n =
     W(fun (asl,_) ->
       let tms = itlist (fun (_,th) acc ->
                   union (frees(concl th)) acc) asl [] in
       EXISTS_TAC (find (fun t -> fst(dest_var t) = n) tms)) in
   (* an empty Block holds no reference, so what the stack with it
      in front reaches is what the stack reaches *)
   let rr_nil = prove
    (`!stack refs n t tag.
        reachable_refs (Block t tag [] :: stack) refs n
        ==> reachable_refs stack refs n`,
     REWRITE_TAC[reachable_refs_def; MEM] THEN REPEAT GEN_TAC THEN
     DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THENL
      [FIRST_X_ASSUM SUBST_ALL_TAC THEN
       FIRST_X_ASSUM(fun m ->
         CONTR_TAC(REWRITE_RULE[get_refs_def; MAP; FLAT; MEM] m));
       MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
       ASM_REWRITE_TAC[]]) in
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   STRIP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
    [(* the new root is a Data, so the pointers are the old ones *)
     USE_CHANGED [roots_ok_def] THEN
     REWRITE_TAC[roots_ok_def; MEM;
                 distinctness "heap_address"];
     ALL_TAC] THEN
   gv "f" THEN gv "tf" THEN ASM_REWRITE_TAC[] THEN
   REPEAT CONJ_TAC THENL
    [(* the timestamps of the stack grow by the Block's own *)
     FIRST_ASSUM(fun sub ->
       let t = rand(concl sub) in
       if hd_is "all_ts" t
       then MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC t THEN
            CONJ_TAC THENL [ACCEPT_TAC sub; ALL_TAC]
       else fail()) THEN
     REWRITE_TAC[all_ts_cons; APPEND; SUBSET; IN_INSERT] THEN
     GEN_TAC THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
     (* blocks_unique says nothing of a Block whose payload is
        empty *)
     REWRITE_TAC[all_vs_Block; APPEND] THEN
     FIRST_ASSUM(fun bu ->
       if hd_is "blocks_unique" (concl bu) then MP_TAC bu
       else fail()) THEN
     REWRITE_TAC[blocks_unique_def; IN_INSERT;
                 injectivity "dataSem_v"] THEN
     DISCH_TAC THEN REPEAT GEN_TAC THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN TRY CONTRA_TAC THEN
     FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
     (* and its root is the BlockNil word of its tag *)
     REWRITE_TAC[ALL2; v_inv_def] THEN ASM_REWRITE_TAC[];
     (* a reference that the new stack reaches the old one reaches,
        because the Block holds none *)
     GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
     CONJ_TAC THENL
      [FIRST_ASSUM(fun rr ->
         if not (hd_is "reachable_refs" (concl rr)) then fail() else
         MATCH_ACCEPT_TAC(MATCH_MP rr_nil rr));
       FIRST_ASSUM ACCEPT_TAC]]));;

