(* [local] *)
let ref_edge_ValueArray = prove
 (`ref_edge (insert ptr (ValueArray xs) refs) x y =
     (if x = ptr then MEM y (get_refs (Block 0 ARB xs)) else
       ref_edge refs x y)`,
  (REWRITE_TAC[ref_edge_def; lookup_insert] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[]));;

(* [local] *)
let ref_edge_Thunk = prove
 (`ref_edge (insert ptr (Thunk ev v) refs) x y =
     (if x = ptr then MEM y (get_refs (Block 0 ARB [v])) else
       ref_edge refs x y)`,
  (REWRITE_TAC[ref_edge_def; lookup_insert] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_UPDATE = prove
 (cake_as_vars (fun () ->
    `reachable_refs (xs ++ (RefPtr b ptr :: stack)) (insert ptr
  (ValueArray xs) refs) n ==>
       reachable_refs (xs ++ (RefPtr b ptr :: stack)) refs n`),
  (* induction along the reflexive transitive closure: an edge of
     the new references is one of the old ones, or it leaves ptr
     and lands in the array, whose values are roots of their own
     (they are the xs at the front of the stack) *)
  (let rtcpath = prove
    (`!r1 n.
        RTC (ref_edge (insert ptr (ValueArray xs) refs)) r1 n ==>
        RTC (ref_edge refs) r1 n \/
        (?s. MEM s (get_refs (Block 0 ARB xs)) /\
             RTC (ref_edge refs) s n)`,
     MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
      [GEN_TAC THEN DISJ1_TAC THEN
       MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
       REPEAT GEN_TAC THEN REWRITE_TAC[ref_edge_ValueArray] THEN
       COND_CASES_TAC THEN STRIP_TAC THEN
       ASM_MESON_TAC[RTC_RULES]]) in
   let mem_block_refs = prove
    (`!(ys:(dataSem_v)list) ss tt aa.
        MEM ss (get_refs (Block tt aa ys))
        ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   REWRITE_TAC[reachable_refs_def] THEN
   DISCH_THEN(X_CHOOSE_THEN `x:dataSem_v`
     (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC)) THEN
   FIRST_ASSUM(fun rtc -> MP_TAC(MATCH_MP rtcpath rtc)) THEN
   DISCH_THEN(DISJ_CASES_THEN2
     (fun old ->
        MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
        ASM_REWRITE_TAC[old])
     (X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)) THEN
   FIRST_ASSUM(fun m -> MP_TAC(MATCH_MP mem_block_refs m)) THEN
   DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v` STRIP_ASSUME_TAC) THEN
   MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `s:num`] THEN
   ASM_REWRITE_TAC[MEM_APPEND]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_Thunk_UPDATE = prove
 (cake_as_vars (fun () ->
    `reachable_refs (v :: RefPtr b ptr :: stack) (insert ptr (Thunk ev
  v) refs) n ==>
       reachable_refs (v :: RefPtr b ptr :: stack) refs n`),
  (* the same, with the thunk's value for the array: the payload of
     the edge that leaves ptr is the one value v, which is the
     root at the front of the stack *)
  (let rtcpath = prove
    (`!r1 n.
        RTC (ref_edge (insert ptr (Thunk ev v) refs)) r1 n ==>
        RTC (ref_edge refs) r1 n \/
        (?s. MEM s (get_refs v) /\ RTC (ref_edge refs) s n)`,
     MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
      [GEN_TAC THEN DISJ1_TAC THEN
       MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
       REPEAT GEN_TAC THEN REWRITE_TAC[ref_edge_Thunk] THEN
       REWRITE_TAC[get_refs_def; MAP; FLAT; APPEND_NIL] THEN
       COND_CASES_TAC THEN STRIP_TAC THEN
       ASM_MESON_TAC[RTC_RULES]]) in
   REWRITE_TAC[reachable_refs_def] THEN
   DISCH_THEN(X_CHOOSE_THEN `x:dataSem_v`
     (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC)) THEN
   FIRST_ASSUM(fun rtc -> MP_TAC(MATCH_MP rtcpath rtc)) THEN
   DISCH_THEN(DISJ_CASES_THEN2
     (fun old ->
        MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
        ASM_REWRITE_TAC[old])
     (X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)) THEN
   MAP_EVERY EXISTS_TAC [`v:dataSem_v`; `s:num`] THEN
   ASM_REWRITE_TAC[MEM]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_UPDATE1 = prove
 (cake_as_vars (fun () ->
    `reachable_refs (xs ++ (RefPtr b ptr :: stack)) (insert ptr
  (ValueArray xs1) refs) n ==>
       (!v. MEM v xs1 ==> ~(MEM v xs) ==> (?xs2. (lookup ptr refs =
         SOME (ValueArray xs2)) /\ MEM v xs2)) ==>
       reachable_refs (xs ++ (RefPtr b ptr :: stack)) refs n`),
  (* the array that is written is not the stack's xs here, so a
     value of it that was not on the stack has to have sat in the
     old array at ptr -- and then the edge that leaves ptr is an
     edge of the old references too, with ptr itself as the root *)
  (let rtcpath = prove
    (`!r1 n.
        RTC (ref_edge (insert ptr (ValueArray xs1) refs)) r1 n ==>
        RTC (ref_edge refs) r1 n \/
        (?s. MEM s (get_refs (Block 0 ARB xs1)) /\
             RTC (ref_edge refs) s n)`,
     MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
      [GEN_TAC THEN DISJ1_TAC THEN
       MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
       REPEAT GEN_TAC THEN REWRITE_TAC[ref_edge_ValueArray] THEN
       COND_CASES_TAC THEN STRIP_TAC THEN
       ASM_MESON_TAC[RTC_RULES]]) in
   let mem_block_refs = prove
    (`!(ys:(dataSem_v)list) ss tt aa.
        MEM ss (get_refs (Block tt aa ys))
        ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   let oldedge = prove
    (`!xs2 s. (lookup ptr refs = SOME (ValueArray xs2)) /\
              MEM s (get_refs (Block 0 ARB xs2))
              ==> ref_edge refs ptr s`,
     REWRITE_TAC[ref_edge_def] THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[]) in
   REWRITE_TAC[reachable_refs_def] THEN
   DISCH_THEN(X_CHOOSE_THEN `x:dataSem_v`
     (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC)) THEN
   DISCH_TAC THEN
   FIRST_ASSUM(fun rtc -> MP_TAC(MATCH_MP rtcpath rtc)) THEN
   DISCH_THEN(DISJ_CASES_THEN2
     (fun old ->
        MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
        ASM_REWRITE_TAC[old])
     (X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)) THEN
   FIRST_ASSUM(fun m -> MP_TAC(MATCH_MP mem_block_refs m)) THEN
   DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v` STRIP_ASSUME_TAC) THEN
   ASM_CASES_TAC `MEM (yy:dataSem_v) xs` THENL
    [MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `s:num`] THEN
     ASM_REWRITE_TAC[MEM_APPEND];
     FIRST_X_ASSUM(fun side ->
       MP_TAC(MATCH_MP (MATCH_MP side (ASSUME `MEM (yy:dataSem_v)
         xs1`)) (ASSUME `~(MEM (yy:dataSem_v) xs)`))) THEN
     DISCH_THEN(X_CHOOSE_THEN `xs2:(dataSem_v)list`
       STRIP_ASSUME_TAC) THEN
     MAP_EVERY EXISTS_TAC
       [`RefPtr b ptr:dataSem_v`; `ptr:num`] THEN
     REWRITE_TAC[MEM_APPEND; MEM; get_refs_def] THEN
     MATCH_MP_TAC(CONJUNCT2(SPEC_ALL RTC_RULES)) THEN
     EXISTS_TAC `s:num` THEN ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC oldedge THEN EXISTS_TAC `xs2:(dataSem_v)list` THEN
     CONJ_TAC THENL
      [FIRST_ASSUM ACCEPT_TAC;
       REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
       EXISTS_TAC `get_refs (yy:dataSem_v)` THEN CONJ_TAC THENL
        [EXISTS_TAC `yy:dataSem_v` THEN ASM_REWRITE_TAC[];
         FIRST_ASSUM ACCEPT_TAC]]]));;

let v_inv_ByteArray_insert_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
       (ptr IN domain refs ==> (?a b. lookup ptr refs = SOME
         (ByteArray a b))) ==>
         v_inv_ck ck conf v1 (insert ptr (ByteArray fl xs) refs)
           (y,f,tf,heap)`,
  (* the refs that the lemma puts a byte array into: v_inv reads
     the cell at ptr to see whether it is a thunk, to annotate a
     pointer to it and in the dest_thunk of a value, and a byte
     array is no thunk and no MutBlock, as what was there is not
     either *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`(ptr IN domain refs ==>
       ?a b. lookup ptr refs = SOME (ByteArray a b)) ==>
      (!k ev v.
         lookup k (insert ptr (ByteArray fl xs) refs) =
           SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ref_ptr_annot conf
             (lookup k (insert ptr (ByteArray fl xs) refs)) =
           ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v refs = NotThunk ==>
           dest_thunk v (insert ptr (ByteArray fl xs) refs) =
             NotThunk) /\
      (!k bb.
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (ByteArray fl xs) refs) =
              SOME (bvlSem_MutBlock t2 g2 m2 d2 s2) ==> ~bb))`,
     DISCH_TAC THEN
     (* the cell at ptr is a byte array, or the refs have no cell
        there: the two are what the rules of a RefPtr read *)
     (SUBGOAL_THEN
       `lookup ptr (refs:(dataSem_v bvlSem_ref) spt) = NONE \/
        ?a b. lookup ptr refs = SOME (ByteArray a b)`
       STRIP_ASSUME_TAC THENL
      [FIRST_ASSUM(fun h ->
         let d = lhand(concl h) in
         ASM_CASES_TAC d THENL
          [DISJ2_TAC THEN MATCH_ACCEPT_TAC(MP h (ASSUME d));
           DISJ1_TAC THEN
           MATCH_ACCEPT_TAC(MATCH_MP no_lk (ASSUME(mk_neg d)))]);
       ALL_TAC; ALL_TAC]) THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[ref_ptr_annot_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
       TRY(CONV_TAC TAUT);
       REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
       REWRITE_TAC[lookup_insert] THEN COND_CASES_TAC THEN
       ASM_REWRITE_TAC(opt @ rfs) THEN
       TRY(FIRST_ASSUM MATCH_ACCEPT_TAC)])) in
   V_INV_REFS_TAC ALL_TAC ALL_TAC (V_INV_REFS_PLAIN same)
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

let v_inv_ByteArray_insert = prove
 (`!conf v1 refs v2 f tf heap ptr fl xs.
     v_inv conf v1 refs (v2,f,tf,heap) /\
     (ptr IN domain refs ==> (?a b. lookup ptr refs = SOME (ByteArray
       a b))) ==>
       v_inv conf v1 (insert ptr (ByteArray fl xs) refs)
         (v2,f,tf,heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_ByteArray_insert_lemma]));;

let isRefBlock_def = cake_define
  `isRefBlock x = (?p. x = RefBlock p)`;;

let RefBlock_inv_def = cake_define
  `RefBlock_inv heap heap2 <=>
     (!n x. (heap_lookup n heap = SOME x) /\ ~(isRefBlock x) ==>
            (heap_lookup n heap2 = SOME x)) /\
     (!n x. (heap_lookup n heap2 = SOME x) /\ ~(isRefBlock x) ==>
            (heap_lookup n heap = SOME x))`;;

let heap_store_RefBlock_thm = prove
 (`!ha. (LENGTH x = LENGTH y) ==>
         (heap_store (heap_length ha) [RefBlock x] (ha ++ (RefBlock y
           :: hb)) =
           (ha ++ (RefBlock x :: hb),T))`,
  (* heap_store_lemma stores at the length of the prefix, and the
     condition it leaves is that the two RefBlocks are of a length *)
  (let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   GEN_TAC THEN DISCH_TAC THEN
   REWRITE_TAC[heap_store_lemma; APPEND; PAIR_EQ; hlen_cl;
               RefBlock_def; el_length_def] THEN
   ASM_ARITH_TAC));;

(* [local] *)
let heap_lookup_RefBlock_lemma = prove
 (`(heap_lookup n (ha ++ (RefBlock y :: hb)) = SOME x) =
       (if n < heap_length ha then
         (heap_lookup n ha = SOME x) else if n = heap_length ha then
         (x = RefBlock y) else if heap_length ha + (LENGTH y + 1) <=
           n then
         (heap_lookup (n - heap_length ha - (LENGTH y + 1)) hb =
           SOME x) else F)`,
  (* the lookup in the append is the one in ha or the one in the
     RefBlock and what follows it, and a RefBlock is LENGTH y + 1
     long *)
  (REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
               heap_lookup_def; RefBlock_def;
               el_length_def] THEN
   REPEAT COND_CASES_TAC THEN
   ASM_REWRITE_TAC[injectivity "option"; distinctness "option"] THEN
   TRY(POP_ASSUM_LIST(fun ths ->
     MP_TAC(end_itlist CONJ (rev ths))) THEN ARITH_TAC) THEN
   TRY(MATCH_ACCEPT_TAC EQ_SYM_EQ) THEN
   REWRITE_TAC[]));;

(* [local] *)
let heap_store_RefBlock = prove
 (`(LENGTH y = LENGTH h) /\
     (heap_lookup n heap = SOME (RefBlock y)) ==>
     (?heap2. (heap_store n [RefBlock h] heap = (heap2,T)) /\
             RefBlock_inv heap heap2 /\
             (heap_lookup n heap2 = SOME (RefBlock h)) /\
             (heap_length heap2 = heap_length heap) /\
             (FILTER isForwardPointer heap2 = FILTER isForwardPointer
               heap) /\
             (!xs l d.
                MEM (DataElement xs l d) heap2 ==> (DataElement xs l
                  d = RefBlock h) \/
                              MEM (DataElement xs l d) heap) /\
             (!a. isSomeDataElement (heap_lookup a heap2) =
                  isSomeDataElement (heap_lookup a heap)) /\
             (!m x. ~(m = n) /\ (heap_lookup m heap = SOME x) ==>
                   (heap_lookup m heap2 = SOME x)))`,
  (* a store into a RefBlock: heap_lookup_SPLIT cuts the heap at
     the element, heap_store_RefBlock_thm does the store, and
     heap_lookup_RefBlock_lemma says where an address falls -- in
     the part before the element, at the element itself, or past
     it -- which is the same of both heaps, because the two
     RefBlocks are of a length.  So the two heaps have the same
     length, the same forward pointers and the same data elements
     but the one stored into, their lookups agree away from it,
     and a RefBlock_inv holds, because an element that is not a
     RefBlock is not the one that changed *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    (* the clauses of heap_length *)
    let hlen_cl = prove
     (`heap_length [] = 0 /\
       (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
      REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
    (* a RefBlock is one *)
    let isrb = prove
     (`!p. isRefBlock (RefBlock p)`,
      REWRITE_TAC[isRefBlock_def] THEN MESON_TAC[]) in
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    FIRST_ASSUM(fun hl ->
      MP_TAC(MATCH_MP heap_lookup_SPLIT hl)) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "APPEND" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "heap_length" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    W(fun (asl,w) ->
      let hs = find_term (hd_is "heap_store") (snd(strip_exists w)) in
      let args = snd(strip_comb hs) in
      let nb = lhand (el 1 args) in
      let hp = el 2 args in
      let ap = rator (rator hp) in
      let rest = rand hp in
      let cs = rator (rator rest) in
      EXISTS_TAC (mk_comb(mk_comb(ap,lhand hp),
                          mk_comb(mk_comb(cs,nb),rand rest)))) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC heap_store_RefBlock_thm THEN
      FIRST_ASSUM(ACCEPT_TAC o SYM);
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[RefBlock_inv_def;
                  heap_lookup_RefBlock_lemma] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THEN REPEAT GEN_TAC THEN
      REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
      STRIP_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      REPEAT(FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) && is_var (lhs (concl e)) &&
           hd_is "RefBlock" (rhs (concl e))
        then SUBST_ALL_TAC e else fail())) THEN
      RULE_ASSUM_TAC(REWRITE_RULE[isrb]) THEN
      FIRST_X_ASSUM CONTR_TAC;
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_lookup_RefBlock_lemma; LT_REFL];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_length_APPEND; hlen_cl;
                  RefBlock_def; el_length_def] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[FILTER_APPEND; FILTER; isForwardPointer_def;
                  RefBlock_def] THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[MEM_APPEND; MEM] THEN MESON_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [GEN_TAC THEN
      REWRITE_TAC[isSomeDataElement_def] THEN
      REWRITE_TAC[heap_lookup_RefBlock_lemma] THEN
      ASM_REWRITE_TAC[] THEN
      REPEAT COND_CASES_TAC THEN
      REWRITE_TAC[RefBlock_def] THEN MESON_TAC[];
      ALL_TAC] THEN
    REPEAT GEN_TAC THEN
    REWRITE_TAC[heap_lookup_RefBlock_lemma] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]));;

(* [local] *)
let NOT_isRefBlock = prove
 (`~(isRefBlock (Bignum x)) /\
     ~(isRefBlock (Word64Rep a w)) /\
     ~(isRefBlock (DataElement xs (LENGTH xs) (BlockTag n,[])))`,
  (* the tag of a RefBlock is RefTag, and the three shapes have
     another one; the conditional of Word64Rep is split after the
     first rewrite, so the injectivity is used again under it *)
  (let rws = [injectivity "heap_element"; PAIR_EQ;
              distinctness "data_to_word_memoryProof_tag"] in
   REWRITE_TAC[isRefBlock_def; RefBlock_def;
               bignum_def; cake_raw "Word64Rep"] THEN
   PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC rws THEN
   REPEAT CONJ_TAC THEN TRY COND_CASES_TAC THEN
   REWRITE_TAC rws));;

(* [local] *)
let v_inv_Ref_lemma = prove
 (`!ck w refs x f tf heap.
     v_inv conf w refs (x,f,tf,heap) /\
     RefBlock_inv heap heap2 ==>
       v_inv_ck ck conf w refs (x,f,tf,heap) = v_inv_ck ck conf w
         refs (x,f,tf,heap2)`,
  (* the two heaps agree on every element that is no RefBlock, and
     the elements that the relation looks up are none of them: so
     one direction of the equation is the induction with that
     carried over, and the other is the hypothesis itself, which
     says the relation holds at the old heap for every clock *)
  ((* the two heaps agree on every element that is no RefBlock, and
      the elements that the relation looks up are none *)
   let hp =
     FIRST_ASSUM(fun rb ->
       let (f1,_) = CONJ_PAIR (REWRITE_RULE[RefBlock_inv_def] rb) in
       MATCH_MP_TAC f1 THEN CONJ_TAC THENL
        [FIRST_ASSUM MATCH_ACCEPT_TAC;
         REWRITE_TAC[isRefBlock_def; RefBlock_def; BlockRep_def;
                     bignum_def; Word64Rep_def; ThunkBlock_def] THEN
         CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
         TRY PAIRARG_TAC THEN
         CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
         TRY COND_CASES_TAC THEN
         REWRITE_TAC[injectivity "heap_element"; PAIR_EQ;
                     distinctness "data_to_word_memoryProof_tag"] THEN
         REWRITE_TAC[NOT_EXISTS_THM; DE_MORGAN_THM]]) in
   (* one direction of the equation: the relation at the new heap *)
   let dir = prove
    (`!ck w refs x f tf heap.
        v_inv conf w refs (x,f,tf,heap) /\ RefBlock_inv heap heap2
        ==> v_inv_ck ck conf w refs (x,f,tf,heap2)`,
     V_INV_REFS_TAC ALL_TAC hp V_INV_HEAP_PLAIN
       (V_INV_HEAP_THUNK hp 5) (V_INV_HEAP_THUNK hp 6)) in
   (* and the other one is the hypothesis itself, which says the
      relation holds at the old heap for every clock *)
   REPEAT GEN_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
   EQ_TAC THEN DISCH_THEN(K ALL_TAC) THENL
    [FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun rb ->
       MATCH_ACCEPT_TAC(SPEC_ALL(MATCH_MP dir (CONJ vi rb)))));
     FIRST_ASSUM(fun vi ->
       MATCH_ACCEPT_TAC(SPEC_ALL(REWRITE_RULE[v_inv_eq] vi)))]));;

(* [local] *)
let v_inv_Ref = prove
 (`RefBlock_inv heap heap2 ==>
     (!x h f tf. (v_inv conf x refs (h,f,tf,heap2) =
                 v_inv conf x refs (h,f,tf,heap)))`,
  (* v_inv_Ref_lemma says that the clocked relation does not see the
     difference between the two heaps, of a value that the relation
     holds of; the unclocked one is the clocked one at every clock,
     so each side gives the other.  The lemma's heap2 is a free
     variable, so the other direction is the lemma with the two
     heaps exchanged, and RefBlock_inv is symmetric *)
  (let lem = v_inv_Ref_lemma in
   let hp = find_term (fun t -> is_var t && fst(dest_var t) = "heap")
              (concl lem) in
   let hp2 = find_term
               (fun t -> is_var t && fst(dest_var t) = "heap2")
               (concl lem) in
   let swapped = INST [hp2,hp; hp,hp2] lem in
   let sym_rb = prove
    (`!h1 h2. RefBlock_inv h1 h2 ==> RefBlock_inv h2 h1`,
     REWRITE_TAC[RefBlock_inv_def] THEN MESON_TAC[]) in
   let step lemm rbt =
     ONCE_REWRITE_TAC[v_inv_eq] THEN
     FIRST_ASSUM(fun rb -> FIRST_ASSUM(fun vi ->
       let th = MATCH_MP lemm (CONJ vi (rbt rb)) in
       let ckv = find_term
                   (fun t -> is_var t && fst(dest_var t) = "ck")
                   (concl th) in
       MP_TAC(GEN ckv th))) THEN
     DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
     FIRST_ASSUM(fun vi -> ACCEPT_TAC(REWRITE_RULE[v_inv_eq] vi)) in
   DISCH_TAC THEN REPEAT GEN_TAC THEN EQ_TAC THEN DISCH_TAC THENL
    [step swapped (MATCH_MP sym_rb);
     step lem (fun th -> th)]));;

let v_inv_ValueArray_insert_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
       RefBlock_inv heap heap2 /\
       (ptr IN domain refs ==> (?as. lookup ptr refs = SOME
         (ValueArray as))) ==>
         v_inv_ck ck conf v1 (insert ptr (ValueArray xs) refs)
           (y,f,tf,heap)`,
  (* the same of an array of values, whose annotation is zero as
     well.  The hypothesis about the cell at ptr is the second
     conjunct of what the lemma assumes, and prep gives it by
     itself *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`(ptr IN domain refs ==>
       ?as. lookup ptr refs = SOME (ValueArray as)) ==>
      (!k ev v.
         lookup k (insert ptr (ValueArray xs) refs) =
           SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ref_ptr_annot conf
             (lookup k (insert ptr (ValueArray xs) refs)) =
           ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v refs = NotThunk ==>
           dest_thunk v (insert ptr (ValueArray xs) refs) =
             NotThunk) /\
      (!k bb.
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (ValueArray xs) refs) =
              SOME (bvlSem_MutBlock t2 g2 m2 d2 s2) ==> ~bb))`,
     DISCH_TAC THEN
     (* the cell at ptr is an array of values, or the refs have no
        cell there: the two are what the rules of a RefPtr read *)
     (SUBGOAL_THEN
       `lookup ptr (refs:(dataSem_v bvlSem_ref) spt) = NONE \/
        ?as. lookup ptr refs = SOME (ValueArray as)`
       STRIP_ASSUME_TAC THENL
      [FIRST_ASSUM(fun h ->
         let d = lhand(concl h) in
         ASM_CASES_TAC d THENL
          [DISJ2_TAC THEN MATCH_ACCEPT_TAC(MP h (ASSUME d));
           DISJ1_TAC THEN
           MATCH_ACCEPT_TAC(MATCH_MP no_lk (ASSUME(mk_neg d)))]);
       ALL_TAC; ALL_TAC]) THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[ref_ptr_annot_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
       TRY(CONV_TAC TAUT);
       REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
       REWRITE_TAC[lookup_insert] THEN COND_CASES_TAC THEN
       ASM_REWRITE_TAC(opt @ rfs) THEN
       TRY(FIRST_ASSUM MATCH_ACCEPT_TAC)])) in
   let prep = FIRST_ASSUM(fun a -> ASSUME_TAC(CONJUNCT2 a)) in
   V_INV_REFS_TAC prep ALL_TAC (V_INV_REFS_PLAIN same)
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

let v_inv_ValueArray_insert = prove
 (`!conf v1 refs v2 f tf heap ptr xs heap2.
     RefBlock_inv heap heap2 /\
     v_inv conf v1 refs (v2,f,tf,heap) /\
     (ptr IN domain refs ==> (?as. lookup ptr refs = SOME (ValueArray
       as))) ==>
       v_inv conf v1 (insert ptr (ValueArray xs) refs)
         (v2,f,tf,heap2)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_ValueArray_insert_lemma;
                 v_inv_Ref]));;

(* inserting a *fresh* MutBlock ref cannot disturb any existing v_inv: the only
   way v_inv inspects refs is through a RefPtr, and those are confined to
   FDOM f, which sits inside domain refs *)
let v_inv_MutBlock_insert_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
     ~(ptr IN domain refs) /\ FDOM f SUBSET domain refs ==>
       v_inv_ck ck conf v1 (insert ptr (bvlSem_MutBlock tag fin l
         cv r) refs) (y,f,tf,heap)`,
  (* here the cell is put at a key that the refs do not have, so a
     MutBlock appears where there was nothing: the annotation of a
     pointer and the condition of a plain reference are the old
     ones away from ptr, and a pointer of the relation is a key of
     f, which is a key of the refs *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`lookup ptr refs = NONE ==>
      (!k ev v.
         lookup k (insert ptr (bvlSem_MutBlock tag fin l cv r)
           refs) = SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ~(k = ptr) ==>
         ref_ptr_annot conf
           (lookup k (insert ptr (bvlSem_MutBlock tag fin l cv r)
             refs)) =
         ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v refs = NotThunk ==>
           dest_thunk v (insert ptr
             (bvlSem_MutBlock tag fin l cv r) refs) = NotThunk) /\
      (!k bb.
         ~(k = ptr) /\
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (bvlSem_MutBlock tag fin l cv r)
              refs) = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
                ==> ~bb))`,
     DISCH_TAC THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       REPEAT STRIP_TAC THEN REWRITE_TAC[lookup_insert] THEN
       ASM_REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
       TRY(CONV_TAC TAUT);
       REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
       REWRITE_TAC[lookup_insert] THEN ASM_REWRITE_TAC[] THEN
       TRY(FIRST_ASSUM MATCH_ACCEPT_TAC)])) in
   let prep =
     FIRST_ASSUM(fun ds ->
       ASSUME_TAC(MATCH_MP no_lk (CONJUNCT1 ds)) THEN
       ASSUME_TAC(REWRITE_RULE[SUBSET] (CONJUNCT2 ds))) in
   let d5 =
     REPEAT SUBST_LHS_TAC THEN
     FIRST_ASSUM(fun nolk ->
       let (t_eq,a_eq,_,m_imp) = v_inv_refs_parts same nolk in
       FIRST_ASSUM(fun sub -> FIRST_ASSUM(fun fd ->
         let np = MATCH_MP notptr (CONJ nolk (CONJ sub fd)) in
         REWRITE_TAC[GSYM (MATCH_MP a_eq np)] THEN
         MATCH_MP_TAC(el 4 v_inv_ck_rules) THEN
         REPEAT CONJ_TAC THENL
          [FIRST_ASSUM MATCH_ACCEPT_TAC;
           ASM_REWRITE_TAC[t_eq];
           MATCH_MP_TAC m_imp THEN CONJ_TAC THENL
            [ACCEPT_TAC np; FIRST_ASSUM MATCH_ACCEPT_TAC]]))) in
   V_INV_REFS_TAC prep ALL_TAC d5
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

let v_inv_MutBlock_insert = prove
 (`!conf v1 refs v2 f tf heap ptr tag fin l cv r.
     v_inv conf v1 refs (v2,f,tf,heap) /\
     ~(ptr IN domain refs) /\ FDOM f SUBSET domain refs ==>
       v_inv conf v1 (insert ptr (bvlSem_MutBlock tag fin l cv r)
         refs) (v2,f,tf,heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_MutBlock_insert_lemma]));;

(* v_inv cannot see a MutBlock's finalised flag: ref_ptr_annot ignores it and
   dest_thunk sends every MutBlock to NotThunk.  Flipping the flag therefore
   preserves v_inv -- this is what makes FinaliseCons a no-op at word level. *)
(* [local] *)
let v_inv_MutBlock_fin_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
     lookup ptr refs = SOME (bvlSem_MutBlock tag fin1 ll cv rr) ==>
       v_inv_ck ck conf v1 (insert ptr (bvlSem_MutBlock tag fin2 ll
         cv rr) refs)
         (y,f,tf,heap)`,
  (* the cell at ptr keeps its tag and its payload, so all four
     lookups of the new refs are the old ones: the annotation is
     the ptr_bits of the tag and the two lengths, which the flag
     does not enter, and a MutBlock is no thunk *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`lookup ptr refs = SOME (bvlSem_MutBlock tag fin1 ll cv rr) ==>
      (!k ev v.
         lookup k (insert ptr (bvlSem_MutBlock tag fin2 ll cv rr)
           refs) = SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ref_ptr_annot conf
             (lookup k (insert ptr
               (bvlSem_MutBlock tag fin2 ll cv rr) refs)) =
           ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v (insert ptr
             (bvlSem_MutBlock tag fin2 ll cv rr) refs) =
           dest_thunk v refs) /\
      (!k bb.
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (bvlSem_MutBlock tag fin2 ll cv rr)
              refs) = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
                ==> ~bb))`,
     DISCH_TAC THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[ref_ptr_annot_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[];
       REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
       (REWRITE_TAC[lookup_insert] THEN COND_CASES_TAC THENL
         [FIRST_X_ASSUM SUBST_ALL_TAC THEN
          DISCH_THEN(K ALL_TAC) THEN
          FIRST_ASSUM(fun a -> FIRST_ASSUM(fun lk ->
            ACCEPT_TAC(MATCH_MP a lk)));
          FIRST_ASSUM MATCH_ACCEPT_TAC])])) in
   V_INV_REFS_TAC ALL_TAC ALL_TAC (V_INV_REFS_PLAIN same)
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

(* bound variables deliberately avoid the names used at the use sites, so that
   irule/MATCH_MP_TAC does not fail on a free/bound name clash *)
let v_inv_MutBlock_fin = prove
 (`!cnf vv rfs yy ff tff hp pp tg b1 b2 l1 c1 r1.
     v_inv cnf vv rfs (yy,ff,tff,hp) /\
     lookup pp rfs = SOME (bvlSem_MutBlock tg b1 l1 c1 r1) ==>
       v_inv cnf vv (insert pp (bvlSem_MutBlock tg b2 l1 c1 r1)
         rfs) (yy,ff,tff,hp)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_MutBlock_fin_lemma]));;

(* ---- MutCons: the Cons allocation, but the value handed back is a fresh ref *)

(* [local] *)
let all_ts_SUBSET_gen = prove
 (`(!x. ((?n r'. lookup n refs1 = SOME r' /\ find_ref r' x) \/ MEM x
  stack1) ==>
        ((?n r'. lookup n refs2 = SOME r' /\ find_ref r' x) \/ MEM x
          stack2)) ==>
   all_ts refs1 stack1 SUBSET all_ts refs2 stack2`,
  (REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]));;

(* like all_ts_SUBSET_gen, but the witness on the right may be a different
   value, as long as it carries the timestamp -- needed when a value only
   survives inside a newly built Block *)
(* [local] *)
let all_ts_SUBSET_ts = prove
 (`(!x t. (((?n r'. lookup n refs1 = SOME r' /\ find_ref r' x) \/ MEM x
  stack1) /\
           MEM t (v_all_ts x)) ==>
          (?x'. ((?n r'. lookup n refs2 = SOME r' /\ find_ref r' x')
            \/
                MEM x' stack2) /\ MEM t (v_all_ts x'))) ==>
   all_ts refs1 stack1 SUBSET all_ts refs2 stack2`,
  (REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let all_ts_mutcons = prove
 (cake_as_vars (fun () ->
    `~(ptr IN domain refs) ==>
       all_ts refs ((l ++ [c] ++ r) ++ stack) SUBSET
       all_ts (insert ptr (bvlSem_MutBlock tag F l c r) refs)
         (RefPtr F ptr :: stack)`),
  (* every value that the old refs and stack reach is reached by the
     new ones: one of the refs is not the fresh pointer, because the
     fresh one has no value in refs at all, and the three parts of
     the MutBlock are what find_ref gives of it *)
  (let fr = prove
    (`!tg fin l c r x.
        find_ref (bvlSem_MutBlock tg fin l c r) x <=>
        MEM x l \/ x = c \/ MEM x r`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [find_ref_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[MEM_APPEND; MEM]) in
   let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN
     CONV_TAC TAUT) in
   DISCH_THEN(fun hyp ->
     MATCH_MP_TAC all_ts_SUBSET_gen THEN GEN_TAC THEN
     REWRITE_TAC[MEM_APPEND; MEM; li] THEN
     MESON_TAC[fr; REWRITE_RULE[GSYM lookup_NONE_domain] hyp;
               distinctness "option"])));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_mutcons = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs ((l ++ [c] ++ r) ++ stack)) ==>
     blocks_unique ts
       (all_vs (insert ptr (bvlSem_MutBlock tag F l c r) refs)
         (RefPtr F ptr :: stack))`),
  (* a Block of the new refs and stack is one of the old ones: the
     MutBlock at the fresh pointer holds the values that the old
     stack has in front of it, and the RefPtr is no Block *)
  (let vrefptr = prove
    (`!b p ys. v_all_vs (CONS (RefPtr b p) ys) =
        CONS (RefPtr b p) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let inc = prove
    (`!refs ptr tag l c r stack' t a xs.
        Block t a xs IN
          all_vs (insert ptr (bvlSem_MutBlock tag F l c r) refs)
                 (CONS (RefPtr F ptr) stack') ==>
        Block t a xs IN
          all_vs refs (APPEND (APPEND l (APPEND [c] r)) stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; vrefptr;
                 v_all_vs_append; MEM; MEM_APPEND; li;
                 distinctness "dataSem_v"; distinctness "bvlSem_ref";
                 injectivity "bvlSem_ref"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* [local] *)
let ref_edge_MutBlock = prove
 (`ref_edge (insert ptr (bvlSem_MutBlock tag fin l c r) refs) x y =
     (if x = ptr then MEM y (get_refs (Block 0 ARB (l ++ [c] ++
       r))) else ref_edge refs x y)`,
  (REWRITE_TAC[ref_edge_def; lookup_insert] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[]));;

(* the only new edge leaves ptr and lands inside the payload, which is exactly
   what used to sit on the stack *)
(* [local] *)
let reachable_refs_MutCons_lemma = prove
 (`!r1 n.
     RTC (ref_edge (insert ptr (bvlSem_MutBlock tag F l c r) refs))
       r1 n ==> ~(n = ptr) ==>
     RTC (ref_edge refs) r1 n \/
     (?s. MEM s (get_refs (Block 0 ARB (l ++ [c] ++ r))) /\ RTC
       (ref_edge refs) s n)`,
  (* induction along the reflexive transitive closure: an edge of
     the new refs is one of the old ones, or it leaves ptr and
     lands in the payload of the MutBlock *)
  (MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN DISJ1_TAC THEN
    MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
    REPEAT GEN_TAC THEN
    REWRITE_TAC[ref_edge_MutBlock] THEN
    COND_CASES_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
    ASM_MESON_TAC[RTC_RULES]]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_MutCons = prove
 (cake_as_vars (fun () ->
    `reachable_refs (RefPtr F ptr :: stack)
       (insert ptr (bvlSem_MutBlock tag F l c r) refs) n /\ ~(n =
         ptr) /\ ~(ptr IN domain refs) ==>
     reachable_refs ((l ++ [c] ++ r) ++ stack) refs n`),
  (* reachable_refs_MutCons_lemma says of a path through the new
     references that it is one of the old ones or that it starts
     inside the payload of the MutBlock.  A root of the stack keeps
     its path; the only other root is the pointer to the MutBlock,
     whose path cannot start at all, because ptr is fresh and so has
     no edge; and a path from the payload has its root among the
     payload's values *)
  (
   let mem_block_refs = prove
    (`!(ys:(dataSem_v)list) ss tt aa.
        MEM ss (get_refs (Block tt aa ys))
        ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   let subst_vars =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_eq(concl th) && is_var(lhand(concl th))
       then SUBST_ALL_TAC th else fail())) in
   let payload b =
     X_CHOOSE_THEN `ss:num` (CONJUNCTS_THEN2
       (fun m -> MP_TAC(MATCH_MP mem_block_refs m)) ASSUME_TAC) b THEN
     DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v` STRIP_ASSUME_TAC) THEN
     MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `ss:num`] THEN
     ASM_REWRITE_TAC[MEM_APPEND] in
   let noedge a =
     MP_TAC(ONCE_REWRITE_RULE[RTC_CASES] a) THEN
     FIRST_ASSUM(fun nd ->
       let th = REWRITE_RULE[GSYM lookup_NONE_domain] nd in
       if concl th = concl nd then fail()
       else REWRITE_TAC[ref_edge_def; th]) THEN
     MATCH_REDUCE_TAC THEN ASM_REWRITE_TAC[] in
   let stackcase a =
     ASSUME_TAC a THEN
     W(fun gl -> MAP_EVERY (fun n -> EXISTS_TAC (var_by_name n gl))
                   ["x"; "r'"]) THEN
     ASM_REWRITE_TAC[MEM_APPEND] in
   let uselemma =
     FIRST_ASSUM(fun rtc -> FIRST_ASSUM(fun ne ->
       MP_TAC(MATCH_MP (MATCH_MP
         reachable_refs_MutCons_lemma rtc) ne))) in
   REWRITE_TAC[reachable_refs_def; MEM] THEN STRIP_TAC THENL
    [subst_vars THEN
     RULE_ASSUM_TAC(REWRITE_RULE[get_refs_def; MEM]) THEN
     subst_vars THEN uselemma THEN
     DISCH_THEN(DISJ_CASES_THEN2 noedge payload);
     uselemma THEN DISCH_THEN(DISJ_CASES_THEN2 stackcase payload)]));;

(* lifting a v_inv across the MutCons allocation: refs gains a fresh ref and f
   gains its binding, and the heap only grew *)
(* [local] *)
let v_inv_MutCons_step = prove
 (`v_inv conf v refs (y,f,tf,heap) /\ ~(ptr IN domain refs) /\
   FDOM f SUBSET domain refs /\ heap_store_rel heap heap2 ==>
     v_inv conf v (insert ptr (bvlSem_MutBlock tag F l c r) refs)
       (y,f |+ (ptr,a),tf,heap2)`,
  (* the point is fresh in the references, so it is not in the
     domain of the map and the map is a SUBMAP of its update there;
     v_inv_MutBlock_insert adds the MutBlock to the references and
     v_inv_SUBMAP takes the relation to the bigger map and the
     bigger heap *)
  (
   let submap_fupd = prove
    (`!(g:(A,B)fmap) k v. ~(k IN FDOM g) ==> g SUBMAP (g |+ (k,v))`,
     REWRITE_TAC[SUBMAP; FDOM_FUPDATE; IN_INSERT;
                 FAPPLY_FUPDATE_THM] THEN MESON_TAC[]) in
   STRIP_TAC THEN
   SUBGOAL_THEN `~(ptr IN FDOM (f:(num,num)fmap))` ASSUME_TAC THENL
    [ASM_MESON_TAC[SUBSET]; ALL_TAC] THEN
   FIRST_ASSUM(fun nf -> ASSUME_TAC(MATCH_MP submap_fupd nf)) THEN
   FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun nd -> FIRST_ASSUM(fun sub ->
     ASSUME_TAC(MATCH_MP v_inv_MutBlock_insert
       (CONJ vi (CONJ nd sub)))))) THEN
   MATCH_MP_TAC (GEN_ALL v_inv_SUBMAP) THEN
   W(fun gl -> MAP_EVERY (fun n -> EXISTS_TAC (var_by_name n gl))
                 ["f"; "tf"; "heap"]) THEN
   ASM_REWRITE_TAC[SUBMAP_REFL]));;

(* [local] *)
let take_el_drop = prove
 (`!index vals. index < LENGTH vals ==>
     TAKE index vals ++ [EL index vals] ++ DROP (index + 1) vals =
       vals`,
  (* DROP_EL_CONS puts the element and the DROP after it back
     together, and TAKE_DROP puts the two halves back together *)
  (REPEAT STRIP_TAC THEN REWRITE_TAC[APPEND] THEN
   FIRST_ASSUM(fun th ->
     MP_TAC(REWRITE_RULE[ADD1] (MATCH_MP DROP_EL_CONS th))) THEN
   DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[TAKE_DROP]));;

(* a value that is not a thunk cannot become one by adding a fresh ref *)
(* [local] *)
let dest_thunk_insert_fresh = prove
 (`~(ptr IN domain refs) /\ dest_thunk v refs = NotThunk ==>
     dest_thunk v (insert ptr x refs) = NotThunk`,
  (* only a RefPtr reads the refs, and at a pointer that the refs
     have no value for the old dest_thunk is BadRef, which the
     assumption says it is not; away from the pointer the lookup is
     the one it was *)
  (let dt_def = dataSem_dest_thunk_def in
   let dtr = [distinctness "dataSem_dest_thunk_ret";
              injectivity "dataSem_dest_thunk_ret"] in
   let opt_rws = [distinctness "option"; injectivity "option"] in
   STRIP_TAC THEN CASES_ON_NAME "v" THEN
   ONCE_REWRITE_TAC[dt_def] THEN
   RULE_ASSUM_TAC(ONCE_REWRITE_RULE[dt_def]) THEN
   SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
   RULE_ASSUM_TAC(REWRITE_RULE[GSYM lookup_NONE_domain]) THEN
   REWRITE_TAC[lookup_insert] THEN
   ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
   EVERY_CASE_TAC THEN ASM_REWRITE_TAC dtr THEN
   REPEAT COND_CASES_TAC THEN
   ASM_MESON_TAC (dtr @ opt_rws)));;

(* mirrors cons_thm_alt: the allocation is the Cons allocation, but the value
   handed back is a RefPtr into refs, so f (not tf) gains a binding and no
   timestamp is consumed *)
(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let mutcons_thm_alt = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (l ++ [c] ++ r ++ stack) refs
                (roots,heap,be,a,sp,sp1,gens) limit ts /\
     LENGTH (l ++ [c] ++ r) < sp /\ ~(ptr IN domain refs) /\
     (!gs. ~(data_to_word_config_gc_kind conf =
       data_to_word_Generational gs)) ==>
     (?rs roots2 heap2.
       (roots = rs ++ roots2) /\ (LENGTH rs = LENGTH (l ++ [c] ++
         r)) /\
       (heap_store_unused_alt a (sp + sp1) (BlockRep tag rs) heap =
         (heap2,T)) /\
       abs_ml_inv conf (RefPtr F ptr :: stack)
         (insert ptr (bvlSem_MutBlock tag F l c r) refs)
         (gc_shared_Pointer a (wordLang_Word (ptr_bits conf tag
           (LENGTH (l ++ [c] ++ r)))) :: roots2,
          heap2,be,a + el_length (BlockRep tag rs),
          sp - el_length (BlockRep tag rs),sp1,gens) limit ts)`),
  (* the attempt: the proof of the source names abs_ml_inv_def,
     bc_stack_ref_inv_def, LIST_REL_SPLIT1, unused_space_inv_def,
     IMP_heap_store_unused_alt, BlockRep_def.  What is here rewrites
     with them and closes by arithmetic, and the cheat is behind it
     until the proof is written.  A MESON over them is what the next
     round adds; it costs a load ten minutes to have it in every
     attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def;
       LIST_REL_SPLIT1; unused_space_inv_def;
       IMP_heap_store_unused_alt; BlockRep_def] THEN
     TRY ASM_ARITH_TAC)));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let mutcons_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ stack) refs (roots,heap,be,a,sp,sp1,gens)
  limit ts /\
     LENGTH xs < sp /\ index < LENGTH xs /\ ~(ptr IN domain refs)
       /\
     (!gs. ~(data_to_word_config_gc_kind conf =
       data_to_word_Generational gs)) ==>
     (?rs roots2 heap2.
       (roots = rs ++ roots2) /\ (LENGTH rs = LENGTH xs) /\
       (heap_store_unused_alt a (sp + sp1) (BlockRep tag rs) heap =
         (heap2,T)) /\
       abs_ml_inv conf (RefPtr F ptr :: stack)
         (insert ptr (bvlSem_MutBlock tag F (TAKE index xs) (EL
           index xs)
                              (DROP (index + 1) xs)) refs)
         (gc_shared_Pointer a (wordLang_Word (ptr_bits conf tag
           (LENGTH xs))) :: roots2,
          heap2,be,a + el_length (BlockRep tag rs),
          sp - el_length (BlockRep tag rs),sp1,gens) limit ts)`),
  (* take_el_drop writes the values as the three parts of the
     MutBlock, which is what mutcons_thm_alt is about, and its
     statement with those three parts in is the goal *)
  (
   STRIP_TAC THEN
   FIRST_ASSUM(fun ix ->
     let eq = REWRITE_RULE[APPEND_ASSOC]
                (MATCH_MP take_el_drop ix) in
     W(fun (asl,w) ->
       let hd_is n t = (try fst(dest_const(fst(strip_comb t))) = n
                        with Failure _ -> false) in
       let alt = mutcons_thm_alt in
       let fv n = find_term
         (fun t -> is_var t && fst(dest_var t) = n) (concl alt) in
       let args = snd(strip_comb
         (find_term (hd_is "bvlSem_MutBlock") w)) in
       let alt = REWRITE_RULE[APPEND_ASSOC; eq]
         (INST [el 2 args, fv "l"; el 3 args, fv "c";
                el 4 args, fv "r"] alt) in
       (* the statement of the theorem and the statement of the goal
          invented type variables of their own, so the one is
          instantiated at the other: with the three parts in, the two
          conclusions are the same term but for those variables *)
       MP_TAC(INSTANTIATE (term_match [] (rand (concl alt)) w)
                alt))) THEN
   ASM_REWRITE_TAC[] THEN TRY(DISCH_THEN ACCEPT_TAC)));;

let heap_store_ThunkBlock_thm = prove
 (`!ha.
     (heap_store (heap_length ha) [ThunkBlock ev1 v1] (ha ++
       (ThunkBlock ev2 v2 :: hb)) =
     (ha ++ (ThunkBlock ev1 v1 :: hb),T))`,
  (* a ThunkBlock is one element long whatever it holds, so the
     store leaves the lengths to agree *)
  (let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   GEN_TAC THEN
   REWRITE_TAC[heap_store_lemma; APPEND; PAIR_EQ; hlen_cl;
               ThunkBlock_def; el_length_def] THEN
   ARITH_TAC));;

(* [local] *)
let heap_lookup_ThunkBlock_lemma = prove
 (`(heap_lookup n (ha ++ (ThunkBlock ev v :: hb)) = SOME x) =
       (if n < heap_length ha then
         (heap_lookup n ha = SOME x) else if n = heap_length ha then
         (x = ThunkBlock ev v) else if heap_length ha + 2 <= n then
         (heap_lookup (n - heap_length ha - 2) hb = SOME x) else F)`,
  (* and a ThunkBlock is two long *)
  (REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
               heap_lookup_def; ThunkBlock_def;
               el_length_def] THEN
   REPEAT COND_CASES_TAC THEN
   ASM_REWRITE_TAC[injectivity "option"; distinctness "option"] THEN
   TRY(POP_ASSUM_LIST(fun ths ->
     MP_TAC(end_itlist CONJ (rev ths))) THEN ARITH_TAC) THEN
   TRY(MATCH_ACCEPT_TAC EQ_SYM_EQ) THEN
   REWRITE_TAC[]));;

(* [local] *)
let heap_store_ThunkBlock = prove
 (`(heap_lookup n heap = SOME (ThunkBlock NotEvaluated y)) ==>
   (?heap2.
     heap_store n [ThunkBlock ev h] heap = (heap2,T) /\
     (heap_lookup n heap2 = SOME (ThunkBlock ev h)) /\
     (heap_length heap2 = heap_length heap) /\
     (FILTER isForwardPointer heap2 = FILTER isForwardPointer heap)
       /\
     (!xs l d.
        MEM (DataElement xs l d) heap2 ==>
          (DataElement xs l d = ThunkBlock ev h) \/
          MEM (DataElement xs l d) heap) /\
     (!a. isSomeDataElement (heap_lookup a heap2) =
          isSomeDataElement (heap_lookup a heap)) /\
     (!m x. ~(m = n) /\ (heap_lookup m heap = SOME x) ==>
           (heap_lookup m heap2 = SOME x)))`,
  (* a store into a ThunkBlock: as the store into a BlockRep,
     where the lengths need no hypothesis, because a ThunkBlock
     holds one value whatever its tag says *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    (* the clauses of heap_length *)
    let hlen_cl = prove
     (`heap_length [] = 0 /\
       (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
      REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
  DISCH_TAC THEN
    FIRST_ASSUM(fun hl ->
      MP_TAC(MATCH_MP heap_lookup_SPLIT hl)) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "APPEND" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "heap_length" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    W(fun (asl,w) ->
      let hs = find_term (hd_is "heap_store") (snd(strip_exists w)) in
      let args = snd(strip_comb hs) in
      let nb = lhand (el 1 args) in
      let hp = el 2 args in
      let ap = rator (rator hp) in
      let rest = rand hp in
      let cs = rator (rator rest) in
      EXISTS_TAC (mk_comb(mk_comb(ap,lhand hp),
                          mk_comb(mk_comb(cs,nb),rand rest)))) THEN
    CONJ_TAC THENL
     [MATCH_ACCEPT_TAC heap_store_ThunkBlock_thm;
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_lookup_ThunkBlock_lemma; LT_REFL];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_length_APPEND; hlen_cl;
                  ThunkBlock_def; el_length_def] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[FILTER_APPEND; FILTER; isForwardPointer_def;
                  ThunkBlock_def] THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[MEM_APPEND; MEM] THEN MESON_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [GEN_TAC THEN
      REWRITE_TAC[isSomeDataElement_def] THEN
      REWRITE_TAC[heap_lookup_ThunkBlock_lemma] THEN
      ASM_REWRITE_TAC[] THEN
      REPEAT COND_CASES_TAC THEN
      REWRITE_TAC[ThunkBlock_def] THEN MESON_TAC[];
      ALL_TAC] THEN
    REPEAT GEN_TAC THEN
    REWRITE_TAC[heap_lookup_ThunkBlock_lemma] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]));;

let INJ_NEQ = prove
 (`INJ (FAPPLY f) (FDOM f) {a | isSomeDataElement (heap_lookup a heap)}
  /\
   n IN FDOM f /\
   ptr IN FDOM f /\ ~(n = ptr) ==> ~((FAPPLY f n) = (FAPPLY f ptr))`,
  (REWRITE_TAC[INJ] THEN REPEAT STRIP_TAC THEN ASM_MESON_TAC[]));;

(* [local] *)
let v_inv_Thunk_insert_lemma = prove
 (`!ck v1 refs x f tf heap ptr v y q.
     v_inv conf v1 refs (x,f,tf,heap) /\
     INJ (FAPPLY f) (FDOM f) {a | isSomeDataElement (heap_lookup a
       heap)} /\
     ptr IN FDOM f /\
     lookup ptr refs = SOME (Thunk NotEvaluated v) /\
     heap_lookup (FAPPLY f ptr) heap = SOME (ThunkBlock NotEvaluated
       y) /\
     v_inv conf v refs (y,f,tf,heap) /\
     (ev = Evaluated ==> dest_thunk h refs = NotThunk) /\
     heap_store (FAPPLY f ptr) [ThunkBlock ev q] heap = (heap2,T) /\
     heap_lookup (FAPPLY f ptr) heap2 = SOME (ThunkBlock ev q) /\
     (!m x. ~(m = FAPPLY f ptr) /\ heap_lookup m heap = SOME x ==>
        heap_lookup m heap2 = SOME x) /\
     v_inv conf h refs (q,f,tf,heap) ==>
       v_inv_ck ck conf v1 (insert ptr (Thunk ev h) refs)
         (x,f,tf,heap2)`,
  (* the attempt: the proof of the source names v_inv_def,
     small_int_def, ThunkBlock_def, Word64Rep_def, BlockRep_def,
     LIST_REL_EL_EQN.  What is here rewrites with them and closes by
     arithmetic, and the cheat is behind it until the proof is
     written.  A MESON over them is what the next round adds; it
     costs a load ten minutes to have it in every attempt and it
     closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[v_inv_def; small_int_def; ThunkBlock_def;
       Word64Rep_def; BlockRep_def; LIST_REL_EL_EQN] THEN
     TRY ASM_ARITH_TAC)));;

