(* [local] *)
let heap_lookup_heap_split = prove
 (`!heap a b h1 h2 x.
     heap_split a heap = SOME (h1,h2) /\
     heap_lookup b heap = SOME x ==>
     (if b < a then MEM x h1 else MEM x h2)`,
  (* the element that a lookup finds is in the half of the split
     that its address falls in: heap_lookup_SPLIT cuts the heap at
     the element, and the split of that append is the one of the
     first part or the one that keeps the element *)
  (let stripconj =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) in
   let aux = prove
    (`!(heap:((A,B)heap_element) list) a b h1 h2 x.
        heap_split a heap = SOME (h1,h2) /\
        heap_lookup b heap = SOME x
        ==> (if b < a then MEM x h1 else MEM x h2)`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     FIRST_X_ASSUM(fun th ->
       if (try fst(dest_const(fst(strip_comb(lhs(concl th))))) =
                "heap_lookup"
           with Failure _ -> false)
       then MP_TAC(MATCH_MP heap_lookup_SPLIT th)
       else fail()) THEN
     DISCH_THEN(X_CHOOSE_THEN `ha:((A,B)heap_element) list`
       (X_CHOOSE_THEN `hb:((A,B)heap_element) list`
         STRIP_ASSUME_TAC)) THEN
     VAR_EQ_TAC THEN
     FIRST_X_ASSUM(fun th ->
       MP_TAC(ONCE_REWRITE_RULE
         [heap_split_APPEND_if] th)) THEN
     COND_CASES_TAC THEN
     REWRITE_TAC[heap_split_def] THEN
     ASM_CASES_TAC
       `a - heap_length (ha:((A,B)heap_element) list) = 0` THEN
     ASM_REWRITE_TAC[] THEN
     ASM_CASES_TAC
       `a - heap_length (ha:((A,B)heap_element) list) <
        el_length (x:(A,B)heap_element)` THEN
     ASM_REWRITE_TAC[distinctness "option"] THEN
     EVERY_CASE_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option";
                 PAIR_EQ] THEN
     STRIP_TAC THEN stripconj THEN VAR_EQ_TAC THEN
     ASM_REWRITE_TAC[MEM_APPEND; MEM] THEN
     TRY(CONV_TAC TAUT) THEN TRY ASM_ARITH_TAC) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let heap_store_heap_lookup = prove
 (`!heap heap2 a x n.
      heap_store a x heap = (heap2,T) /\ n < a ==>
      heap_lookup n heap = heap_lookup n heap2`,
  (* the store leaves the elements before the address it writes at
     where they are, so the lookup below it gives the same *)
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[heap_store_def; PAIR_EQ];
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV o LAND_CONV)
       [heap_store_def] THEN
     COND_CASES_TAC THENL
      [ASM_REWRITE_TAC[ARITH_RULE `((n:num) < 0) <=> F`];
       ALL_TAC] THEN
     COND_CASES_TAC THENL
      [REWRITE_TAC[PAIR_EQ]; ALL_TAC] THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[PAIR_EQ] THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
          (fun th -> SUBST_ALL_TAC(EQT_INTRO th)))
       ASSUME_TAC) THEN
     ONCE_REWRITE_TAC[heap_lookup_def] THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_EXISTS_TAC THEN
     ASM_REWRITE_TAC[] THEN ARITH_ASM_TAC]));;

let update_ref_gen_state_ok = prove
 (`heap_store b [RefBlock t1] heap = (heap2,T) /\ a <= b /\
       gen_state_ok a (a + (sp + sp1)) heap gens ==>
       gen_state_ok a (a + (sp + sp1)) heap2 gens`,
  ((* the head constant of a term, by name, and the assumption
      that a test picks out *)
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* the generations are all below a and the pointers of the part
     below each of them stay where they were: the store is at b,
     which is at or above a, so the split at a generation's start
     gives the same first half (heap_split_heap_store) *)
  STRUCT_CASES_TAC(ISPEC `gens:gen_state`
    (cases_of `:gen_state`)) THEN
  REWRITE_TAC[gen_state_ok_def] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(fun ev ->
    if hd_is "ALL" (concl ev) &&
       hd_is "gen_start_ok" (lhand (concl ev))
    then MP_TAC(REWRITE_RULE[GSYM ALL_MEM] ev) else fail()) THEN
  REWRITE_TAC[GSYM ALL_MEM] THEN
  DISCH_TAC THEN GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(fun ev ->
    FIRST_ASSUM(fun mm -> MP_TAC(MATCH_MP ev mm))) THEN
  REWRITE_TAC[gen_start_ok_def] THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
  W(fun (asl,w) ->
    let ev = grab asl (fun th -> hd_is "ALL" (concl th)) in
    let m  = grab asl (fun th -> hd_is "MEM" (concl th) &&
               rand (concl th) = rand (concl ev)) in
    let ab = grab asl (fun th -> hd_is "<=" (concl th)) in
    let sp = grab asl (fun th ->
               hd_is "heap_split" (lhand (concl th))) in
    let st = grab asl (fun th ->
               hd_is "heap_store" (lhand (concl th))) in
    let xa = BETA_RULE(MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev) m) in
    let xb = MATCH_MP (MATCH_MP (ARITH_RULE
               `(x:num) <= a ==> a <= b ==> x <= b`) xa) ab in
    MP_TAC(MATCH_MP heap_split_heap_store
             (CONJ sp (CONJ st xb)))) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN ASSUME_TAC) THEN
  ASM_MESON_TAC[]));;

