(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let num_eq_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (Number i1 :: Number i2 :: stack) refs
       (r1 :: r2 :: roots,heap,be,a,sp,sp1,gens) limit ts /\
     small_int (:'a) i1 /\
     small_int (:'a) i2 ==>
     ((i1 = i2) <=> (r1 = r2)) /\
     r1 = gc_shared_Data (wordLang_Word (Smallnum i1:'a word)) /\
     r2 = gc_shared_Data (wordLang_Word (Smallnum i2))`),
  (* the roots of two small integers are the words of four times
     them, and such a word determines the integer because four
     times a small one is within the range of the word: an eighth
     part of the dimword times four is half of it *)
  ((* Smallnum as an i2w, which the file proves a few theorems
      later (smallnum_i2w of the source): a section may only name
      what stands before it, so the proof stands here as well *)
   let as_i2w = prove
    (`Smallnum i = i2w ((&4) * i)`,
     REWRITE_TAC[smallnum_def] THEN COND_CASES_TAC THENL
      [REWRITE_TAC[WORD_SUB_LZERO] THEN
       ONCE_REWRITE_TAC[WORD_IWORD] THEN
       REWRITE_TAC[GSYM IWORD_INT_NEG] THEN AP_TERM_TAC THEN
       SUBGOAL_THEN `&0 <= &4 * ((&0) - (i:int))` (fun th ->
         REWRITE_TAC[MATCH_MP INT_OF_NUM_OF_INT th]) THENL
        [ASM_INT_ARITH_TAC; INT_ARITH_TAC];
       ONCE_REWRITE_TAC[WORD_IWORD] THEN AP_TERM_TAC THEN
       MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC]) in
   (* four times a small integer is within the range of the word *)
   let bnds = prove
    (`small_int (:'a) i ==>
       --(&2 pow (dimindex (:'a) - 1)) <= (&4) * i /\
       (&4) * i < &2 pow (dimindex (:'a) - 1)`,
     let exp1 = prove
      (`!d. 1 <= d ==> 2 EXP d = 2 * 2 EXP (d - 1)`,
       INDUCT_TAC THEN
       REWRITE_TAC[ARITH_RULE `~(1 <= 0)`; SUC_SUB1; EXP]) in
     let key = prove
      (`4 * (2 EXP (dimindex (:'a)) DIV 8)
        <= 2 EXP (dimindex (:'a) - 1)`,
       MP_TAC(SPECL [`2 EXP (dimindex (:'a))`; `8`] DIVISION) THEN
       REWRITE_TAC[ARITH_EQ] THEN
       MP_TAC(MATCH_MP exp1 (ISPEC `(:'a)` DIMINDEX_GE_1)) THEN
       ARITH_TAC) in
     REWRITE_TAC[small_int_def; dimword] THEN
     MP_TAC key THEN
     REWRITE_TAC[GSYM INT_OF_NUM_POW; GSYM INT_OF_NUM_LE;
                 GSYM INT_OF_NUM_MUL] THEN
     INT_ARITH_TAC) in
   (* so the word of a small integer determines it *)
   let num_eq = prove
    (`small_int (:'a) i1 /\ small_int (:'a) i2 ==>
       ((i1 = i2) <=> (Smallnum i1 = (Smallnum i2:'a word)))`,
     STRIP_TAC THEN
     REWRITE_TAC[as_i2w; GSYM IVAL_EQ] THEN
     ASSUM_LIST(fun ths ->
       REWRITE_TAC(mapfilter
         (fun a -> MATCH_MP IVAL_IWORD (MATCH_MP bnds a)) ths)) THEN
     INT_ARITH_TAC) in
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   STRIP_TAC THEN
   RULE_ASSUM_TRY(REWRITE_RULE[ALL2; v_inv_def]) THEN
   (* the two roots are the words of the integers *)
   FIRST_ASSUM(fun c ->
     if not (is_conj (concl c)) then fail() else
     FIRST_ASSUM(fun s1 -> FIRST_ASSUM(fun s2 ->
       if concl s1 = concl s2 then fail() else
       STRIP_ASSUME_TAC(REWRITE_RULE[s1; s2] c)))) THEN
   ASM_REWRITE_TAC[injectivity "heap_address";
                   injectivity "word_loc"] THEN
   FIRST_ASSUM(fun s1 -> FIRST_ASSUM(fun s2 ->
     if concl s1 = concl s2 then fail() else
     ACCEPT_TAC(MATCH_MP num_eq (CONJ s1 s2))))));;

(* Smallnum_i2w *)
let smallnum_i2w = prove
 (`Smallnum i = i2w ((&4) * i)`,
  (* Smallnum writes the two cases of i2w out: a negative integer
     is the negation of the word of its absolute value, and & of
     the number of a non-negative integer is the integer itself *)
  (REWRITE_TAC[smallnum_def] THEN COND_CASES_TAC THENL
    [REWRITE_TAC[WORD_SUB_LZERO] THEN
     ONCE_REWRITE_TAC[WORD_IWORD] THEN
     REWRITE_TAC[GSYM IWORD_INT_NEG] THEN AP_TERM_TAC THEN
     SUBGOAL_THEN `&0 <= &4 * ((&0) - (i:int))` (fun th ->
       REWRITE_TAC[MATCH_MP INT_OF_NUM_OF_INT th]) THENL
      [ASM_INT_ARITH_TAC; INT_ARITH_TAC];
     ONCE_REWRITE_TAC[WORD_IWORD] THEN AP_TERM_TAC THEN
     MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC]));;

let small_int_IMP_MIN_MAX = prove
 (`good_dimindex (:'a) /\ small_int (:'a) i ==>
    INT_MIN (:'a) <= (&4) * i /\ (&4) * i <= INT_MAX (:'a)`,
  (* the bound of a small integer is a quarter of the dimword and
     INT_MIN and INT_MAX are a half of it, so four times a small
     integer is between them *)
  (REWRITE_TAC[good_dimindex_def; small_int_def;
               dimword; integer_word_INT_MIN; integer_word_INT_MAX;
               INT_MIN] THEN
   STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
   RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
   CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC));;

let num_less_thm = prove
 (`good_dimindex (:'a) /\ small_int (:'a) i1 /\ small_int (:'a) i2 ==>
    ((i1 < i2) <=> (Smallnum i1 < (Smallnum i2:'a word)))`,
  (* the words are the i2w of four times the integers, whose
     ival is the integer itself because a small integer times
     four is between INT_MIN and INT_MAX *)
  (let bnds = prove
    (`good_dimindex (:'a) /\ small_int (:'a) i ==>
       --(&2 pow (dimindex (:'a) - 1)) <= (&4) * i /\
       (&4) * i < &2 pow (dimindex (:'a) - 1)`,
     REWRITE_TAC[good_dimindex_def; small_int_def;
                 dimword] THEN
     STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
     RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
     CONV_TAC NUM_REDUCE_CONV THEN
     CONV_TAC(ONCE_DEPTH_CONV INT_POW_CONV) THEN
     ASM_INT_ARITH_TAC) in
   STRIP_TAC THEN
   REWRITE_TAC[smallnum_i2w; word_ilt; irelational2] THEN
   CONV_TAC(DEPTH_CONV BETA_CONV) THEN
   ASSUM_LIST(fun ths ->
     REWRITE_TAC(mapfilter (fun (a,b) ->
       MATCH_MP IVAL_IWORD (MATCH_MP bnds (CONJ a b)))
       (allpairs (fun a b -> (a,b)) ths ths))) THEN
   INT_ARITH_TAC));;

(* permute stack *)

let all_ts_permute = prove
 (`!(refs:(dataSem_v bvlSem_ref) spt) stack' stack'.
     PERM stack' stack' ==> all_ts refs stack' = all_ts refs stack'`,
  (* the two variables of HOL4's statement, `stack` and `stack'`,
     became one name in the port, so what it states here is that
     the timestamps of a list are the timestamps of that same list
