     W(fun (asl,_) ->
       let eqs = mapfilter (fun (_,th) -> MATCH_MP rel_app_eq th) asl in
       RULE_ASSUM_TAC(REWRITE_RULE eqs) THEN REWRITE_TAC eqs) THEN
     ASM_REWRITE_TAC[];
     GEN_TAC THEN STRIP_TAC THEN
     FIRST_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
      [FIRST_ASSUM(fun rr ->
