(* [local] *)
let small_int_w2i_i2w = prove
 (`small_int (:'a) i /\ good_dimindex (:'a) ==>
   w2i ((i2w ((&4) * i)):'a word) = (&4) * i`,
  (* four times a small integer is between INT_MIN and INT_MAX, so
     the i2w of it has it for its w2i *)
  (let bnds = prove
    (`good_dimindex (:'a) /\ small_int (:'a) i ==>
