        (CONJ gd (CONJ (snd (el 0 sis)) (mr1 asl)))) in
      RULE_ASSUM_TAC(REWRITE_RULE[e1; e2]) THEN
      REWRITE_TAC[e1; e2]) THEN
    REWRITE_TAC[subsm] THEN
    MATCH_MP_TAC IMP_memory_rel_Number THEN
    W(fun (asl,w) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let sis = filter (fun (_,th) -> hd_is "small_int" (concl th))
                  asl in
      let sw = small_int_w2i_i2w in
      let e1 = MATCH_MP sw (CONJ (snd (el 1 sis)) gd) in
