      [SIMP_TAC[];
       DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
       FIRST_ASSUM(fun th1 -> FIRST_ASSUM(fun th2 ->
         MP_TAC(MATCH_MP bits_lt (CONJ th2 th1)))) THEN
