    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[SNOC; SNOC_CASES; SNOC_APPEND; FRONT_SNOC;
       word_list_APPEND; word_list_def] THEN
     TRY ASM_ARITH_TAC)));;

