                // 0 <= i1
                if (x2 && (n2w 16)) = (n2w 0) then
                  // 0 <= i2
                  if decode_length c x1 <+ decode_length c x2 then
                    (n2w 0) else (n2w 2):'a word else
                  (n2w 2) else
                if (x2 && (n2w 16)) = (n2w 0) then
