               ARITH_RULE `~(1 <= 0)`] THEN
   CONV_TAC TAUT));;

let all_ones_n2w = prove
 (`all_ones (l + b) b = n2w (2 EXP l - 1) << b`,
  (* and the same word is the mask of l ones shifted up by b, whose
     bits HOL Light's BIT_MASK_WORD gives *)
  (REWRITE_TAC[all_ones_def] THEN COND_CASES_TAC THENL
    [SUBGOAL_THEN `l = 0` SUBST1_TAC THENL
      [POP_ASSUM MP_TAC THEN ARITH_TAC; ALL_TAC] THEN
     CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC WORD_RULE;
     ALL_TAC] THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; word_slice; word_bits;
               BIT_WORD_SHL; BIT_WORD_SUBWORD; BIT_WORD_NOT;
               BIT_WORD_0; BIT_MASK_WORD] THEN
   X_GEN_TAC `i:num` THEN DISCH_TAC THEN
   REWRITE_TAC[ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
   REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   POP_ASSUM_LIST(fun ths -> MAP_EVERY MP_TAC ths) THEN ARITH_TAC));;

let ptr_bits_lemma = prove
 (`(w << shift_length conf || ptr_bits conf 0 2 || (n2w 1)) =
   w << shift_length conf + ptr_bits conf 0 2 + (n2w 1)`,
  (* the three parts of a pointer do not share a bit, so the or
     of them is their sum: the bits of a maxout_bits lie between
     its shift and its shift plus its width, so the ones of
     ptr_bits lie below the shift_length and above the zeroth *)
  (let bit_hi = prove
    (`!n r (i:num). n < 2 EXP r /\ r <= i
        ==> ~(bit i ((n2w n):(N)word))`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[BIT_WORD] THEN
     SUBGOAL_THEN `n DIV 2 EXP i = 0` SUBST1_TAC THENL
      [MATCH_MP_TAC DIV_LT THEN
       TRANS_TAC LTE_TRANS `2 EXP r` THEN
       ASM_SIMP_TAC[LE_EXP; ARITH];
       REWRITE_TAC[ODD]]) in
   let bit_maxout = prove
    (`!n rep k j. bit j ((maxout_bits n rep k):(N)word)
        ==> k <= j /\ j < k + rep`,
     REPEAT GEN_TAC THEN REWRITE_TAC[maxout_bits_def] THEN
     COND_CASES_TAC THEN REWRITE_TAC[all_ones_def] THENL
      [REWRITE_TAC[BIT_WORD_SHL] THEN STRIP_TAC THEN
       CONJ_TAC THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC(ARITH_RULE
         `k <= j /\ ~(rep <= j - k) ==> j < k + rep`) THEN
       ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
       MP_TAC(ISPECL [`n:num`; `rep:num`; `j - k`] bit_hi) THEN
       ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC;
       COND_CASES_TAC THEN
       REWRITE_TAC[BIT_WORD_0; word_slice; word_bits; BIT_WORD_SHL;
                   BIT_WORD_SUBWORD] THEN
       STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC]) in
   let bit_pb = prove
    (`!conf j. bit j ((ptr_bits conf 0 2):(N)word)
        ==> 1 <= j /\ j < small_shift_length conf`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[ptr_bits_def; small_shift_length_def;
                 BIT_WORD_OR] THEN
     DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (DISJ_CASES_THEN
       (fun th -> MP_TAC(MATCH_MP bit_maxout th)))) THEN
     ARITH_TAC) in
   let sl = prove
    (`!conf. small_shift_length conf <= shift_length conf /\
             2 <= shift_length conf`,
     REWRITE_TAC[small_shift_length_def;
                 shift_length_def] THEN ARITH_TAC) in
   let pb1 = prove
    (`!conf. ((ptr_bits conf 0 2) && (n2w 1):(N)word) = n2w 0`,
     GEN_TAC THEN REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
     X_GEN_TAC `j:num` THEN DISCH_TAC THEN
     REWRITE_TAC[BIT_WORD_AND; BIT_WORD_0; BIT_WORD_1] THEN
     REWRITE_TAC[TAUT `(p <=> F) <=> ~p`] THEN STRIP_TAC THEN
     FIRST_ASSUM(MP_TAC o MATCH_MP bit_pb) THEN
     ASM_REWRITE_TAC[] THEN ARITH_TAC) in
   let aw = prove
    (`!(w:(N)word) conf.
        (w << shift_length conf) &&
        (ptr_bits conf 0 2 || n2w 1) = n2w 0`,
     REPEAT GEN_TAC THEN REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
     X_GEN_TAC `j:num` THEN DISCH_TAC THEN
     REWRITE_TAC[BIT_WORD_AND; BIT_WORD_OR; BIT_WORD_0; BIT_WORD_1;
                 BIT_WORD_SHL] THEN
     REWRITE_TAC[TAUT `(p <=> F) <=> ~p`] THEN STRIP_TAC THEN
     TRY(FIRST_ASSUM(MP_TAC o MATCH_MP bit_pb)) THEN
     MP_TAC(SPEC_ALL sl) THEN ARITH_NO_BIT_TAC) in
   let gen = prove
    (`!(w:(N)word) conf.
        (w << shift_length conf || ptr_bits conf 0 2 || n2w 1) =
        w << shift_length conf + ptr_bits conf 0 2 + n2w 1`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[GEN_ALL(MATCH_MP WORD_ADD_OR (SPEC_ALL pb1));
                 GEN_ALL(MATCH_MP WORD_ADD_OR (SPEC_ALL aw))]) in
   MATCH_ACCEPT_TAC gen));;

let encode_header_lemma = prove
 (`1 < data_to_word_config_len_size c /\ data_to_word_config_len_size c
  + 5 < dimindex (:'a) /\
   good_dimindex (:'a) ==>
   decode_length c (make_header c (n2w 0) 2) = ((n2w 2):'a word) /\
   encode_header c 0 2 = SOME (make_header c ((n2w 0):'a word) 2)`,
  (* the four conditions of encode_header hold of the tag 0 and the
     length 2 (the length size is above one, so two is below two to
     that power), so the header is SOME of what make_header gives,
     and encode_header_IMP reads the length back off it *)
  (let gdcases =
     FIRST_ASSUM(DISJ_CASES_THEN SUBST1_TAC o
       REWRITE_RULE[good_dimindex_def]) in
   STRIP_TAC THEN
   SUBGOAL_THEN
     `0 < 2 EXP (dimindex (:'a) -
                 data_to_word_config_len_size c - 2) /\
      0 < dimword (:'a) DIV 16 /\
      2 < 2 EXP (dimindex (:'a) - 4) /\
      2 < 2 EXP (data_to_word_config_len_size c)`
     STRIP_ASSUME_TAC THENL
    [REPEAT CONJ_TAC THENL
      [REWRITE_TAC[LT_NZ; EXP_EQ_0; ARITH_EQ];
       REWRITE_TAC[dimword] THEN gdcases THEN
       CONV_TAC NUM_REDUCE_CONV;
       gdcases THEN CONV_TAC NUM_REDUCE_CONV;
       MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `2 EXP 2` THEN
       CONJ_TAC THENL
        [CONV_TAC NUM_REDUCE_CONV;
         REWRITE_TAC[LE_EXP] THEN CONV_TAC NUM_REDUCE_CONV THEN
         ASM_ARITH_TAC]];
     ALL_TAC] THEN
   SUBGOAL_THEN
     `encode_header c 0 2 = SOME (make_header c ((n2w 0):'a word) 2)`
     ASSUME_TAC THENL
    [ASM_REWRITE_TAC[encode_header_def]; ALL_TAC] THEN
   ASM_REWRITE_TAC[] THEN
   FIRST_ASSUM(fun eh -> FIRST_ASSUM(fun ls -> FIRST_ASSUM(fun gd ->
     ACCEPT_TAC(CONJUNCT2(MATCH_MP encode_header_IMP
       (CONJ eh (CONJ ls gd)))))))));;

let append_writes_list_to_BlockReps = prove
 (`!xs ws x w offset init_ptr.
     LENGTH xs = LENGTH ws /\
     good_dimindex (:'a) /\
     1 < data_to_word_config_len_size c /\
       data_to_word_config_len_size c + 5 < dimindex (:'a) /\
     backend_common_word_shift (:'a) <= shift_length c /\
     LIST_REL (\v w. word_addr c v = w) (x :: xs) (w :: ws) /\
     wordLang_Word init_ptr = make_cons_ptr c (bytes_in_word * (n2w
       offset:'a word)) 0 2 ==>
     misc_word_list (curr + bytes_in_word * (n2w offset:'a word))
       (append_writes c init_ptr
          (make_header c (n2w 0) 2) (w :: ws) (word_addr c v)) =
     word_heap (curr + bytes_in_word * (n2w offset:'a word))
       (list_to_BlockReps c v offset (x :: xs)) c`,
  (* the attempt: the proof of the source names append_writes_def,
     list_to_BlockReps_def, BlockRep_def, word_heap_def,
     el_length_def, word_el_def.  What is here rewrites with them
     and closes by arithmetic, and the cheat is behind it until the
     proof is written.  A MESON over them is what the next round
     adds; it costs a load ten minutes to have it in every attempt
     and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[append_writes_def; list_to_BlockReps_def;
       BlockRep_def; word_heap_def; el_length_def; word_el_def] THEN
     TRY ASM_ARITH_TAC)));;

let bind_each_eq_tf = prove
 (`!k tf ts n i x.
     (!t. t IN FDOM tf ==> t < ts) /\ x < ts ==> FAPPLY (bind_each
       tf ts n i k) x = FAPPLY tf x`,
  (* the bindings that bind_each adds are above ts, so a timestamp
     below it keeps the value that tf gives it *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   REWRITE_TAC[bind_each_def] THEN
   REWRITE_TAC[FAPPLY_FUPDATE_THM] THEN
   COND_CASES_TAC THENL
    [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC;
     FIRST_X_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
      [GEN_TAC THEN DISCH_TAC THEN
       FIRST_X_ASSUM(MP_TAC o SPEC `t:num`) THEN
       ASM_REWRITE_TAC[] THEN ARITH_TAC;
       ASM_ARITH_TAC]]));;

let bind_each_FDOM = prove
 (`!n tf ts k i.
    FDOM (bind_each tf ts k i n) = FDOM tf UNION {x | ts <= x /\ x
      < ts + n}`,
  (* bind_each ts ... n binds the n timestamps from ts up *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   ASM_REWRITE_TAC[bind_each_def; FDOM_FUPDATE] THEN
   REWRITE_TAC[EXTENSION; IN_UNION; IN_INSERT; IN_ELIM_THM] THEN
   GEN_TAC THEN EQ_TAC THEN STRIP_TAC THEN
   ASM_REWRITE_TAC[] THEN
   TRY(DISJ2_TAC THEN ASM_ARITH_TAC) THEN
   TRY(DISJ1_TAC THEN ASM_ARITH_TAC) THEN
   ASM_ARITH_TAC));;

let bind_each_eq_tf_FDOM = prove
 (`!k tf ts n i x.
     (!t. t IN FDOM tf ==> t < ts) /\ x < ts /\ x IN FDOM
       (bind_each tf ts n i k) ==> x IN FDOM tf`,
  (REWRITE_TAC[bind_each_FDOM; IN_UNION; IN_ELIM_THM] THEN
   REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC));;

let bind_each_eq_lt_FAPPLY = prove
 (`!n tf ts k i x.
    FAPPLY
    (bind_each tf ts k i n) x < k ==> FAPPLY (bind_each tf ts k i
      n) x = FAPPLY tf x`,
  (* a value below the first key that bind_each gives out is one of
     tf: the keys it gives are k, k + i, k + 2 * i, ... *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM] THEN
   COND_CASES_TAC THEN REWRITE_TAC[LT_REFL] THEN
   DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC));;

let bind_each_eq_lt_FDOM = prove
 (`!n tf ts k i x.
    x IN FDOM (bind_each tf ts k i n) /\ FAPPLY (bind_each tf ts k
      i n) x < k ==> x IN FDOM tf`,
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM;
               FDOM_FUPDATE; IN_INSERT] THENL
    [CONV_TAC TAUT;
     COND_CASES_TAC THEN REWRITE_TAC[LT_REFL] THEN
     STRIP_TAC THEN
     FIRST_X_ASSUM(fun ih -> MP_TAC(SPECL
       [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`; `x:num`]
       ih)) THEN
     ANTS_TAC THENL
      [CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_ARITH_TAC;
       DISCH_THEN ACCEPT_TAC]]));;

let bind_each_eq_gt_FAPPLY = prove
 (`!n tf ts k i x.
    i * n + k < FAPPLY (bind_each tf ts k i n) x ==> FAPPLY
      (bind_each tf ts k i n) x = FAPPLY tf x`,
  (* and a value above the last one is one of tf as well *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM;
               MULT_SUC] THEN
   COND_CASES_TAC THEN
   TRY(DISCH_THEN(fun th -> MP_TAC th THEN ARITH_TAC)) THEN
   DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC));;

let bind_each_eq_gt_FDOM = prove
 (`!n tf ts k i x.
    x IN FDOM (bind_each tf ts k i n) /\ i * n + k < FAPPLY
      (bind_each tf ts k i n) x ==> x IN FDOM tf`,
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM;
               FDOM_FUPDATE; IN_INSERT; MULT_SUC] THENL
    [CONV_TAC TAUT;
     COND_CASES_TAC THENL
      [STRIP_TAC THEN ASM_ARITH_TAC;
       STRIP_TAC THEN
       FIRST_X_ASSUM(fun ih -> MP_TAC(SPECL
         [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`; `x:num`]
         ih)) THEN
       ANTS_TAC THENL
        [CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
         ASM_ARITH_TAC;
         DISCH_THEN ACCEPT_TAC]]]));;

let bind_each_eq_ge_FDOM = prove
 (`!n tf ts k i x.
    x IN FDOM (bind_each tf ts k i n) /\
    i * n + k <= FAPPLY (bind_each tf ts k i n) x /\ ~(i = 0) ==> x
      IN FDOM tf`,
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM;
               FDOM_FUPDATE; IN_INSERT; MULT_SUC] THENL
    [CONV_TAC TAUT;
     COND_CASES_TAC THENL
      [STRIP_TAC THEN ASM_ARITH_TAC;
       STRIP_TAC THEN
       FIRST_X_ASSUM(fun ih -> MP_TAC(SPECL
         [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`; `x:num`]
         ih)) THEN
       ANTS_TAC THENL
        [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
         ASM_ARITH_TAC;
         DISCH_THEN ACCEPT_TAC]]]));;

let bind_each_fdom_limit = prove
 (`!k tf ts n i x.
     (!t. t IN FDOM tf ==> t < ts) /\ ts + k < x ==> ~(x IN FDOM
       (bind_each tf ts n i k))`,
  (* bind_each binds the k timestamps from ts up, so a timestamp
     above ts + k is in neither it nor tf *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FDOM_FUPDATE; IN_INSERT;
               DE_MORGAN_THM] THEN
   STRIP_TAC THENL
    [DISCH_TAC THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `x:num`) THEN
     ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
     CONJ_TAC THENL
      [ASM_ARITH_TAC;
       FIRST_X_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
        [GEN_TAC THEN DISCH_TAC THEN
         FIRST_X_ASSUM(MP_TAC o SPEC `t:num`) THEN
         ASM_REWRITE_TAC[] THEN ARITH_TAC;
         ASM_ARITH_TAC]]]));;

let bind_each_FUPDATE = prove
 (`!n i tf ts1 ts2 k1 k2.
    ts1 < ts2 /\ k1 < k2 ==> bind_each (tf |+ (ts1,k1)) ts2 k2 i n
      = bind_each tf ts2 k2 i n |+ (ts1,k1)`,
  (* the binding of the timestamps of a block does not touch a
     timestamp below the ones it binds, so an update of that one
     commutes with it (ml/lib/lemmas.ml has FUPDATE_COMMUTES) *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def] THEN
   DISCH_TAC THEN
   FIRST_X_ASSUM(fun ih ->
     MP_TAC(SPECL [`i:num`; `tf:(num,num)fmap`; `ts1:num`;
                   `ts2 + 1`; `k1:num`; `k2 + i`] ih)) THEN
   ASM_REWRITE_TAC[ARITH_RULE `(ts1 < ts2 + 1) <=> ts1 <= ts2`] THEN
   ANTS_TAC THENL
    [ASM_ARITH_TAC;
     DISCH_THEN SUBST1_TAC THEN
     MATCH_MP_TAC FUPDATE_COMMUTES THEN ASM_ARITH_TAC]));;

let bind_each_MINUS = prove
 (`!n tf ts x k1 k2 i.
    (!t. t IN FDOM tf ==> t < ts) /\
    x IN {x | ts <= x /\ x < ts + n} /\ k2 <= k1 ==> FAPPLY
      (bind_each tf ts k1 i n) x - k2 = FAPPLY (bind_each tf ts (k1 -
      k2) i n) x`,
  (* the binding of each timestamp of a block gives the one at ts
     the clock k and the ones above it k + i, k + 2i, ...: taking k2
     off every one of them is the binding that starts k2 lower *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bind_each_def; IN_ELIM_THM] THEN
    STRIP_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_CASES_TAC `(x:num) = ts` THENL
     [ASM_REWRITE_TAC[FAPPLY_FUPDATE_THM];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[FAPPLY_FUPDATE_THM] THEN
    SUBGOAL_THEN `(k1 - k2) + i = (k1 + i) - k2` SUBST1_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[IN_ELIM_THM] THEN
    REPEAT CONJ_TAC THEN TRY ASM_ARITH_TAC THEN
    GEN_TAC THEN DISCH_TAC THEN
    FIRST_ASSUM(fun fd -> FIRST_ASSUM(fun h ->
      MP_TAC(MATCH_MP fd h))) THEN
    ARITH_TAC));;

(* isSomeDataElement_heap_lookup[allow_rebind] *)
let data_to_word_memoryProof_isSomeDataElement_heap_lookup = prove
 (`!n a sp b.
    isSomeDataElement (heap_lookup n (a ++ [Unused sp] ++ b)) ==> n
      < heap_length a \/ el_length (Unused sp) + heap_length a <= n`,
  (* the lookup falls in the first heap, or past the Unused in the
     second: the Unused itself holds no data element *)
  (let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) =
              el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   let isde_rws = [isSomeDataElement_def;
                   distinctness "option"; injectivity "option";
                   distinctness "heap_element"] in
   let un_none = prove
    (`!sp m. ~(isSomeDataElement
                 (heap_lookup m [Unused sp:((A,B)heap_element)]))`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC(heap_lookup_def :: el_length_def ::
                 isde_rws) THEN
     REPEAT COND_CASES_TAC THEN
     REWRITE_TAC(heap_lookup_def :: isde_rws)) in
   REPEAT GEN_TAC THEN
   REWRITE_TAC[GSYM APPEND_ASSOC;
               data_to_word_memoryProof_heap_lookup_APPEND] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN
   REWRITE_TAC[hlen_cl; ADD_CLAUSES] THEN
   COND_CASES_TAC THEN REWRITE_TAC[un_none] THEN
   DISCH_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[el_length_def]) THEN
   REWRITE_TAC[el_length_def] THEN ARITH_ASM_TAC));;

let isSomeDataElement_heap_lookup_eq = prove
 (`!ls n p k1 k2 conf.
    isSomeDataElement (heap_lookup n
      ((list_to_BlockReps conf p k2 ls):(('a
        word_loc,data_to_word_memoryProof_tag#'b list)heap_element)
        list)) ==> isSomeDataElement (heap_lookup n
      ((list_to_BlockReps conf p k1 ls):(('a
        word_loc,data_to_word_memoryProof_tag#'b list)heap_element)
        list))`,
  (* the heap that the list builds has the same elements whatever
     the address it starts at: the first block is a data element
     either way, and the lookup past it is the induction *)
  (let isde = prove
    (`!ys l d. isSomeDataElement (SOME (DataElement ys l d))`,
     REWRITE_TAC[isSomeDataElement_def] THEN MESON_TAC[]) in
   let isdeN = prove
    (`~isSomeDataElement NONE`,
     REWRITE_TAC[isSomeDataElement_def;
                 distinctness "option"]) in
   LIST_INDUCT_TAC THENL
    [REWRITE_TAC[list_to_BlockReps_def]; ALL_TAC] THEN
   REPEAT GEN_TAC THEN POP_ASSUM MP_TAC THEN
   REWRITE_TAC[list_to_BlockReps_def] THEN
   (fun (asl,w as gl) ->
      let scr = hd (filter is_var (match_scruts w)) in
      STRUCT_CASES_TAC(ISPEC scr list_CASES_v) gl) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[] THEN
   DISCH_TAC THEN
   ONCE_REWRITE_TAC[heap_lookup_def] THEN
   REWRITE_TAC[BlockRep_def; el_length_def; LENGTH] THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[isde] THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[isdeN] THEN
   DISCH_TAC THEN
   FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_EXISTS_TAC THEN
   ASM_REWRITE_TAC[]));;

let bind_each_isSomeDataElement = prove
 (`!l tf ts x p k conf.
    ~(l = []) /\
    x IN {x | ts <= x /\ x < ts + (LENGTH l)} /\ (!t. t IN FDOM tf
      ==> t < ts) ==> isSomeDataElement (heap_lookup ((FAPPLY (bind_each
      tf ts 0 3 (LENGTH l)) x))
                        (list_to_BlockReps conf p k l))`,
  (* the attempt: the proof of the source names bind_each_def,
     bind_each_FUPDATE, FAPPLY_FUPDATE_THM, list_to_BlockReps_def,
     BlockRep_def, heap_lookup_def.  What is here rewrites with them
     and closes by arithmetic, and the cheat is behind it until the
     proof is written.  A MESON over them is what the next round
     adds; it costs a load ten minutes to have it in every attempt
     and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[bind_each_def; bind_each_FUPDATE;
       FAPPLY_FUPDATE_THM; list_to_BlockReps_def; BlockRep_def;
       heap_lookup_def] THEN
     TRY ASM_ARITH_TAC)));;

let bind_each_eq_INJ = prove
 (`!n x y tf ts k i.
   FAPPLY
   (bind_each tf ts k i n) x = FAPPLY (bind_each tf ts k i n) y /\
   ~(i = 0) /\ x IN {x | ts <= x /\ x < ts + n} /\
   ~(x IN FDOM tf) /\ y IN {x | ts <= x /\ x < ts + n} /\ ~(y IN
     FDOM tf) ==> x = y`,
  (* the binding gives each timestamp its own clock: the one at ts
     gets k and the ones above it more than k, which
     bind_each_eq_lt_FDOM says, so two of them with one clock are
     one timestamp *)
  (let eqlt = bind_each_eq_lt_FDOM in
    let bfd = bind_each_FDOM in
    let use_eqlt v =
      MP_TAC(SPECL [`n:num`; `tf:(num,num)fmap`; `ts + 1`; `k + i`;
                    `i:num`; v] eqlt) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [REWRITE_TAC[bfd; IN_UNION; IN_ELIM_THM] THEN ASM_ARITH_TAC;
          FIRST_ASSUM(fun e -> REWRITE_TAC[GSYM e]) THEN ASM_ARITH_TAC];
        ASM_REWRITE_TAC[]] in
    INDUCT_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bind_each_def; IN_ELIM_THM] THENL
     [STRIP_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[FAPPLY_FUPDATE_THM] THEN
    ASM_CASES_TAC `(x:num) = ts` THEN ASM_CASES_TAC `(y:num) = ts` THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [use_eqlt `y:num`;
      use_eqlt `x:num`;
      FIRST_X_ASSUM MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC
        [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`] THEN
      ASM_REWRITE_TAC[IN_ELIM_THM] THEN
      REPEAT CONJ_TAC THEN ASM_ARITH_TAC]));;

let all_ts_list_to_v_SUBSET = prove
 (`!xs ts (refs:(dataSem_v bvlSem_ref) spt) t.
    {x | ts <= x /\ x < ts + LENGTH xs} SUBSET all_ts refs
      [list_to_v ts t xs]`,
  (* the list that list_to_v builds is a Block of each timestamp
     from ts up, one for each element, and the timestamps of a
     Block on the stack are its own and the ones of its payload *)
  (SUBGOAL_THEN
     `!xs ts refs (tv:dataSem_v).
        {x | ts <= x /\ x < ts + LENGTH xs} SUBSET
        all_ts refs [list_to_v ts tv xs]`
     (fun th -> MATCH_ACCEPT_TAC th) THEN
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[SUBSET; IN_ELIM_THM; LENGTH; ADD_CLAUSES] THEN
     GEN_TAC THEN MATCH_MP_TAC(TAUT `~p ==> (p ==> q)`) THEN
     ARITH_TAC;
     REWRITE_TAC[dataSem_list_to_v_def] THEN
     ONCE_REWRITE_TAC[all_ts_cons] THEN
     REWRITE_TAC[APPEND; APPEND_NIL] THEN
     ONCE_REWRITE_TAC[all_ts_head] THEN
     FIRST_X_ASSUM(MP_TAC o SPECL
       [`(ts:num) + 1`; `refs:(dataSem_v bvlSem_ref) spt`;
        `tv:dataSem_v`]) THEN
     REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INSERT; IN_UNION;
                 LENGTH] THEN
     DISCH_TAC THEN X_GEN_TAC `u:num` THEN STRIP_TAC THEN
     ASM_CASES_TAC `(u:num) = ts` THENL
      [DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
       DISJ2_TAC THEN DISJ2_TAC THEN
       FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC]]));;

let all_ts_SUBSET_list_to_v = prove
 (`!refs t xs stack' ts.
     all_ts refs (t :: (xs ++ stack')) SUBSET
     all_ts refs (list_to_v ts t xs :: stack')`,
  (* and so are the timestamps of the elements and of the tail of
     the list, which are the same values in another order *)
  (let all_ts_perm = prove
    (`!refs (xs:dataSem_v list) ys.
        (!x. MEM x xs <=> MEM x ys)
        ==> all_ts refs xs = all_ts refs ys`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[all_ts_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_REWRITE_TAC[]) in
   SUBGOAL_THEN
     `!xs refs (tv:dataSem_v) stk ts.
        all_ts refs (CONS tv (xs ++ stk)) SUBSET
        all_ts refs (CONS (list_to_v ts tv xs) stk)`
     (fun th -> REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC th) THEN
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[dataSem_list_to_v_def; APPEND; SUBSET_REFL];
     REWRITE_TAC[dataSem_list_to_v_def] THEN
     ONCE_REWRITE_TAC[all_ts_cons] THEN
     REWRITE_TAC[APPEND] THEN
     SUBGOAL_THEN
       `all_ts refs (CONS (tv:dataSem_v) (CONS h (t ++ stk))) =
        all_ts refs (CONS tv (t ++ CONS h stk))`
       SUBST1_TAC THENL
      [MATCH_MP_TAC all_ts_perm THEN
       REWRITE_TAC[MEM; MEM_APPEND] THEN CONV_TAC TAUT;
       ALL_TAC] THEN
     SUBGOAL_THEN
       `all_ts refs (CONS (h:dataSem_v)
          (CONS (list_to_v ((ts:num) + 1) tv t) stk)) =
        all_ts refs (CONS (list_to_v (ts + 1) tv t) (CONS h stk))`
       SUBST1_TAC THENL
      [MATCH_MP_TAC all_ts_perm THEN REWRITE_TAC[MEM] THEN
       CONV_TAC TAUT;
       ALL_TAC] THEN
     FIRST_X_ASSUM(MP_TAC o SPECL
       [`refs:(dataSem_v bvlSem_ref) spt`; `tv:dataSem_v`;
        `CONS (h:dataSem_v) stk`; `(ts:num) + 1`]) THEN
     SET_TAC[]]));;

let new_all_ts_SUBSET_list_to_v = prove
 (`!refs t xs stack' ts.
     {x | ts <= x /\ x < ts + LENGTH xs} SUBSET
     all_ts refs (list_to_v ts t xs :: stack')`,
  (* and those timestamps are timestamps of the stack that the
     list is on, whatever else that stack holds *)
  (let all_ts_perm = prove
    (`!refs (xs:dataSem_v list) ys.
        (!x. MEM x xs <=> MEM x ys)
        ==> all_ts refs xs = all_ts refs ys`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[all_ts_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_REWRITE_TAC[]) in
   SUBGOAL_THEN
     `!xs refs (tv:dataSem_v) stk ts.
        {x | ts <= x /\ x < ts + LENGTH xs} SUBSET
        all_ts refs (CONS (list_to_v ts tv xs) stk)`
     (fun th -> REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC th) THEN
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[SUBSET; IN_ELIM_THM; LENGTH; ADD_CLAUSES] THEN
     GEN_TAC THEN MATCH_MP_TAC(TAUT `~p ==> (p ==> q)`) THEN
     ARITH_TAC;
     REWRITE_TAC[dataSem_list_to_v_def] THEN
     ONCE_REWRITE_TAC[all_ts_cons] THEN
     REWRITE_TAC[APPEND] THEN
     SUBGOAL_THEN
       `all_ts refs (CONS (h:dataSem_v)
          (CONS (list_to_v ((ts:num) + 1) tv t) stk)) =
        all_ts refs (CONS (list_to_v (ts + 1) tv t) (CONS h stk))`
       SUBST1_TAC THENL
      [MATCH_MP_TAC all_ts_perm THEN REWRITE_TAC[MEM] THEN
       CONV_TAC TAUT;
       ALL_TAC] THEN
     FIRST_X_ASSUM(MP_TAC o SPECL
       [`refs:(dataSem_v bvlSem_ref) spt`; `tv:dataSem_v`;
        `CONS (h:dataSem_v) stk`; `(ts:num) + 1`]) THEN
     REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INSERT; LENGTH] THEN
     DISCH_TAC THEN X_GEN_TAC `u:num` THEN STRIP_TAC THEN
     ASM_CASES_TAC `(u:num) = ts` THENL
      [DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
       DISJ2_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
       ASM_ARITH_TAC]]));;

let FDOM_bind_each_lemma = prove
 (`!tf k ts h.
     FDOM tf SUBSET {n | n < ts} ==>
     FDOM (bind_each tf ts h n k) SUBSET {n | n < ts + k}`,
  (* induction on the number of bindings: each one is a timestamp
     one higher than the last, and the domain grows by that one *)
  (let aux = prove
    (`!k tf ts h i. FDOM tf SUBSET {m | m < ts}
        ==> FDOM (bind_each tf ts h i k) SUBSET {m | m < ts + k}`,
     INDUCT_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THENL
      [ASM_REWRITE_TAC[bind_each_def; ADD_CLAUSES];
       REWRITE_TAC[bind_each_def; FDOM_FUPDATE;
                   INSERT_SUBSET; IN_ELIM_THM] THEN
       CONJ_TAC THENL
        [ARITH_TAC;
         FIRST_ASSUM(fun ih ->
           MP_TAC(SPECL [`tf:(num,num)fmap`; `ts + 1`; `h + i:num`;
                         `i:num`] ih)) THEN
         REWRITE_TAC[ARITH_RULE `(ts + 1) + k = ts + SUC k`] THEN
         DISCH_THEN MATCH_MP_TAC THEN
         FIRST_ASSUM(fun sub -> MP_TAC sub) THEN
         REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
         MESON_TAC[ARITH_RULE `!a b:num. a < b ==> a < b + 1`]]]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC(SPEC_ALL aux)));;

let v_all_vs_list_to_v1 = prove
 (`!xs stack' ts t t1 a1 xs1.
     t1 < ts /\
     MEM (Block t1 a1 xs1) (v_all_vs (list_to_v ts t xs :: stack'))
       ==>
       MEM (Block t1 a1 xs1) (v_all_vs (t :: (xs ++ stack')))`,
  (* the list that list_to_v builds is a chain of conses, and the
     Blocks of the chain itself have the timestamps from ts on,
     which the Block of the goal is below; so a Block among the
     values of the chain is one of the values of the list or of the
     stack, which the induction follows cons by cons *)
  (
   let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let split = MEM_v_all_vs_split
   and ext_hd = MEM_v_all_vs_extend_hd
   and ext_tl = MEM_v_all_vs_extend_tl in
   let mem_app = prove
    (`!(x:dataSem_v) l1 l2.
        MEM x (v_all_vs (l1 ++ l2)) <=>
        MEM x (v_all_vs l1) \/ MEM x (v_all_vs l2)`,
     REWRITE_TAC[v_all_vs_append; MEM_APPEND]) in
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[dataSem_list_to_v_def; APPEND] THENL
    [DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
     STRIP_TAC THEN
     SUBGOAL_THEN `t1 < ts + 1` ASSUME_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC] THEN
     FIRST_ASSUM(fun m ->
       let th = MATCH_MP split m in
       MP_TAC(REWRITE_RULE[vsing; MEM] th)) THEN
     STRIP_TAC THEN
     ASM_MESON_TAC[split; ext_hd; ext_tl; mem_app;
                   injectivity "dataSem_v"; LT_REFL]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_GT_ts = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (t :: (xs ++ stack))) /\
     t' >= ts /\ ~(xs1 = []) ==> ~(Block t' a1 xs1 IN all_vs refs
       (t :: (xs ++ stack)))`),
  (* blocks_unique gives the timestamp of a Block of the set as one
     below ts, and this one is not *)
  (REWRITE_TAC[blocks_unique_def] THEN REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[ARITH_RULE `!a b:num. a >= b /\ a < b ==> F`]));;

(* the port's own: what the three lemmas about the chain of conses
   that list_to_v builds share.  Each of them is an induction on the
   list the chain is of, and what the steps need is the three ways
   in which a value is one of the values of the refs and the stack,
   and the two ways in which a value of the chain and the stack is
   one of the chain's own. *)

(* a value of the head of the stack, a value of the rest of it, and
   a value of a shorter stack, are values of the refs and the
   stack *)

let av_in_stack = prove
 (`!x refs stack'.
     MEM x (v_all_vs stack') ==> x IN all_vs refs stack'`,
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[]);;

let av_in_cons = prove
 (`!x refs v l.
     MEM x (v_all_vs [v]) ==> x IN all_vs refs (v :: l)`,
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[MEM_v_all_vs_extend_tl]);;

let av_in_tl = prove
 (`!x refs v l. x IN all_vs refs l ==> x IN all_vs refs (v :: l)`,
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[MEM_v_all_vs_extend_hd]);;

(* and a value of the refs and a stack is one of the stack or one
   of the refs and any other stack *)

let av_in_refs = prove
 (`!x refs l1 l2.
     x IN all_vs refs l1
     ==> MEM x (v_all_vs l1) \/ x IN all_vs refs l2`,
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[]);;

(* the set of a stack without one of its values is a part of the
   set with it, and the other way about *)

let av_shrink2 = prove
 (`!x refs t h h' l.
     ~(x IN all_vs refs (t :: h :: h' :: l))
     ==> ~(x IN all_vs refs (t :: h' :: l))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; DE_MORGAN_THM] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[MEM_v_all_vs_split; MEM_v_all_vs_extend_hd;
                MEM_v_all_vs_extend_tl]);;

let av_shrink = prove
 (`!x refs t h l.
     ~(x IN all_vs refs (t :: h :: l))
     ==> ~(x IN all_vs refs (t :: l))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; DE_MORGAN_THM] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[MEM_v_all_vs_split; MEM_v_all_vs_extend_hd;
                MEM_v_all_vs_extend_tl]);;

let av_grow = prove
 (`!x refs t h l.
     x IN all_vs refs (t :: l) ==> x IN all_vs refs (t :: h :: l)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[MEM_v_all_vs_split; MEM_v_all_vs_extend_hd;
            MEM_v_all_vs_extend_tl]);;

(* a value of the values of a chain of conses and a stack is the
   first Block of the chain, a value of the element it holds, or a
   value of the rest of the chain and the stack *)

let av_decomp = prove
 (`!x ts t h xs stack'.
     MEM x (v_all_vs (list_to_v ts t (h :: xs) :: stack')) ==>
     x = Block ts cons_tag [h; list_to_v (ts + 1) t xs] \/
     MEM x (v_all_vs [h]) \/
     MEM x (v_all_vs (list_to_v (ts + 1) t xs :: stack'))`,
  (let (_,vsing,_,_) = v_all_vs_clauses () in
   REPEAT GEN_TAC THEN REWRITE_TAC[dataSem_list_to_v_def] THEN
   DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC o
               MATCH_MP MEM_v_all_vs_split) THENL
    [FIRST_ASSUM(fun m ->
       if not (hd_is "MEM" (concl m)) then fail() else
       MP_TAC(REWRITE_RULE[vsing; MEM] m)) THEN
     DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
      [ASM_REWRITE_TAC[];
       FIRST_ASSUM(fun m ->
         if not (hd_is "MEM" (concl m)) then fail() else
         DISJ_CASES_THEN ASSUME_TAC
           (MATCH_MP MEM_v_all_vs_split m)) THEN
       ASM_MESON_TAC[MEM_v_all_vs_extend_tl;
                     MEM_v_all_vs_extend_hd]];
     ASM_MESON_TAC[MEM_v_all_vs_extend_hd]]));;

(* and of the two ways that are left when the value is none of the
   list and the stack, the one through the element the chain holds
   is out, because that element is on the stack *)

let av_decomp2 = prove
 (`!x refs ts t h xs stack'.
     MEM x (v_all_vs (list_to_v ts t (h :: xs) :: stack')) /\
     ~(x IN all_vs refs (t :: ((h :: xs) ++ stack'))) ==>
     x = Block ts cons_tag [h; list_to_v (ts + 1) t xs] \/
     MEM x (v_all_vs (list_to_v (ts + 1) t xs :: stack'))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[APPEND] THEN STRIP_TAC THEN
  FIRST_ASSUM(fun m ->
    if not (hd_is "MEM" (concl m)) then fail() else
    STRIP_ASSUME_TAC(MATCH_MP av_decomp m)) THEN
  ASM_MESON_TAC[av_in_cons; av_in_tl]);;

(* a Block of the chain's own timestamp that is a value of the rest
   of the chain is a value of the list and the stack *)

let av_no_mix = prove
 (`!refs ts t h xs stack' a2 xs2.
     MEM (Block ts a2 xs2)
       (v_all_vs (list_to_v (ts + 1) t xs :: stack'))
     ==> Block ts a2 xs2 IN
           all_vs refs (t :: ((h :: xs) ++ stack'))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(fun m ->
    MP_TAC(MATCH_MP v_all_vs_list_to_v1
      (CONJ (ARITH_RULE `ts < ts + 1`) m))) THEN
  REWRITE_TAC[APPEND] THEN
  ASM_MESON_TAC[av_in_stack; av_grow]);;

(* and one below the chain's timestamps that is a value of the refs
   and the chain is a value of the refs and the list *)

let av_in_shift = prove
 (`!refs ts t xs stack' t1 a1 xs1.
     t1 < ts /\
     Block t1 a1 xs1 IN all_vs refs (list_to_v ts t xs :: stack')
     ==> Block t1 a1 xs1 IN all_vs refs (t :: (xs ++ stack'))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  STRIP_TAC THEN ASM_MESON_TAC[v_all_vs_list_to_v1]);;

(* while one of the chain's timestamps that is a value of the refs
   and the chain is a value of the chain itself: a value of the
   refs would be one of the list and the stack, which
   blocks_unique_GT_ts says it is not *)

let av_in_mem = prove
 (`!refs ts t xs stack' t1 a1 xs1.
     blocks_unique ts (all_vs refs (t :: (xs ++ stack'))) /\
     ts <= t1 /\ ~(xs1 = []) /\
     Block t1 a1 xs1 IN all_vs refs (list_to_v ts t xs :: stack')
     ==> MEM (Block t1 a1 xs1)
           (v_all_vs (list_to_v ts t xs :: stack'))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun inn ->
    if not (is_binary "IN" (concl inn)) then fail() else
    DISJ_CASES_THEN2 ACCEPT_TAC
      (fun inn2 ->
         ASSUME_TAC inn2 THEN
         ASM_MESON_TAC[GEN_ALL blocks_unique_GT_ts;
                       ARITH_RULE `!a b:num. b <= a ==> a >= b`])
      (SPEC `(t:dataSem_v) :: (xs ++ stack')`
         (MATCH_MP av_in_refs inn))));;

(* the Block of an assumption that says a value is one of the refs
   and a stack, the list it holds, and the assumption that says
   that list is not empty *)

let av_blocks (asl,w) =
  map snd (filter (fun (_,th) ->
    is_binary "IN" (concl th) &&
    hd_is "all_vs" (rand(concl th))) asl);;

let av_xs_of th = last(snd(strip_comb(lhand(concl th))));;

let av_a_of th = el 1 (snd(strip_comb(lhand(concl th))));;

let av_find p (asl,w) =
  snd(find (fun (_,th) -> p (concl th)) asl);;

let av_nn g x =
  av_find (fun t -> is_neg t && is_eq (dest_neg t) &&
                    lhand(dest_neg t) = x) g;;

let Block_NOT_IN_all_vs = prove
 (`!xs t t' a2 xs2 h stack' refs. ~(Block t' a2 xs2 IN all_vs refs (t ::
  h :: (xs ++ stack'))) ==>
     (!m. m > 0 ==> ~(MEM (Block t' a2 xs2) (v_all_vs [list_to_v
       (t' + m) t xs])))`,
  (* the chain of no elements is the value it ends with, which is
     on the stack, and of one more it is a Block of a later
     timestamp, whose values are the element's -- also on the stack
     -- and the rest of the chain's, which the induction
     hypothesis is about at one timestamp more *)
  ((let (_,vsing,_,_) = v_all_vs_clauses () in
    LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[APPEND]) THEN
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    REWRITE_TAC[dataSem_list_to_v_def] THENL
     [DISCH_TAC THEN ASM_MESON_TAC[av_in_cons];
      REWRITE_TAC[vsing; MEM; DE_MORGAN_THM] THEN CONJ_TAC THENL
       [DISCH_THEN(fun eq ->
          MP_TAC(REWRITE_RULE[injectivity "dataSem_v"] eq)) THEN
        ASM_ARITH_TAC;
        DISCH_TAC THEN
        FIRST_ASSUM(fun m ->
          if not (hd_is "MEM" (concl m)) then fail() else
          DISJ_CASES_THEN ASSUME_TAC
            (MATCH_MP MEM_v_all_vs_split m)) THEN
        FIRST_ASSUM(fun nin ->
          if not (is_neg (concl nin)) then fail() else
          FIRST_ASSUM(fun ih ->
            if not (is_forall (concl ih)) then fail() else
            let sh = MATCH_MP av_shrink2 nin in
            let th = MATCH_MP (MATCH_MP ih sh)
                       (ARITH_RULE `m + 1 > 0`) in
            MP_TAC(REWRITE_RULE
              [ARITH_RULE `t' + (m + 1) = (t' + m) + 1`] th))) THEN
        ASM_MESON_TAC[av_in_cons; av_in_tl]]])));;

let v_all_vs_list_to_v2 = prove
 (`!xs t' a1 a2 xs1 xs2 ts t stack' refs.
   MEM (Block t' a1 xs1) (v_all_vs (list_to_v ts t xs :: stack')) /\
     ~(xs1 = []) /\
   MEM (Block t' a2 xs2) (v_all_vs (list_to_v ts t xs :: stack')) /\
     ~(xs2 = []) /\ ~(Block t' a1 xs1 IN all_vs refs (t :: (xs ++
     stack'))) /\ ~(Block t' a2 xs2 IN all_vs refs (t :: (xs ++
     stack'))) ==>
     a1 = a2 /\ xs1 = xs2 /\ t' < ts + LENGTH xs`,
  (* each of the two Blocks is the chain's first Block or a value
     of the rest of the chain, because the hypothesis says neither
     is a value of the list and the stack.  Two first Blocks are
     the same Block; a first Block and one of the rest cannot have
     the same timestamp (av_no_mix); and two of the rest are what
     the induction hypothesis is about *)
  ((let inj = injectivity "dataSem_v" in
    let blk th = hd(snd(strip_comb(concl th))) in
    let not_in x t =
      is_neg t && is_binary "IN" (dest_neg t) &&
      lhand(dest_neg t) = x in
    LIST_INDUCT_TAC THENL
     [REPEAT GEN_TAC THEN DISCH_THEN STRIP_ASSUME_TAC THEN
      RULE_ASSUM_TAC(REWRITE_RULE[dataSem_list_to_v_def; APPEND]) THEN
      ASM_MESON_TAC[av_in_stack];
      REPEAT GEN_TAC THEN DISCH_THEN STRIP_ASSUME_TAC THEN
      W(fun g ->
        let (asl,w) = g in
        let mems = map snd (filter (fun (_,th) ->
          hd_is "MEM" (concl th)) asl) in
        let d th =
          MATCH_MP av_decomp2
            (CONJ th (av_find (not_in (blk th)) g)) in
        let d1 = d (hd mems) and d2 = d (hd(tl mems)) in
        DISJ_CASES_THEN2
          (fun e1 ->
            DISJ_CASES_THEN2
              (fun e2 ->
                STRIP_ASSUME_TAC(REWRITE_RULE[inj] e1) THEN
                STRIP_ASSUME_TAC(REWRITE_RULE[inj] e2) THEN
                ASM_REWRITE_TAC[LENGTH] THEN ASM_ARITH_TAC)
              (fun c2 ->
                ASSUME_TAC c2 THEN
                SUBST_ALL_TAC(CONJUNCT1(REWRITE_RULE[inj] e1)) THEN
                ASM_MESON_TAC[av_no_mix])
              d2)
          (fun c1 ->
            DISJ_CASES_THEN2
              (fun e2 ->
                ASSUME_TAC c1 THEN
                SUBST_ALL_TAC(CONJUNCT1(REWRITE_RULE[inj] e2)) THEN
                ASM_MESON_TAC[av_no_mix])
              (fun c2 ->
                W(fun g2 ->
                  let nin th =
                    MATCH_MP av_shrink (REWRITE_RULE[APPEND]
                      (av_find (not_in (blk th)) g2)) in
                  FIRST_ASSUM(fun ih ->
                    if not (is_forall (concl ih)) then fail() else
                    MP_TAC(MATCH_MP ih
                      (CONJ c1 (CONJ (av_nn g2 (last(snd(strip_comb
                         (blk c1))))) (CONJ c2 (CONJ (av_nn g2
                         (last(snd(strip_comb (blk c2)))))
                           (CONJ (nin c1) (nin c2))))))))) THEN
                REWRITE_TAC[LENGTH] THEN STRIP_TAC THEN
                ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC)
              d2)
          d1)])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_cons_multi = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (t :: (xs ++ stack))) ==>
       blocks_unique (ts + LENGTH xs) (all_vs refs (list_to_v ts
         t xs :: stack))`),
  (* a Block of the chain and the stack is below the chain's
     timestamps, and then it is a value of the list and the stack,
     of which the hypothesis speaks; or it is one of the chain's
     own, and then it is a value of the chain (av_in_mem) that the
     theorem before this one is about *)
  (DISCH_TAC THEN REWRITE_TAC[blocks_unique_def] THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   W(fun (asl,w) ->
     let third = rand(rand w) in
     ASM_CASES_TAC
       (mk_binary "<" (lhand third, lhand(rand third)))) THENL
    [W(fun g ->
       let lt = av_find (fun t -> is_binary "<" t) g in
       let ins = av_blocks g in
       let bu = REWRITE_RULE[blocks_unique_def]
                  (av_find (hd_is "blocks_unique") g) in
       let i1 = MATCH_MP av_in_shift (CONJ lt (el 0 ins))
       and i2 = MATCH_MP av_in_shift (CONJ lt (el 1 ins)) in
       STRIP_ASSUME_TAC(MATCH_MP bu
         (CONJ i1 (CONJ (av_nn g (av_xs_of (el 0 ins)))
           (CONJ i2 (av_nn g (av_xs_of (el 1 ins)))))))) THEN
     ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
     W(fun g ->
       let notlt = av_find (fun t ->
         is_neg t && is_binary "<" (dest_neg t)) g in
       let ins = av_blocks g in
       let bu = av_find (hd_is "blocks_unique") g in
       let t1 = lhand(dest_neg(concl notlt))
       and ts = rand(dest_neg(concl notlt)) in
       let le = MP (ARITH_RULE (mk_imp(concl notlt,
                  mk_binary "<=" (ts,t1)))) notlt in
       let ge = MP (ARITH_RULE (mk_imp(concl notlt,
                  mk_binary ">=" (t1,ts)))) notlt in
       let mem inn = MATCH_MP av_in_mem
         (CONJ bu (CONJ le (CONJ (av_nn g (av_xs_of inn)) inn))) in
       let notin inn = SPEC (av_a_of inn)
         (MATCH_MP (GEN_ALL blocks_unique_GT_ts)
            (CONJ bu (CONJ ge (av_nn g (av_xs_of inn))))) in
       STRIP_ASSUME_TAC(MATCH_MP (GEN_ALL v_all_vs_list_to_v2)
         (CONJ (mem (el 0 ins)) (CONJ (av_nn g (av_xs_of (el 0 ins)))
           (CONJ (mem (el 1 ins)) (CONJ (av_nn g
             (av_xs_of (el 1 ins)))
             (CONJ (notin (el 0 ins)) (notin (el 1 ins))))))))) THEN
     ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]));;

(* the names of record fields that this statement uses for
