let cons_multi_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf ((t :: xs) ++ stack) refs
  (roots,heap,be,a,sp,sp1,gens) limit ts /\
     3 * LENGTH xs <= sp /\ ~(xs = []) ==>
        (?rt rs roots2 heap1 heap2.
          let Allocd = list_to_BlockReps conf rt a rs in
            (roots = (rt :: rs) ++ roots2) /\ (LENGTH rs = LENGTH
              xs) /\
            heap = heap1 ++ heap_expand (sp + sp1) ++ heap2 /\
            a = heap_length heap1 /\
            abs_ml_inv conf
              (list_to_v ts t xs :: stack) refs
              (gc_shared_Pointer a (wordLang_Word (ptr_bits conf
                cons_tag 2)) :: roots2,
               heap1 ++ Allocd ++ heap_expand ((sp + sp1) -
                 heap_length Allocd) ++ heap2,be,
               a + heap_length Allocd,sp - heap_length
                 Allocd,sp1,gens) limit (ts + LENGTH xs))`),
  (* the attempt: the proof of the source names abs_ml_inv_def,
     bc_stack_ref_inv_def, LIST_REL_SPLIT1, LIST_REL_LENGTH,
     unused_space_inv_def, heap_lookup_SPLIT.  What is here rewrites
     with them and closes by arithmetic, and the cheat is behind it
     until the proof is written.  A MESON over them is what the next
     round adds; it costs a load ten minutes to have it in every
     attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def;
       LIST_REL_SPLIT1; LIST_REL_LENGTH; unused_space_inv_def;
       heap_lookup_SPLIT] THEN
     TRY ASM_ARITH_TAC)));;

