let walk_EL = prove
 (`!vs ptr ps v ts.
     v_inv c v refs (gc_shared_Pointer ptr (wordLang_Word (ptr_bits c
       cons_tag 2)),f,tf,heap) /\
     v_to_list v = SOME vs /\ ~(vs = []) /\
     data_to_word_memoryProof_walk c heap ptr (LENGTH vs) = ps ==>
     (!n. SUC n < LENGTH vs ==>
       (?x.
         heap_lookup (EL n ps) heap =
           SOME (BlockRep cons_tag [x;
             gc_shared_Pointer (EL (SUC n) ps) (wordLang_Word
               (ptr_bits c cons_tag 2))])))`,
  (* the attempt: the proof of the source names
     v_to_list_SOME_CONS_IMP, v_inv_def, v_to_list_def,
     v_inv_v_to_list_lemma, BlockRep_def,
     data_to_word_memoryProof_walk_def.  What is here rewrites with
     them and closes by arithmetic, and the cheat is behind it until
     the proof is written.  A MESON over them is what the next round
     adds; it costs a load ten minutes to have it in every attempt
     and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[v_to_list_SOME_CONS_IMP; v_inv_def;
       v_to_list_def; v_inv_v_to_list_lemma; BlockRep_def;
       data_to_word_memoryProof_walk_def] THEN
     TRY ASM_ARITH_TAC)));;

let v_to_list_same_LENGTH = prove
 (`!xs x ys v1 v2 ts1 ts2.
     v_inv c v1 refs (x,f,tf,heap) /\
     v_inv c v2 refs (x,f,tf,heap) /\
     v_to_list v1 = SOME xs /\
     v_to_list v2 = SOME ys ==>
     LENGTH xs = LENGTH ys`,
  (* two values with the same root have lists of the same length:
     the induction is on the first list.  Of an empty one the value
     is the Block of nil_tag, whose root is a Data, and of a cons
     it is the Block of cons_tag, whose root is a Pointer, so the
     two lists are empty together; and when both are a cons the
     roots are the same pointer, so the heap gives them the same
     BlockRep, whose second element is the root of both tails *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let safep p th = (try p th with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* an ALL2 whose first list is a cons *)
    let all2cons1 = prove
     (`!P h t (l:(B)list).
         ALL2 P (CONS (h:A) t) l <=>
         ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
      REPEAT GEN_TAC THEN
      STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
      REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
    (* a value whose list is empty is the Block of nil_tag, and one
       whose list is a cons is the Block of cons_tag of two *)
    let vnil =
      FIRST_X_ASSUM(fun th ->
        if hd_is "dataSem_v_to_list" (lhs (concl th)) &&
           hd_is "NIL" (rand (rhs (concl th)))
        then MP_TAC(REWRITE_RULE[v_to_list_SOME_NIL_IFF] th)
        else fail()) THEN
      DISCH_THEN(CHOOSE_THEN SUBST_ALL_TAC) in
    let vcons =
      FIRST_X_ASSUM(fun th ->
        if hd_is "dataSem_v_to_list" (lhs (concl th)) &&
           hd_is "CONS" (rand (rhs (concl th)))
        then MP_TAC(SPEC_ALL(MATCH_MP
               v_to_list_SOME_CONS_IMP th))
        else fail()) THEN
      DISCH_THEN STRIP_ASSUME_TAC THEN
      FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) && is_var (lhs (concl e)) &&
           hd_is "dataSem_Block" (rhs (concl e))
        then SUBST_ALL_TAC e else fail()) in
    (* the invariants of the values, taken apart *)
    let splitinv =
      RULE_ASSUM_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL;
                                  all2cons1; CONJUNCT1 ALL2_DEF]) THEN
      REPEAT(FIRST_X_ASSUM(fun th ->
        if is_conj (concl th) || is_exists (concl th)
        then STRIP_ASSUME_TAC th else fail())) THEN
      REPEAT(FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) && is_var (lhs (concl e)) &&
           (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
        then SUBST_ALL_TAC e else fail())) in
    (* a Data and a Pointer of the same root is a contradiction *)
    let clash =
      FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
        CONTR_TAC(REWRITE_RULE[distinctness "heap_address"]
                    (TRANS (SYM e1) e2)))) in
  LIST_INDUCT_TAC THEN
    REPEAT GEN_TAC THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    CASES_ON_NAME "ys" THEN
    REWRITE_TAC[LENGTH] THEN
    TRY(vnil THEN vcons THEN splitinv THEN clash THEN NO_TAC) THEN
    TRY(vcons THEN vnil THEN splitinv THEN clash THEN NO_TAC) THEN
    vcons THEN
    vcons THEN
    splitinv THEN
    W(fun (asl,w) ->
      let pes = filter (fun (_,th) -> safep (fun t ->
        is_eq (concl t) && is_var (lhs (concl t)) &&
        hd_is "gc_shared_Pointer" (rhs (concl t))) th) asl in
      MP_TAC(REWRITE_RULE[injectivity "heap_address"]
               (TRANS (SYM (snd (el 0 pes))) (snd (el 1 pes))))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC (K ALL_TAC)) THEN
    W(fun (asl,w) ->
      let hls = filter (fun (_,th) -> safep (fun t ->
        hd_is "heap_lookup" (lhs (concl t))) th) asl in
      MP_TAC(REWRITE_RULE[BlockRep_def; injectivity "option";
                          injectivity "heap_element"; CONS_11;
                          PAIR_EQ; LENGTH]
               (TRANS (SYM (snd (el 0 hls))) (snd (el 1 hls))))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    REPEAT(FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         is_var (rhs (concl e))
      then SUBST_ALL_TAC e else fail())) THEN
    REWRITE_TAC[SUC_INJ] THEN
    W(fun (asl,w) ->
      MATCH_MP_TAC (grab asl (fun th -> is_forall (concl th)))) THEN
    W(fun (asl,w) ->
      let cs = conjuncts (snd(strip_exists w)) in
      let pick lst = grab asl (fun th -> safep (fun u ->
        hd_is "dataSem_v_to_list" (lhs (concl u)) &&
        rand (rhs (concl u)) = lst) th) in
      let vl1 = pick (rand (rhs (el 2 cs))) in
      let vl2 = pick (rand (rhs (el 3 cs))) in
      let w1 = rand (lhs (concl vl1)) in
      let w2 = rand (lhs (concl vl2)) in
      let vi1 = grab asl (fun th ->
        hd_is "v_inv" (concl th) &&
        el 1 (snd(strip_comb (concl th))) = w1) in
      let addr = fst(dest_pair
        (el 3 (snd(strip_comb (concl vi1))))) in
      MAP_EVERY EXISTS_TAC [addr; w1; w2]) THEN
    ASM_REWRITE_TAC[]));;

let block_drop_def = cake_define
  `block_drop x1 v =
      match (x1,v) with
        (0,v) -> SOME v
      | (SUC n,(Block ts tag [h; vl]:dataSem_v)) -> block_drop n vl
      | (_115,_116) -> NONE`;;

let v_to_list_DROP = prove
 (`!vs ptr ps k v ts.
   v_inv c v refs (gc_shared_Pointer ptr (wordLang_Word (ptr_bits c
     cons_tag 2)),f,tf,heap) /\
   v_to_list v = SOME vs /\ ~(vs = []) /\
   data_to_word_memoryProof_walk c heap ptr (LENGTH vs) = ps /\
   ALL_DISTINCT ps /\
   k < LENGTH vs ==>
   v_inv c (THE (block_drop k v)) refs
     (gc_shared_Pointer (EL k ps) (wordLang_Word (ptr_bits c
       cons_tag 2)),f,tf,heap)`,
  (* the attempt: the proof of the source names v_inv_def,
     block_drop_def, BlockRep_def, v_to_list_SOME_CONS_IMP,
     v_inv_v_to_list_lemma, data_to_word_memoryProof_walk_def.  What
     is here rewrites with them and closes by arithmetic, and the
     cheat is behind it until the proof is written.  A MESON over
     them is what the next round adds; it costs a load ten minutes
     to have it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[v_inv_def; block_drop_def; BlockRep_def;
       v_to_list_SOME_CONS_IMP; v_inv_v_to_list_lemma;
       data_to_word_memoryProof_walk_def] THEN
     TRY ASM_ARITH_TAC)));;

let block_drop_DROP = prove
 (`!n v vs.
   v_to_list v = SOME vs /\ n < LENGTH vs ==> v_to_list (THE
     (block_drop n v)) = SOME (DROP n vs)`,
  (* induction on the number: a drop of none is the value itself,
     and one more goes down the tail of the cons that the list of
     the value is, which v_to_list_SOME_CONS_IMP names *)
  (let suc1 = ARITH_RULE `SUC n - 1 = n` in
   INDUCT_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THENL
    [REWRITE_TAC[block_drop_def] THEN MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[THE; DROP_0];
     CASES_ON_NAME "vs" THENL
      [FIRST_ASSUM(fun th -> CONTR_TAC(REWRITE_RULE[LENGTH; LT] th));
       ALL_TAC] THEN
     FIRST_ASSUM(fun th ->
       MP_TAC(SPEC_ALL(MATCH_MP v_to_list_SOME_CONS_IMP th))) THEN
     DISCH_THEN(X_CHOOSE_THEN `ts':num`
       (X_CHOOSE_THEN `ys:dataSem_v` STRIP_ASSUME_TAC)) THEN
     REPEAT SUBST_LHS_TAC THEN
     ONCE_REWRITE_TAC[block_drop_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[DROP; NOT_SUC; suc1] THEN
     FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
     RULE_ASSUM_TAC(REWRITE_RULE[LENGTH]) THEN ARITH_ASM_TAC]));;

