  (* the walk of the heap from the pointer of the value gives one
     pointer per element of the list, they are distinct, and each
     holds a BlockRep of two: three words of the heap each.  The
     list of pointers is the walk itself, which the first premise
     of walk_LENGTH names, so the theorem is matched against the
     invariant and the walk is read off that instance *)
  (let wl = walk_LENGTH
   and wad = walk_ALL_DISTINCT
   and whl = walk_heap_lookup
   and hlb = heap_length_Blocks in
   STRIP_TAC THEN
   FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun vl -> FIRST_ASSUM(fun ne ->
     MP_TAC(MATCH_MP v_inv_v_to_list_lemma
              (CONJ vi (CONJ vl ne)))))) THEN
   STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
   FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun vl -> FIRST_ASSUM(fun ne ->
     let w1 = PART_MATCH (hd o conjuncts o lhand) wl (concl vi) in
     let wt = lhs (last (conjuncts (lhand (concl w1)))) in
     let prem = CONJ vi (CONJ vl (CONJ ne (REFL wt))) in
     let len = SPEC_ALL(MATCH_MP wl prem)
     and ad = SPEC_ALL(MATCH_MP wad prem)
     and ev = SPEC_ALL(MATCH_MP whl prem) in
     MP_TAC(REWRITE_RULE[len] (MATCH_MP hlb (CONJ ad ev)))))) THEN
   REWRITE_TAC[]));;

(* ------------------------------------------------------------------------- *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_list_limit = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp0 st m dm ((v,(w:'a word_loc)) :: vars)
  /\
     v_to_list v = SOME xs /\
     good_dimindex (:'a) ==>
     3 * (LENGTH xs + 1) * (dimindex (:'a) DIV 8) < dimword (:'a)`),
  (* the heap holds three words per element of the list, and the
     heap in memory leaves room for the limit and three more *)
  (let mul_le = prove
    (`!a b d x. 3 * a <= b /\ (b + 3) * d + 1 < x
                ==> 3 * (a + 1) * d < x`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     MATCH_MP_TAC LET_TRANS THEN EXISTS_TAC `(b + 3) * d` THEN
     CONJ_TAC THENL
      [REWRITE_TAC[MULT_ASSOC;
                   ARITH_RULE `3 * (a + 1) = 3 * a + 3`;
                   LE_MULT_RCANCEL] THEN
       DISJ1_TAC THEN ASM_ARITH_TAC;
       ASM_ARITH_TAC]) in
   MEMORY_REL_TAC THEN USE_CHANGED [heap_ok_def] THEN
   STRIP_TAC THEN
   SUBGOAL_THEN `3 * LENGTH (xs:(dataSem_v)list) <= limit'`
     MP_TAC THENL
    [ASM_CASES_TAC `xs:(dataSem_v)list = []` THENL
      [ASM_REWRITE_TAC[LENGTH] THEN ARITH_TAC;
       FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun vl ->
         FIRST_ASSUM(fun ne ->
           MP_TAC(MATCH_MP v_to_list_heap_length
                    (CONJ vi (CONJ vl ne)))))) THEN
       ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
   DISCH_TAC THEN
   FIRST_ASSUM(fun le -> FIRST_ASSUM(fun dw ->
     MATCH_ACCEPT_TAC(MATCH_MP mul_le (CONJ le dw))))));;

let build_part_words_def = cake_define_list
  [`build_part_words c m (Int i:const_part) (offset:'a word) =
      (if small_int (:'a) i then SOME (wordLang_Word (Smallnum
        i),[]) else let (sign,ws) = i2mw i in
              match encode_header c (w2n (b2w sign << 2 || ((n2w
                3):'a word))) (LENGTH ws) with NONE -> NONE | SOME hd ->
                SOME (make_ptr c offset ((n2w 0):'a word) (LENGTH ws),
                              MAP wordLang_Word (hd :: ws)))`;
   `build_part_words c m (Con t ns:const_part) (offset:'a word) =
      (if NULL ns then
         if t < dimword (:'a) DIV 16 then SOME (wordLang_Word (n2w
           (16 * t + 2)),[]) else NONE else
         match encode_header c (4 * t) (LENGTH ns) with NONE -> NONE
           | SOME hd -> SOME (make_cons_ptr c offset t (LENGTH ns),
                            wordLang_Word hd :: (MAP m ns)))`;
   `build_part_words c m (W64 w:const_part) (offset:'a word) =
      (let ws = (if dimindex (:'a) < 64 then [((63 >< 32) w); ((31
        >< 0) w)] else [((63 >< 0) w):'a word]) in
         match encode_header c 3 (LENGTH ws) with NONE -> NONE |
           SOME hd -> SOME (make_ptr c offset ((n2w 0):'a word) (LENGTH
           ws),
                            MAP wordLang_Word (hd :: ws)))`;
   `build_part_words c m (closLang_Str s:const_part) (offset:'a word) =
      (let bytes = MAP (n2w o ORD) (explode s) in
       let n = LENGTH bytes in
       let hd = make_byte_header c T n in
       let ws = write_bytes bytes (REPLICATE (byte_len (:'a) n) (n2w
         0)) (be c) in
         if byte_len (:'a) n < 2 EXP (dimindex (:'a) - 4) /\
            byte_len (:'a) n < 2 EXP
              data_to_word_config_len_size c then SOME (make_ptr c
              offset ((n2w 0):'a word) (byte_len (:'a) n),MAP
              wordLang_Word (hd :: ws)) else NONE)`];;

let build_words_def = cake_define_list
  [`build_words c m i [] (off:'a word) = SOME (m (i - (1:num)),[])`;
   `build_words c m i (x :: parts') (off:'a word) =
      (match build_part_words c m x off with NONE -> NONE | SOME
        (w,xs) ->
        (match build_words c ((i =+ w) m) (i + 1) parts' (off +
          bytes_in_word * n2w (LENGTH xs)) with NONE -> NONE | SOME
          (r,ys) -> SOME (r,xs ++ ys)))`];;

let do_part_SOME_IMP_SOME = prove
 (`do_part map0 h refs (SOME ts) = (x,s1,ts1) ==> (?ts'. ts1 = SOME
  ts')`,
  (* every clause of do_part gives the timestamp back as a SOME,
     and the one of a Str gives it under a let *)
  (CASES_ON_NAME "h" THEN
   REWRITE_TAC[dataSem_do_part_def] THEN
   REPEAT(CHANGED_TAC
     (REWRITE_TAC[PAIR_EQ] THEN
      CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
      REPEAT COND_CASES_TAC THEN REPEAT STRIP_TAC)) THEN
   RULE_ASSUM_TAC(CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
   RULE_ASSUM_TAC(REWRITE_RULE[PAIR_EQ]) THEN
   REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC)) THEN
   ASM_MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_IMP_MAP_UPDATE = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
             (((b,w) :: MAP (\k. (map0 k,map0' k)) ks) ++ vars) ==>
     memory_rel c be ts refs sp st m dm
             (MAP (\k. ((i =+ b) map0 k,((i =+ w) map0' k))) ks
               ++ vars)`),
  (MATCH_MP_TAC memory_rel_rearrange THEN
   GEN_TAC THEN REWRITE_TAC[MEM_APPEND; MEM_MAP; MEM] THEN
   STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
   REWRITE_TAC[UPDATE] THEN
   CONV_TAC(DEPTH_CONV BETA_CONV) THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   ASM_MESON_TAC[]));;

(* ZIP_MAP_MAP[local] *)
let data_to_word_memoryProof_ZIP_MAP_MAP = prove
 (`!xs. ZIP (MAP f xs) (MAP g xs) = MAP (\k. (f k,g k)) xs`,
  (let aux = prove
    (`!(f:A->B) (g:A->C) xs.
        ZIP (MAP f xs) (MAP g xs) = MAP (\k. (f k,g k)) xs`,
     GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[MAP; ZIP]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

(* [local] *)
let LENGTH_n2mw_LE_num_size = prove
 (`!n m. good_dimindex (:'a) /\ n <= m ==> SUC (LENGTH (n2mw n:('a
  word) list)) <= num_size m`,
  (* the words of a number are at most its num_size: both
     recursions divide, n2mw by the size of a word and num_size by
     two to the thirty-two, and a word of a good size is at least
     that wide -- so a complete induction on the number does it,
     with the clause of num_size at a number below two to the
     thirty-two (which is two, and a number that small is one word)
     for the base.  The source has the induction theorem of the
     definition, which the port's cake_define does not make *)
  ((* the quotient of a number by two or more is smaller *)
   let divlt = prove
    (`!n d. ~(n = 0) /\ 2 <= d ==> n DIV d < n`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     MP_TAC(SPECL [`n:num`; `d:num`] DIVISION) THEN
     ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     ABBREV_TAC `q = n DIV d` THEN ABBREV_TAC `r = n MOD d` THEN
     STRIP_TAC THEN
     SUBGOAL_THEN `2 * q <= d * q` MP_TAC THENL
      [ASM_SIMP_TAC[LE_MULT_RCANCEL]; ALL_TAC] THEN
     ASM_ARITH_TAC) in
   (* a word of a good size holds a number of thirty-two bits *)
   let dw32 = prove
    (`good_dimindex (:'a) ==> 2 EXP 32 <= dimword (:'a)`,
     REWRITE_TAC[good_dimindex_def; dimword] THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     CONV_TAC NUM_REDUCE_CONV) in
   let usedw32 =
     FIRST_ASSUM(fun gd -> MATCH_ACCEPT_TAC(MATCH_MP dw32 gd)) in
   MATCH_MP_TAC num_WF THEN
   X_GEN_TAC `n:num` THEN DISCH_TAC THEN
   X_GEN_TAC `m:num` THEN STRIP_TAC THEN
   ONCE_REWRITE_TAC[n2mw_def] THEN
   ONCE_REWRITE_TAC[num_size_def] THEN
   ASM_CASES_TAC `n = 0` THEN
   ASM_REWRITE_TAC[LENGTH] THEN
   TRY(COND_CASES_TAC THEN ARITH_TAC THEN NO_TAC) THEN
   REWRITE_TAC[LENGTH] THEN
   COND_CASES_TAC THEN
   (* m is below two to the thirty-two, and then so is n *)
   TRY(SUBGOAL_THEN `n DIV dimword (:'a) = 0` SUBST1_TAC THENL
        [MATCH_MP_TAC DIV_LT THEN
         TRANS_TAC LTE_TRANS `2 EXP 32` THEN
         CONJ_TAC THENL [ASM_ARITH_TAC; usedw32];
         ALL_TAC] THEN
       REWRITE_TAC[n2mw_def; LENGTH] THEN ARITH_TAC THEN
       NO_TAC) THEN
   (* and otherwise the induction hypothesis, at the quotients *)
   MATCH_MP_TAC(ARITH_RULE `k <= l ==> SUC k <= 1 + l`) THEN
   FIRST_X_ASSUM(fun ih ->
     MP_TAC(SPEC `n DIV dimword (:'a)` ih)) THEN
   ANTS_TAC THENL
    [MATCH_MP_TAC divlt THEN ASM_REWRITE_TAC[] THEN
     TRANS_TAC LE_TRANS `2 EXP 32` THEN
     CONJ_TAC THENL [CONV_TAC NUM_REDUCE_CONV; usedw32];
     ALL_TAC] THEN
   DISCH_THEN(fun th -> MP_TAC(SPEC `m DIV 2 EXP 32` th)) THEN
   ASM_REWRITE_TAC[] THEN
   ANTS_TAC THENL
    [TRANS_TAC LE_TRANS `m DIV dimword (:'a)` THEN CONJ_TAC THENL
      [MATCH_MP_TAC DIV_MONO THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[dimword; EXP_EQ_0; ARITH];
       MATCH_MP_TAC DIV_MONO2 THEN CONJ_TAC THEN
       TRY(REWRITE_TAC[EXP_EQ_0; ARITH] THEN NO_TAC) THEN
       usedw32];
     DISCH_THEN ACCEPT_TAC]));;

let least_notin_domain = prove
 (`~((LEAST (\ptr. ~(ptr IN domain refs))) IN domain (refs:'a spt))`,
  (* the domain of a tree is finite, so some number is not in it,
     and the least number that is not in it is one of those *)
  (let fin = prove
    (`!t:A spt. FINITE (domain t)`,
     MATCH_MP_TAC spt_INDUCT THEN
     SIMP_TAC[domain_def; FINITE_EMPTY; FINITE_INSERT;
              FINITE_UNION; FINITE_IMAGE]) in
   let notin = prove
    (`!s:num->bool. FINITE s ==> ?n. ~(n IN s)`,
     GEN_TAC THEN REWRITE_TAC[num_FINITE] THEN
     DISCH_THEN(X_CHOOSE_TAC `a:num`) THEN
     EXISTS_TAC `a + 1` THEN DISCH_TAC THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `a + 1`) THEN
     ASM_REWRITE_TAC[] THEN ARITH_TAC) in
   let least_lemma = prove
    (`!s:num->bool. FINITE s ==> ~((LEAST (\n. ~(n IN s))) IN s)`,
     GEN_TAC THEN DISCH_TAC THEN
     MP_TAC(ISPEC `\n:num. ~(n IN s)` MINIMAL) THEN
     REWRITE_TAC[LEAST] THEN
     ASM_SIMP_TAC[notin] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT1 th])) in
   MATCH_ACCEPT_TAC (MATCH_MP least_lemma (SPEC_ALL fin))));;

let _ = do_list hide_constant ["free"];;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_do_build = prove
 (cake_as_vars (fun () ->
    `!parts' i st free' curr sp map0 map0' refs ts refs1 v m v ws.
       do_build map0 i parts' refs (SOME ts) = (v,refs1,SOME ts1)
         /\
       build_words c map0' i parts' (free' - (curr:'a word)) = SOME
         (w,ws) /\
       SUM (MAP part_space_req parts') <= sp /\
       FLOOKUP st NextFree = SOME (wordLang_Word free') /\
       FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
       (!ks. memory_rel c be ts refs sp st m dm (MAP (\k. (map0
         k,(map0' k))) ks ++ vars)) /\
       good_dimindex (:'a) ==>
       (?m1.
         let nf = free' + bytes_in_word * n2w (LENGTH ws) in
           memory_rel c be ts1 refs1 (sp - LENGTH ws)
             (st |+ (NextFree,wordLang_Word nf)) m1 dm ((v,w) ::
               vars) /\
           data_to_word_memoryProof_store_list free' ws m dm =
             SOME m1)`),
  (* the attempt: the proof of the source names do_build_def,
     build_words_def, memory_rel_def, heap_in_memory_store_def,
     FLOOKUP_UPDATE, data_to_word_memoryProof_store_list_def.  What
     is here rewrites with them and closes by arithmetic, and the
     cheat is behind it until the proof is written.  A MESON over
     them is what the next round adds; it costs a load ten minutes
     to have it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[do_build_def; build_words_def;
       memory_rel_def; heap_in_memory_store_def; FLOOKUP_UPDATE;
       data_to_word_memoryProof_store_list_def] THEN
     TRY ASM_ARITH_TAC)));;

let word_and_lsr_0 = prove
 (`(!i. k <= i /\ i < dimindex (:'a) ==> ~(FAPPLY w i)) ==> w && n <<
  k = ((n2w 0):'a word)`,
  (REWRITE_TAC[word_index] THEN DISCH_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_0; BIT_WORD_AND;
               BIT_WORD_SHL] THEN
   REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM(MP_TAC o SPEC `i:num`) THEN ASM_REWRITE_TAC[]));;

let byte_aligned_IMP_shift = prove
 (`byte_aligned (w:'a word) /\ good_dimindex (:'a) ==>
   (?v. w = v << backend_common_word_shift (:'a))`,
  (* a byte aligned word is its own slice above the shift of the
     dimindex, and such a slice is the word shifted down and up
     again *)
  (let LOG2_RED =
     REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                          NUM_REDUCE_CONV THENC REWRITE_CONV[])) in
   let key = prove
    (`!p (w:(N)word). word_slice (dimindex (:N) - 1) p w = w
        ==> w = word_shl (word_ushr w p) p`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(fun th -> GEN_REWRITE_TAC LAND_CONV [GSYM th]) THEN
     REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
                 BIT_WORD_SHL; BIT_WORD_SUBWORD; BIT_WORD_USHR] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THEN ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN
       `i - p < MIN ((dimindex (:N) - 1 + 1) - p) (dimindex (:N))`
       (fun th -> REWRITE_TAC[th]) THENL
      [REWRITE_TAC[ARITH_RULE
         `MIN a b = if a <= b then a else b`] THEN
       COND_CASES_TAC THEN ASM_ARITH_TAC;
       REWRITE_TAC[ARITH_RULE `p + (i - p) = (i - p) + p`]]) in
   REWRITE_TAC[byte_aligned_def; aligned_def;
               align_def] THEN
   STRIP_TAC THEN
   SUBGOAL_THEN `LOG2 (dimindex (:'a) DIV 8) =
                 backend_common_word_shift (:'a)`
     (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THENL
    [FIRST_ASSUM(fun g -> MP_TAC g) THEN
     REWRITE_TAC[good_dimindex_def;
                 word_shift_def] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
     CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED;
     EXISTS_TAC
       `word_ushr (w:'a word) (backend_common_word_shift (:'a))` THEN
     MATCH_MP_TAC key THEN FIRST_ASSUM ACCEPT_TAC]));;

let make_cons_ptr_add = prove
 (`byte_aligned n /\ good_dimindex (:'a) /\ backend_common_word_shift
  (:'a) <= shift_length c ==>
   make_cons_ptr c n tag len =
   wordLang_Word (n << (shift_length c - backend_common_word_shift
     (:'a)) +
         (get_lowerbits c (wordLang_Word (ptr_bits c tag len)):'a
           word))`,
  (* and the same for the pointer of a cons, where the one that
     the lower bits already hold is absorbed first *)
  (let lb1 = prove
     (`!c (x:(N)word).
         word 1 || get_lowerbits c (wordLang_Word x) =
         get_lowerbits c (wordLang_Word x)`,
      REPEAT GEN_TAC THEN REWRITE_TAC[get_lowerbits_def] THEN
      MATCH_REDUCE_TAC THEN CONV_TAC WORD_BITWISE_RULE) in
    STRIP_TAC THEN
    REWRITE_TAC[make_cons_ptr_def] THEN
    AP_TERM_TAC THEN
    REWRITE_TAC[lb1] THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC WORD_ADD_OR THEN
    FIRST_ASSUM(fun ba -> FIRST_ASSUM(fun gd ->
      MP_TAC(MATCH_MP byte_aligned_IMP_shift
        (CONJ ba gd)))) THEN
    DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST_ALL_TAC) THEN
    REWRITE_TAC[get_lowerbits_def] THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_OR;
                BIT_WORD_1; BIT_WORD_0; BIT_WORD_SHL; word_bits;
                BIT_WORD_SUBWORD;
                ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    REWRITE_TAC[shift_length_def;
                small_shift_length_def] THEN
    REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
    POP_ASSUM_LIST(fun ths -> MAP_EVERY MP_TAC ths) THEN
    REWRITE_TAC[shift_length_def;
                small_shift_length_def] THEN
    ARITH_TAC));;

let make_ptr_add = prove
 (`byte_aligned n /\ good_dimindex (:'a) /\ backend_common_word_shift
  (:'a) <= shift_length c ==>
   make_ptr c n tag len =
   wordLang_Word (n << (shift_length c - backend_common_word_shift
     (:'a)) + ((n2w 1):'a word))`,
  (* a byte aligned word is a word shifted up by the shift, so the
     pointer it makes has its lowest bit clear and the or with one
     is an add *)
  (STRIP_TAC THEN
    REWRITE_TAC[make_ptr_def] THEN
    AP_TERM_TAC THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC WORD_ADD_OR THEN
    FIRST_ASSUM(fun ba -> FIRST_ASSUM(fun gd ->
      MP_TAC(MATCH_MP byte_aligned_IMP_shift
        (CONJ ba gd)))) THEN
    DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST_ALL_TAC) THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_1;
                BIT_WORD_0; BIT_WORD_SHL] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(fun gd ->
      if can (find_term (fun t ->
        try fst(dest_const t) = "good_dimindex"
        with Failure _ -> false))
        (concl gd)
      then MP_TAC gd else failwith "no") THEN
    REWRITE_TAC[good_dimindex_def;
                word_shift_def] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    POP_ASSUM_LIST(fun ths -> MAP_EVERY MP_TAC ths) THEN ARITH_TAC));;

let word_cond_add_def = cake_define
  `word_cond_add c a x3 =
      match x3 with
        (F,x) -> (x:'a word_loc)
      | (T,wordLang_Word w) -> wordLang_Word (w + a << (shift_length
        c - backend_common_word_shift (:'a)))
      | (T,other) -> other`;;

(* the port's own: what the four lemmas about the words of a
   constant part share.  HOL4 gets the sum of two aligned words
   from alignmentTheory; here a shifted word is aligned by the
   definition of align, and each aligned word is a shifted one
   (byte_aligned_IMP_shift). *)

let LOG2_RED =
  REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                       NUM_REDUCE_CONV THENC REWRITE_CONV[]));;

let shl_add = prove
 (`!(a:N word) b n.
     word_shl (word_add a b) n =
     word_add (word_shl a n) (word_shl b n)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_SHL; VAL_WORD_ADD] THEN
  CONV_TAC MOD_DOWN_CONV THEN
  REWRITE_TAC[LEFT_ADD_DISTRIB] THEN CONV_TAC MOD_DOWN_CONV THEN
  REWRITE_TAC[]);;

let byte_aligned_shl = prove
 (`good_dimindex (:'a) ==>
   byte_aligned (word_shl (u:'a word)
                   (backend_common_word_shift (:'a)))`,
  REWRITE_TAC[byte_aligned_def; aligned_def; align_def] THEN
  STRIP_TAC THEN
  (SUBGOAL_THEN `LOG2 (dimindex (:'a) DIV 8) =
                 backend_common_word_shift (:'a)` SUBST1_TAC THENL
    [FIRST_ASSUM MP_TAC THEN
     REWRITE_TAC[good_dimindex_def; word_shift_def] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
     CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED;
     ALL_TAC]) THEN
  REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
              BIT_WORD_SHL; BIT_WORD_SUBWORD;
              ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  REPEAT COND_CASES_TAC THEN
  ASM_CASES_TAC `word_shift (:'a) <= i` THEN ASM_REWRITE_TAC[] THEN
  (SUBGOAL_THEN
     `(word_shift (:'a) + i - word_shift (:'a)) -
      word_shift (:'a) = i - word_shift (:'a)` SUBST1_TAC THENL
    [ASM_ARITH_TAC; ALL_TAC]) THEN
  (SUBGOAL_THEN
     `i - word_shift (:'a) <
        (dimindex (:'a) - 1 + 1) - word_shift (:'a) /\
      word_shift (:'a) <= word_shift (:'a) + i - word_shift (:'a) /\
      word_shift (:'a) + i - word_shift (:'a) < dimindex (:'a)`
     STRIP_ASSUME_TAC THENL
    [FIRST_ASSUM MP_TAC THEN
     REWRITE_TAC[good_dimindex_def; word_shift_def] THEN
     ASM_ARITH_TAC;
     ALL_TAC]) THEN
  ASM_REWRITE_TAC[] THEN
  (SUBGOAL_THEN `i - word_shift (:'a) < dimindex (:'a)`
     ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
  ASM_REWRITE_TAC[]);;

let byte_aligned_add = prove
 (`good_dimindex (:'a) /\ byte_aligned (a:'a word) /\ byte_aligned b
   ==> byte_aligned (a + b)`,
  STRIP_TAC THEN
  FIRST_ASSUM(fun gd ->
    if not (hd_is "good_dimindex" (concl gd)) then fail() else
    REPEAT(FIRST_X_ASSUM(fun ba ->
      if not (hd_is "byte_aligned" (concl ba)) then fail() else
      CHOOSE_THEN SUBST_ALL_TAC
        (MATCH_MP byte_aligned_IMP_shift (CONJ ba gd)))) THEN
    REWRITE_TAC[GSYM shl_add] THEN
    MATCH_ACCEPT_TAC(GEN_ALL(MATCH_MP byte_aligned_shl gd))));;

(* the header of a bignum, which the two definitions write
   differently: the deep embedding takes the sign bit of a word and
   the shallow one the number 7 or 3 *)

let or43 = prove
 (`((n2w 4):'a word) || n2w 3 = n2w 7`, WORD_NUM_BIT_TAC 3);;

let or03 = prove
 (`((n2w 0):'a word) || n2w 3 = n2w 3`, WORD_NUM_BIT_TAC 2);;

let hdr_bits = prove
 (`good_dimindex (:'a) ==>
   w2n ((b2w sign << 2 || (n2w 3)):'a word) =
   (if sign then 7 else 3)`,
  REWRITE_TAC[b2w_def] THEN DISCH_TAC THEN
  STRUCT_CASES_TAC(SPEC `sign:bool` BOOL_CASES_AX) THEN
  REWRITE_TAC[b2n_def; WORD_SHL_WORD] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[or43; or03; VAL_WORD] THEN
  FIRST_ASSUM(fun gd ->
    STRIP_ASSUME_TAC(REWRITE_RULE[good_dimindex_def] gd)) THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV);;

(* what word_cond_add does to a word that is a pointer and to one
   that is not *)

let cond_add_F = prove
 (`!c a x. word_cond_add c a (F,x) = x`,
  REPEAT GEN_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [word_cond_add_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

let cond_add_T = prove
 (`!c a (w:'a word). word_cond_add c a (T,wordLang_Word w) =
     wordLang_Word (w + a << (shift_length c -
       backend_common_word_shift (:'a)))`,
  REPEAT GEN_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [word_cond_add_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

(* the map of the deep embedding with a word put in: what it looks
   up, read as the function of the shallow side with that word put
   in, and the condition of the two maps carried over it *)

let lookup_mem_insert = prove
 (`!m i v j. lookup_mem (insert i v m) j =
             (if j = i then v else lookup_mem m j)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[lookup_mem_def; lookup_insert] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

let upd_lookup = prove
 (`!m i (v:bool#('a word_loc)).
     (\j. SND (lookup_mem (insert i v m) j)) =
     ((i =+ SND v) (\j. SND (lookup_mem m j)))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
  X_GEN_TAC `j:num` THEN REWRITE_TAC[UPDATE] THEN BETA_TAC THEN
  REWRITE_TAC[lookup_mem_insert] THEN
  (ASM_CASES_TAC `(i:num) = j` THENL
    [FIRST_ASSUM SUBST_ALL_TAC THEN REWRITE_TAC[];
     ASM_REWRITE_TAC[] THEN
     (SUBGOAL_THEN `~((j:num) = i)` (fun th -> REWRITE_TAC[th])
        THENL [ASM_MESON_TAC[]; ALL_TAC]) THEN
     REWRITE_TAC[]]));;

let ins_cond = prove
 (`(!j. SND (lookup_mem m1 j) =
        word_cond_add c a (lookup_mem m j)) /\
   SND v = word_cond_add c a w
   ==> (!j. SND (lookup_mem (insert i v m1) j) =
            word_cond_add c a (lookup_mem (insert i w m) j))`,
  STRIP_TAC THEN X_GEN_TAC `j:num` THEN
  REWRITE_TAC[lookup_mem_insert] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[]);;

(* two lists that a map takes to the same list are of one length *)

let len_of_map = prove
 (`!(l1:A list) (l2:B list) f g.
     MAP (f:A->C) l1 = MAP (g:B->C) l2 ==> LENGTH l1 = LENGTH l2`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(MP_TAC o AP_TERM `LENGTH:C list->num`) THEN
  REWRITE_TAC[LENGTH_MAP]);;

(* the witnesses of an existential whose body says what each of
   them is, the assumption that is an induction hypothesis and the
   one that is the condition of the two maps *)

let EXISTS_EQ_TAC =
  W(fun (asl,w) ->
    if not (is_exists w) then fail() else
    let vs,body = strip_exists w in
    let eqs = conjuncts body in
    let wit = map (fun v ->
      lhs(find (fun t -> is_eq t && rhs t = v) eqs)) vs in
    MAP_EVERY EXISTS_TAC wit);;

let is_ih t = is_forall t && is_imp(snd(strip_forall t));;

let is_cond t = is_forall t && is_eq(snd(strip_forall t));;

(* and the call of a recursion in an assumption, split into its
   result and that result into a pair *)

let pw_is_lhs n t = (try hd_is n (lhs t) with Failure _ -> false);;

let pw_has_call n t =
  (try hd_is n (find_term (hd_is n) t) with Failure _ -> false);;

let PW_SPLIT_CALL_TAC n =
  W(fun g ->
    let th = av_find (pw_has_call n) g in
    CASES_ON_TAC (find_term (hd_is n) (concl th))) THEN
  TRY SAFE_MATCH_REDUCE_ASM_TAC THEN
  RULE_ASSUM_TRY (REWRITE_RULE[distinctness "option"]) THEN
  TRY(FIRST_ASSUM CONTR_TAC) THEN
  TRY(W(fun g ->
    let th = av_find (fun t -> pw_is_lhs n t &&
                               hd_is "SOME" (rhs t)) g in
    CASES_ON_TAC (rand(rhs(concl th))))) THEN
  TRY SAFE_MATCH_REDUCE_ASM_TAC THEN
  RULE_ASSUM_TRY (REWRITE_RULE[distinctness "option";
                               injectivity "option"; PAIR_EQ]) THEN
  TRY(FIRST_ASSUM CONTR_TAC) THEN
  TRY SAFE_MATCH_REDUCE_ASM_TAC;;

let part_to_words_add = prove
 (`!part m off a w ws m1.
     byte_aligned off /\ byte_aligned a /\
     good_dimindex (:'a) /\ backend_common_word_shift (:'a) <=
       shift_length c ==>
     part_to_words c m part (off:'a word) = SOME (w,ws) /\
     (!i. SND (lookup_mem m1 i) = word_cond_add c a (lookup_mem m i))
       ==>
     (?v vs. part_to_words c m1 part (off + (a:'a word)) = SOME
       (v,vs) /\
            MAP SND vs = MAP (word_cond_add c a) ws /\
            SND v = word_cond_add c a w)`,
  (* the four kinds of part, each written at the offset and at the
     offset plus a: what is not a pointer is written the same, and
     a pointer has the shifted a added to it, which is what
     word_cond_add does *)
  (REPEAT GEN_TAC THEN STRIP_TAC THEN CASES_ON_NAME "part" THEN
   REWRITE_TAC[part_to_words_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN STRIP_TAC THEN
   TRY PAIRARG_TAC THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
   EVERY_CASE_COND_TAC THEN VAR_EQ_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_REWRITE_TAC[] THEN
   REPEAT(CHANGED_TAC(TRY MATCH_REDUCE_TAC THEN
     REWRITE_TAC[distinctness "option"])) THEN
   REWRITE_TAC[injectivity "option"; PAIR_EQ; GSYM CONJ_ASSOC] THEN
   TRY EXISTS_EQ_TAC THEN
   REWRITE_TAC[cond_add_F; cond_add_T; MAP; GSYM MAP_o; o_DEF] THEN
   ASM_REWRITE_TAC[] THEN
   TRY(ASM_SIMP_TAC[make_ptr_add; make_cons_ptr_add;
                    byte_aligned_add; get_lowerbits_ptrbits]) THEN
   REWRITE_TAC[cond_add_F; cond_add_T] THEN
   TRY(AP_TERM_TAC THEN REWRITE_TAC[shl_add] THEN
       CONV_TAC WORD_RULE)));;

let byte_aligned_bytes_in_word = prove
 (`good_dimindex (:'a) ==>
   byte_aligned (bytes_in_word:'a word)`,
  (* the alignment of a word is the slice that drops its lowest
     bits, and the bytes in a word of a good dimindex are four or
     eight, which have no bit as low as that *)
  (let LOG2_RED =
     REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                          NUM_REDUCE_CONV THENC REWRITE_CONV[])) in
   let slice_lemma = prove
    (`!h p (w:(N)word).
        dimindex (:N) <= h + 1 /\ (!i. i < p ==> ~word_bit i w)
        ==> word_slice h p w = w`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
                 BIT_WORD_SHL; BIT_WORD_SUBWORD] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THENL
      [SUBGOAL_THEN `(p + (i - p) = i) /\
                     i - p < MIN ((h + 1) - p) (dimindex (:N))`
         STRIP_ASSUME_TAC THENL
        [CONJ_TAC THENL
          [ASM_ARITH_TAC;
           REWRITE_TAC[ARITH_RULE
             `MIN a b = if a <= b then a else b`] THEN
           COND_CASES_TAC THEN ASM_ARITH_TAC];
         ASM_REWRITE_TAC[]];
       ASM_REWRITE_TAC[] THEN
       FIRST_X_ASSUM(MP_TAC o SPEC `i:num`) THEN
       ASM_SIMP_TAC[ARITH_RULE `~(p <= i) ==> (i:num) < p`]]) in
   REWRITE_TAC[good_dimindex_def; byte_aligned_def;
               aligned_def; align_def;
               bytes_in_word_def] THEN
   DISCH_THEN(DISJ_CASES_THEN
     (fun th -> SUBST1_TAC th THEN ASSUME_TAC th)) THEN
   CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED THEN
   MATCH_MP_TAC slice_lemma THEN
   (CONJ_TAC THENL
     [ASM_REWRITE_TAC[] THEN ARITH_TAC;
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
        REWRITE_TAC[BIT_WORD] THEN CONV_TAC NUM_REDUCE_CONV THEN
        TRY(REWRITE_TAC[]) THEN TRY(ASM_ARITH_TAC)]])));;

let byte_align_mult_bytes_in_word = prove
 (`good_dimindex (:'a) ==>
   byte_aligned (w * (bytes_in_word:'a word)) /\
   byte_aligned (bytes_in_word * (w:'a word))`,
  (* the bytes in a word are two to the shift, so a multiple of them
     is the word shifted up, and the alignment of a word shifted up
     is the word shifted down and up again, which is the word
     itself *)
  (
   let LOG2_RED =
     REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                          NUM_REDUCE_CONV THENC REWRITE_CONV[])) in
   let slice_shl = prove
    (`!p (w:(N)word).
        word_slice (dimindex (:N) - 1) p w =
        word_shl (word_ushr w p) p`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
                 BIT_WORD_SHL; BIT_WORD_SUBWORD; BIT_WORD_USHR] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THEN ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN
       `i - p < MIN ((dimindex (:N) - 1 + 1) - p) (dimindex (:N))`
       (fun th -> REWRITE_TAC[th]) THENL
      [REWRITE_TAC[ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
       COND_CASES_TAC THEN ASM_ARITH_TAC;
       REWRITE_TAC[ARITH_RULE `p + (i - p) = (i - p) + p`]]) in
   let shl_slice = prove
    (`!p (w:(N)word).
        word_slice (dimindex (:N) - 1) p (word_shl w p) =
        word_shl w p`,
     REPEAT GEN_TAC THEN REWRITE_TAC[slice_shl] THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_SHL; BIT_WORD_USHR] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THEN
     ASM_SIMP_TAC[ARITH_RULE `p <= i ==> (i - p) + p = i`] THEN
     ASM_REWRITE_TAC[BIT_WORD_SHL]) in
   let mul_shl = prove
    (`!p d (w:(N)word). d = 2 EXP p ==> w * n2w d = word_shl w p`,
     REPEAT GEN_TAC THEN DISCH_THEN SUBST1_TAC THEN
     REWRITE_TAC[word_shl] THEN
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM WORD_VAL] THEN
     REWRITE_TAC[GSYM WORD_MUL]) in
   DISCH_TAC THEN
   SUBGOAL_THEN
     `dimindex (:'a) DIV 8 = 2 EXP (LOG2 (dimindex (:'a) DIV 8))`
     ASSUME_TAC THENL
    [FIRST_ASSUM(DISJ_CASES_THEN SUBST1_TAC o
       REWRITE_RULE[good_dimindex_def]) THEN
     CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED THEN
     CONV_TAC NUM_REDUCE_CONV;
     ALL_TAC] THEN
   REWRITE_TAC[byte_aligned_def;
               aligned_def; align_def;
               bytes_in_word_def] THEN
   CONJ_TAC THENL
    [ALL_TAC;
     SUBST1_TAC(WORD_RULE
       `n2w (dimindex (:'a) DIV 8) * (w:'a word) =
        w * n2w (dimindex (:'a) DIV 8)`)] THEN
   FIRST_ASSUM(fun f1 -> REWRITE_TAC[MATCH_MP mul_shl f1]) THEN
   MATCH_ACCEPT_TAC shl_slice));;

let parts_to_words_add = prove
 (`!parts' m i off a w ws m1.
     parts_to_words c m i parts' (off:'a word) = SOME (w,ws) /\
     byte_aligned off /\ byte_aligned a /\
     good_dimindex (:'a) /\ backend_common_word_shift (:'a) <=
       shift_length c /\
     (!i. SND (lookup_mem m1 i) = word_cond_add c a (lookup_mem m i))
       ==>
     (?v vs. parts_to_words c m1 i parts' (off + (a:'a word)) = SOME
       (v,vs) /\
            MAP SND vs = MAP (word_cond_add c a) ws /\
            SND v = word_cond_add c a w)`,
  (* the parts one after the other: this part's words by the
     theorem before this one, and the rest by the induction
     hypothesis of the two maps with this part's word put in
     (ins_cond), at the offset that the words of this part move on
     by -- which is aligned (byte_aligned_add) and the same whether
     a is added before or after it *)
  (let gen = prove
    (`!parts' m i (off:'a word) a w ws m1.
        parts_to_words c m i parts' off = SOME (w,ws) /\
        byte_aligned off /\ byte_aligned a /\ good_dimindex (:'a) /\
        backend_common_word_shift (:'a) <= shift_length c /\
        (!j. SND (lookup_mem m1 j) =
             word_cond_add c a (lookup_mem m j))
        ==> (?v vs. parts_to_words c m1 i parts' (off + a) =
                      SOME (v,vs) /\
                    MAP SND vs = MAP (word_cond_add c a) ws /\
                    SND v = word_cond_add c a w)`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[parts_to_words_def] THENL
      [STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       REWRITE_TAC[injectivity "option"; PAIR_EQ;
                   GSYM CONJ_ASSOC] THEN
       EXISTS_EQ_TAC THEN ASM_REWRITE_TAC[MAP];
       STRIP_TAC THEN
       PW_SPLIT_CALL_TAC "part_to_words" THEN
       PW_SPLIT_CALL_TAC "parts_to_words" THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       W(fun g ->
         let pt = av_find (pw_is_lhs "part_to_words") g
         and gd = av_find (hd_is "good_dimindex") g
         and sh = av_find (is_binary "<=") g
         and cond = av_find is_cond g in
         let off = last(snd(strip_comb(lhs(concl pt)))) in
         let a = el 1 (snd(strip_comb(rhs(snd(strip_forall(concl
                   cond)))))) in
         let ba_off = av_find (fun t -> hd_is "byte_aligned" t &&
                                        rand t = off) g
         and ba_a = av_find (fun t -> hd_is "byte_aligned" t &&
                                      rand t = a) g in
         MP_TAC(MATCH_MP (MATCH_MP (SPEC_ALL part_to_words_add)
           (CONJ ba_off (CONJ ba_a (CONJ gd sh))))
           (CONJ pt cond))) THEN
       DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
       W(fun g ->
         let gd = av_find (hd_is "good_dimindex") g
         and sh = av_find (is_binary "<=") g
         and cond = av_find is_cond g
         and ih = av_find is_ih g
         and pw = av_find (pw_is_lhs "parts_to_words") g in
         let body = snd(strip_forall(concl cond)) in
         let m1t = el 0 (snd(strip_comb(rand(lhs body))))
         and mt = el 0 (snd(strip_comb(rand(rhs body)))) in
         let pt = av_find (fun t -> pw_is_lhs "part_to_words" t &&
                    el 1 (snd(strip_comb(lhs t))) = mt) g
         and pt1 = av_find (fun t -> pw_is_lhs "part_to_words" t &&
                     el 1 (snd(strip_comb(lhs t))) = m1t) g in
         let off = last(snd(strip_comb(lhs(concl pt)))) in
         let a = el 1 (snd(strip_comb(rhs body))) in
         let ba_a = av_find (fun t -> hd_is "byte_aligned" t &&
                                      rand t = a) g in
         let map_eq = av_find (fun t -> is_eq t &&
                                 hd_is "MAP" (lhs t)) g in
         let len_eq = MATCH_MP len_of_map map_eq in
         let snd_eq = av_find (fun t -> is_eq t &&
                                 hd_is "SND" (lhs t)) g in
         let off2 = last(snd(strip_comb(lhs(concl pw)))) in
         let ba2 = MATCH_MP byte_aligned_add
           (CONJ gd (CONJ (av_find (fun t ->
                             hd_is "byte_aligned" t &&
                             rand t = off) g)
              (SPEC (rand(rand off2)) (GEN_ALL(CONJUNCT2(MATCH_MP
                 byte_align_mult_bytes_in_word gd)))))) in
         let cond2 = MATCH_MP ins_cond (CONJ cond snd_eq) in
         let ith = MATCH_MP (SPEC_ALL ih)
           (CONJ pw (CONJ ba2 (CONJ ba_a (CONJ gd
              (CONJ sh cond2))))) in
         REWRITE_TAC[pt1] THEN
         CONV_TAC(ONCE_DEPTH_CONV MATCH_CONV) THEN
         REWRITE_TAC[len_eq] THEN
         SUBGOAL_THEN (mk_eq(mk_binop `(+):'a word->'a word->'a word`
                               (mk_binop
                                  `(+):'a word->'a word->'a word`
                                  off a) (rand off2),
                             mk_binop `(+):'a word->'a word->'a word`
                               off2 a)) SUBST1_TAC THENL
          [CONV_TAC WORD_RULE; ALL_TAC] THEN
         MP_TAC ith THEN
         DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
         W(fun g2 ->
           let pw2 = av_find (fun t ->
             pw_is_lhs "parts_to_words" t &&
             (try rand(last(snd(strip_comb(lhs t)))) = a
              with Failure _ -> false)) g2 in
           REWRITE_TAC[pw2] THEN MATCH_REDUCE_TAC THEN
           REWRITE_TAC[distinctness "option"; injectivity "option";
                       PAIR_EQ; GSYM CONJ_ASSOC] THEN
           EXISTS_EQ_TAC THEN
           ASM_REWRITE_TAC[MAP_APPEND]))]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC(SPEC_ALL gen)));;

let part_to_words_IMP_build_words = prove
 (`part_to_words c m p (off:'a word) = SOME (w,ws) /\ good_dimindex
  (:'a) /\
   byte_aligned off /\ backend_common_word_shift (:'a) <=
     shift_length c ==>
   build_part_words c (\i. SND (lookup_mem m i)) p off = SOME (SND
     w,MAP SND ws)`,
  (* the four kinds of part again, where the deep embedding writes
     what the shallow one writes: the header of a bignum differs
     (hdr_bits), the pointer of a cons is the same one written out
     (make_cons_ptr_add), and the words themselves are the deep
     ones without their flags *)
  (REPEAT GEN_TAC THEN CASES_ON_NAME "p" THEN
   REWRITE_TAC[part_to_words_def; build_part_words_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN STRIP_TAC THEN
   TRY PAIRARG_TAC THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
   EVERY_CASE_COND_TAC THEN VAR_EQ_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_SIMP_TAC[GEN_ALL hdr_bits] THEN
   EVERY_CASE_COND_TAC THEN VAR_EQ_TAC THEN
   ASM_SIMP_TAC[MAP; GSYM MAP_o; o_DEF; SND; ETA_AX;
                make_cons_ptr_add; get_lowerbits_ptrbits]));;

let parts_to_words_IMP_build_words = prove
 (`!c m i parts' (off:'a word) w ws.
     parts_to_words c m i parts' off = SOME (w,ws) /\ good_dimindex
       (:'a) /\
     byte_aligned off /\ backend_common_word_shift (:'a) <=
       shift_length c ==>
     build_words c (\i. SND (lookup_mem m i)) i parts' off = SOME
       (SND w,MAP SND ws)`,
  (* the parts one after the other, with the map, the index and the
     offset that the recursion changes generalised.  The offset of
     the next part is the one of this part and the words it wrote,
     which is aligned as well (byte_aligned_add), and the map with
     this part's word put in is the function of the shallow side
     with it put in (upd_lookup) *)
  (let gen = prove
    (`!parts' c m i (off:'a word) w ws.
        parts_to_words c m i parts' off = SOME (w,ws) /\
        good_dimindex (:'a) /\ byte_aligned off /\
        backend_common_word_shift (:'a) <= shift_length c
        ==> build_words c (\j. SND (lookup_mem m j)) i parts' off =
            SOME (SND w,MAP SND ws)`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[parts_to_words_def; build_words_def] THENL
      [STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       REWRITE_TAC[MAP] THEN BETA_TAC THEN REWRITE_TAC[];
       STRIP_TAC THEN
       PW_SPLIT_CALL_TAC "part_to_words" THEN
       PW_SPLIT_CALL_TAC "parts_to_words" THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       W(fun g ->
         let pt = av_find (pw_is_lhs "part_to_words") g
         and pw = av_find (pw_is_lhs "parts_to_words") g
         and gd = av_find (hd_is "good_dimindex") g
         and ba = av_find (hd_is "byte_aligned") g
         and sh = av_find (is_binary "<=") g
         and ih = av_find is_forall g in
         let pth = MATCH_MP part_to_words_IMP_build_words
                     (CONJ pt (CONJ gd (CONJ ba sh))) in
         let off2 = last(snd(strip_comb(lhs(concl pw)))) in
         let bal = MATCH_MP byte_aligned_add
           (CONJ gd (CONJ ba (SPEC (rand(rand off2))
              (GEN_ALL(CONJUNCT2(MATCH_MP
                 byte_align_mult_bytes_in_word gd)))))) in
         let ith = MATCH_MP (SPEC_ALL ih)
                     (CONJ pw (CONJ gd (CONJ bal sh))) in
         REWRITE_TAC[pth; LENGTH_MAP; GSYM upd_lookup; ith] THEN
         MATCH_REDUCE_TAC THEN REWRITE_TAC[MAP_APPEND])]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC(SPEC_ALL gen)));;

let LESS_EQ_num_size = prove
 (`good_dimindex (:'a) ==>
   (!m n. n <= m ==> SUC (LENGTH (n2mw n:('a word) list)) <=
     num_size m)`,
  (* the same as LENGTH_n2mw_LE_num_size, with the good_dimindex
     pulled out in front, as the source states it twice *)
  (DISCH_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
   FIRST_ASSUM(fun le -> FIRST_ASSUM(fun gd ->
     MATCH_ACCEPT_TAC(MATCH_MP LENGTH_n2mw_LE_num_size
                        (CONJ gd le))))));;

(* the port's own: a number that is below 2 EXP 29 is a small int,
   whichever of the two word sizes it is -- which is what says that
   the words of a constant part are counted by part_space_req *)

let small_29 = prove
 (`good_dimindex (:'a) /\ num_of_int (abs i) < 2 EXP 29
   ==> small_int (:'a) i`,
  REWRITE_TAC[good_dimindex_def; small_int_def; dimword] THEN
  STRIP_TAC THEN
  (SUBGOAL_THEN `abs (i:int) < &(2 EXP 29)` MP_TAC THENL
    [FIRST_ASSUM(fun lt ->
       if not (is_binary "<" (concl lt)) then fail() else
       ACCEPT_TAC(ONCE_REWRITE_RULE
         [MATCH_MP INT_OF_NUM_OF_INT (SPEC `i:int` INT_ABS_POS)]
         (REWRITE_RULE[GSYM INT_OF_NUM_LT] lt)));
     ALL_TAC]) THEN
  ASM_REWRITE_TAC[ARITH_RULE `2 EXP 32 DIV 8 = 2 EXP 29`;
                  ARITH_RULE `2 EXP 64 DIV 8 = 2 EXP 61`] THEN
  CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC);;

let part_to_words_LENGTH = prove
 (`part_to_words c m h a = SOME ((w:bool#'a word_loc),ws) /\
   good_dimindex (:'a) ==>
   LENGTH ws <= part_space_req h`,
  (* the four kinds of constant part, each written as a header and
     the words of its content: a small int writes nothing, a Con
     writes its elements, a W64 at most three words, and a string
     as many as its bytes fill *)
  (REPEAT GEN_TAC THEN CASES_ON_NAME "h" THEN
   REWRITE_TAC[part_to_words_def; part_space_req_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN STRIP_TAC THEN
   TRY PAIRARG_TAC THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
   EVERY_CASE_COND_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[NULL_EQ]) THEN VAR_EQ_TAC THEN
   ASM_REWRITE_TAC[LENGTH; LENGTH_MAP; LENGTH_write_bytes;
                   LENGTH_REPLICATE] THEN
   TRY ASM_ARITH_TAC THEN
   FIRST
    [(* a list of no elements that is not empty *)
     SOLVED(SUBGOAL_THEN `F` CONTR_TAC THEN
            ASM_MESON_TAC[LENGTH_EQ_NIL]);
     (* a number below 2 EXP 29 that is not a small int *)
     SOLVED(SUBGOAL_THEN `F` CONTR_TAC THEN
            ASM_MESON_TAC[GEN_ALL small_29]);
     (* and otherwise the words of the number, which num_size
        bounds *)
     SOLVED
      (RULE_ASSUM_TAC(REWRITE_RULE[i2mw_def; PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       FIRST_ASSUM(fun gd ->
         if not (hd_is "good_dimindex" (concl gd)) then fail() else
         MATCH_MP_TAC(MATCH_MP LESS_EQ_num_size gd)) THEN
       REWRITE_TAC[LE_REFL]);
     (* the bytes of a string, of which a word holds four or
        eight *)
     SOLVED
      (REWRITE_TAC[byte_len_def; LENGTH_explode] THEN
       FIRST_ASSUM(fun gd ->
         if not (hd_is "good_dimindex" (concl gd)) then fail() else
         STRIP_ASSUME_TAC(REWRITE_RULE[good_dimindex_def] gd)) THEN
       ASM_REWRITE_TAC[ARITH_EQ] THEN
       MP_TAC(SPECL [`8`; `strlen a'`; `4`] DIV_MONO2) THEN
       REWRITE_TAC[ARITH] THEN ARITH_TAC)]));;

let const_parts_to_words_LENGTH = prove
 (`const_parts_to_words c parts = SOME ((w:bool#'a word_loc),ws) /\
   good_dimindex (:'a) ==>
   LENGTH ws <= SUM (MAP part_space_req parts)`,
  (* the parts one after the other, each counted by
     part_to_words_LENGTH, with the map, the index and the offset
     that the recursion changes generalised *)
  (let sum_cons = prove
    (`!f h t. SUM (MAP f (CONS h t)) = f h + SUM (MAP f t)`,
     REWRITE_TAC[MAP; SUM_DEF; ITLIST]) in
   let gen = prove
    (`!parts' c m i (off:'a word) w ws.
        parts_to_words c m i parts' off = SOME (w,ws) /\
        good_dimindex (:'a)
        ==> LENGTH ws <= SUM (MAP part_space_req parts')`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[parts_to_words_def; sum_cons] THENL
      [STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       REWRITE_TAC[LENGTH; LE_0];
       STRIP_TAC THEN EVERY_CASE_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       REWRITE_TAC[LENGTH_APPEND] THEN
       MATCH_MP_TAC LE_ADD2 THEN CONJ_TAC THENL
        [FIRST_ASSUM(fun pt ->
           if not (hd_is "part_to_words" (lhs(concl pt)))
           then fail() else
           FIRST_ASSUM(fun gd ->
             if not (hd_is "good_dimindex" (concl gd)) then fail()
             else
             MATCH_ACCEPT_TAC(MATCH_MP part_to_words_LENGTH
               (CONJ pt gd))));
         FIRST_ASSUM(fun ih ->
           if not (is_forall (concl ih)) then fail() else
           FIRST_ASSUM(fun pw ->
             if not (hd_is "parts_to_words" (lhs(concl pw))) then
               fail() else
             FIRST_ASSUM(fun gd ->
               if not (hd_is "good_dimindex" (concl gd)) then
                 fail() else
               MATCH_ACCEPT_TAC(MATCH_MP (SPEC_ALL ih)
                 (CONJ pw gd)))))]]) in
   REWRITE_TAC[const_parts_to_words_def] THEN
   MATCH_ACCEPT_TAC(SPEC_ALL gen)));;

let good_loc_def = cake_define
  `good_loc code x2 =
      match x2 with
        wordLang_Loc n m -> (m = 0 /\ n IN code)
      | _117 -> T`;;

(* the port's own: what says that the words of a constant part are
   good_loc.  Nothing a part writes is a Loc: it writes words, and
   the entries of the map, which the invariant of the induction
   keeps good. *)

let good_loc_Word = prove
 (`!s w. good_loc s (wordLang_Word w) = T`,
  REPEAT GEN_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [good_loc_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

let good_loc_LN = prove
 (`!s k. good_loc s
           (SND (lookup_mem (LN:(bool#('a word_loc))spt) k))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[lookup_mem_def; lookup_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[SND; good_loc_Word]);;

let part_gl = prove
 (`(!k. good_loc s (SND (lookup_mem m k))) /\
   part_to_words c m h (off:'a word) = SOME ((y0,y1),y2)
   ==> good_loc s y1 /\ EVERY (good_loc s o SND) y2`,
  STRIP_TAC THEN
  RULE_ASSUM_TRY (CONV_RULE(REWRITE_CONV[part_to_words_def])) THEN
  POP_ASSUM MP_TAC THEN
  CASES_ON_NAME "h" THEN
  REWRITE_TAC[part_to_words_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  TRY PAIRARG_TAC THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
  TRY(CONV_TAC(TOP_DEPTH_CONV let_CONV)) THEN
  EVERY_CASE_COND_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option";
              PAIR_EQ] THEN
  STRIP_TAC THEN VAR_EQ_TAC THEN
  ASM_REWRITE_TAC[ALL; ALL_MAP; good_loc_Word; o_DEF; SND;
                  make_ptr_def; make_cons_ptr_def] THEN
  ASM_REWRITE_TAC[good_loc_Word; ALL_T]);;

let ins_loc = prove
 (`(!k. good_loc s (SND (lookup_mem m k))) /\ good_loc s y1
   ==> (!k. good_loc s
              (SND (lookup_mem (insert i ((y0:bool),y1) m) k)))`,
  STRIP_TAC THEN GEN_TAC THEN REWRITE_TAC[lookup_mem_insert] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[SND]);;

let const_parts_to_words_good_loc = prove
 (`const_parts_to_words c parts = SOME ((y0,y1),y2) ==>
   good_loc s y1 /\ EVERY (good_loc s o SND) y2`,
  (* the parts one after the other, with the map generalised: the
     map starts empty, where every lookup is a word (good_loc_LN),
     and what each part puts in is good as well (part_gl), so the
     invariant holds all the way along (ins_loc) *)
  (let gen = prove
    (`!parts' m i (off:'a word) y0 y1 y2.
        (!k. good_loc s (SND (lookup_mem m k))) /\
        parts_to_words c m i parts' off = SOME ((y0,y1),y2)
        ==> good_loc s y1 /\ EVERY (good_loc s o SND) y2`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[parts_to_words_def] THENL
      [STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       W(fun g ->
         let inv = av_find is_forall g in
         let eq = av_find (fun t -> is_eq t &&
                             hd_is "lookup_mem" (lhs t)) g in
         let k = last(snd(strip_comb(lhs(concl eq)))) in
         REWRITE_TAC[ALL; o_DEF] THEN
         ACCEPT_TAC(REWRITE_RULE[eq; SND] (SPEC k inv)));
       STRIP_TAC THEN
       PW_SPLIT_CALL_TAC "part_to_words" THEN
       TRY(W(fun g ->
         let pt = av_find (pw_is_lhs "part_to_words") g in
         CASES_ON_TAC (fst(dest_pair(rand(rhs(concl pt))))))) THEN
       PW_SPLIT_CALL_TAC "parts_to_words" THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       W(fun g ->
         let inv = av_find is_forall g
         and pt = av_find (pw_is_lhs "part_to_words") g
         and pw = av_find (pw_is_lhs "parts_to_words") g in
         let gl = MATCH_MP (GEN_ALL part_gl) (CONJ inv pt) in
         let body = snd(strip_forall(concl inv)) in
         let st = el 0 (snd(strip_comb body))
         and sndf = rator(rand body) in
         let mp = el 1 (snd(strip_comb(lhs(concl pw)))) in
         let tm = mk_forall(`k:num`,
                    list_mk_icomb "good_loc"
                      [st; mk_comb(sndf,
                             list_mk_icomb "lookup_mem"
                               [mp; `k:num`])]) in
         (SUBGOAL_THEN tm ASSUME_TAC THENL
           [GEN_TAC THEN REWRITE_TAC[lookup_mem_insert] THEN
            COND_CASES_TAC THEN
            ASM_REWRITE_TAC[SND; CONJUNCT1 gl];
            ALL_TAC]) THEN
         W(fun g2 ->
           let inv2 = av_find (fun t -> t = tm) g2
           and ih = av_find is_ih g2 in
           MP_TAC(MATCH_MP ih (CONJ inv2 pw)) THEN MP_TAC gl)) THEN
       REWRITE_TAC[ALL_APPEND] THEN
       REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]]) in
   REWRITE_TAC[const_parts_to_words_def] THEN
   ASM_MESON_TAC[gen; good_loc_LN]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_do_build_const = prove
 (cake_as_vars (fun () ->
    `do_build_const parts refs (SOME ts) = (v,refs1,SOME ts1) /\
     const_parts_to_words c parts = SOME (w,ws) /\
     memory_rel c be ts refs sp st m dm vars /\
     SUM (MAP part_space_req parts) <= sp /\
     FLOOKUP st NextFree = SOME (wordLang_Word free) /\
     FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
     good_dimindex (:'a) ==>
     (?m1.
       let nf = free + bytes_in_word * n2w (LENGTH ws) in
       let adjust = word_cond_add c (free - (curr:'a word)) in
         memory_rel c be ts1 refs1 (sp - LENGTH ws)
           (st |+ (NextFree,wordLang_Word nf)) m1 dm ((v,adjust w)
             :: vars) /\
         data_to_word_memoryProof_store_list free (MAP adjust ws)
           m dm = SOME m1)`),
  (* the attempt: the proof of the source names memory_rel_do_build,
     word_cond_add_def, do_build_const_def, IMP_memory_rel_Number,
     good_dimindex_def, const_parts_to_words_def.  What is here
     rewrites with them and closes by arithmetic, and the cheat is
     behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_do_build; word_cond_add_def;
       do_build_const_def; IMP_memory_rel_Number;
       good_dimindex_def; const_parts_to_words_def] THEN
     TRY ASM_ARITH_TAC)));;

let read_word_def = cake_define
  `read_word dm m a = (theWord (m a),(a IN dm /\ isWord (m a)))`;;

(* HOL4 data_to_word_memoryProofScript.sml:18378-18384: the tactic
   that proves the termination *)
(* the first pass assumes the termination:
   replacing the CHEAT_TAC is all that is left *)
let word_xor_bytes_def = cake_define_try_tac (fun () ->
  `MEASURE (\(a1,a2,len,dm,m). w2n len)`)
  CHEAT_TAC
  `word_xor_bytes (a1:'a word) (a2:'a word) (len:'a word) dm m =
     (if len <+ (n2w 2) \/ ~(good_dimindex (:'a)) then
       if len = (n2w 0) then SOME m else
         let (w1a,c1) = read_word dm m a1 in
         let (w2a,c2) = read_word dm m a2 in
         let a = word_xor w1a w2a in
         let m = (a2 =+ wordLang_Word (a:'a word)) m in
           if c1 /\ c2 then SOME m else NONE else
       let (w1a,c1) = read_word dm m a1 in
       let (w2a,c2) = read_word dm m a2 in
       let (w1b,c3) = read_word dm m (a1 + bytes_in_word) in
       let (w2b,c4) = read_word dm m (a2 + bytes_in_word) in
       let a = word_xor w1a w2a in
       let b = word_xor w1b w2b in
       let m = ((a2 + bytes_in_word) =+ wordLang_Word b) ((a2 =+
         wordLang_Word a) m) in
         if c1 /\ c2 /\ c3 /\ c4 then
           word_xor_bytes (a1 + (n2w 2) * bytes_in_word) (a2 + (n2w
             2) * bytes_in_word)
             (len - (n2w 2)) dm m else NONE)`;;

let make_zeros_def = cake_define
  `make_zeros (vals:word8 list) =
     REPLICATE (LENGTH vals DIV (dimindex (:'a) DIV 8) + 1) ((n2w
       0):'a word)`;;

let xor_words_def = cake_define
  `xor_words xs ys =
      match (xs,ys) with
        ([],ys) -> SOME ys
      | (xs,[]) -> NONE
      | ((x :: xs),(y :: ys)) ->
     (match xor_words xs ys with NONE -> NONE | SOME rest -> SOME
       (word_xor (x:'a word) y :: rest))`;;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_xor_set_byte = prove
 (cake_as_vars (fun () ->
    `word_xor (set_byte a h1 w1 be) (set_byte a h2 w2 be) =
     set_byte a (word_xor h1 h2) (word_xor w1 w2) be`),
  (let bsa = prove
    (`!h l (w:(N)word) j. j < dimindex (:N)
        ==> (bit j (word_slice_alt h l w) <=>
             l <= j /\ j < h /\ bit j w)`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[word_slice_alt; BIT_WORD_SHL; BIT_WORD_SUBWORD] THEN
     REWRITE_TAC[ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
     ASM_CASES_TAC `l:num <= j` THEN ASM_REWRITE_TAC[] THEN
     ASM_SIMP_TAC[ARITH_RULE `l <= j ==> l + j - l = j`] THEN
     COND_CASES_TAC THEN
     ASM_CASES_TAC `bit j (w:(N)word)` THEN ASM_REWRITE_TAC[] THEN
     ARITH_NO_BIT_TAC) in
   let bsb0 = prove
    (`!(a:(N)word) b (h:(N)word) bb j. j < dimindex (:N)
        ==> (bit j (set_byte a b h bb) <=>
             (if byte_index a bb <= j /\ j < byte_index a bb + 8
              then bit (j - byte_index a bb) b else bit j h))`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[set_byte_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_SIMP_TAC[BIT_WORD_OR; bsa; BIT_WORD_SHL; BIT_WORD_ZX;
                  DIMINDEX_8] THEN
     MP_TAC(REWRITE_RULE[DIMINDEX_8]
       (ISPECL [`b:(8)word`; `j - byte_index (a:(N)word) bb`]
          BIT_TRIVIAL)) THEN
     ASM_CASES_TAC `byte_index (a:(N)word) bb <= j` THEN
     ASM_CASES_TAC `j < byte_index (a:(N)word) bb + 8` THEN
     ASM_CASES_TAC `bit j (h:(N)word)` THEN
     ASM_CASES_TAC
       `bit (j - byte_index (a:(N)word) bb) (b:(8)word)` THEN
     ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC) in
   let gen = prove
    (`!(a:(N)word) h1 h2 w1 w2 bb.
        word_xor (set_byte a h1 w1 bb) (set_byte a h2 w2 bb) =
        set_byte a (word_xor h1 h2) (word_xor w1 w2) bb`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_SIMP_TAC[BIT_WORD_XOR; bsb0] THEN
     COND_CASES_TAC THEN
     TRY(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC)) THEN
     ASM_SIMP_TAC[BIT_WORD_XOR; DIMINDEX_8;
                  ARITH_RULE `b <= i /\ i < b + 8 ==> i - b < 8`]) in
   MATCH_ACCEPT_TAC gen));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let xor_bytes_bytes_to_word = prove
 (cake_as_vars (fun () ->
    `!k vals1 vals2 res_vals a.
       xor_bytes vals1 vals2 = SOME res_vals ==>
       bytes_to_word k a vals1 (n2w 0) be ??
       bytes_to_word k a vals2 (n2w 0) be =
       bytes_to_word k a res_vals (n2w 0) be`),
  (* the induction of the source on the number of bytes: the xor of
     the two bytes that the two words take is the byte that the word
     of the xor takes (word_xor_set_byte), and the induction
     hypothesis says it of the rest.  MATCH_CONV leaves the match on
     the result of the recursive call as an epsilon term, which
     UNWIND_CONV and the two theorems about one take apart *)
  (INDUCT_TAC THENL
    [ONCE_REWRITE_TAC[bytes_to_word_def] THEN
     REWRITE_TAC[WORD_XOR_0];
     ALL_TAC] THEN
   REPEAT GEN_TAC THEN
   LIST_CASES_TAC ["vals1"; "vals2"] THEN
   ONCE_REWRITE_TAC[xor_bytes_def] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[distinctness "option"] THEN
   TRY (W(fun (asl,w) ->
     CASES_ON_TAC (find_term (hd_is "xor_bytes") w))) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
   TRY (CONV_TAC(REDEPTH_CONV UNWIND_CONV)) THEN
   REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL;
               distinctness "option"; injectivity "option"] THEN
   DISCH_THEN (SUBST1_TAC o SYM) THEN
   ONCE_REWRITE_TAC[bytes_to_word_def] THEN
   REWRITE_TAC[NOT_SUC; SUC_SUB1] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[WORD_XOR_0; word_xor_set_byte] THEN
   FIRST_X_ASSUM (fun ih -> FIRST_ASSUM (fun h ->
     REWRITE_TAC[GEN_ALL (MATCH_MP ih h)]))));;

let xor_bytes_length = prove
 (`!xs ys zs.
     xor_bytes xs ys = SOME zs ==>
     LENGTH xs <= LENGTH zs /\ LENGTH zs = LENGTH ys`,
  (* the xor of two lists of bytes is as long as the second and at
     least as long as the first, by the induction of the
     definition; the case of the xor of the tails is what
     EVERY_CASE_TAC splits *)
  (let xb = xor_bytes_def in
   LIST_INDUCT_TAC THENL
    [REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [xb] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[injectivity "option"] THEN
     DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[LENGTH; LE_0];
     (fun (asl,w as gl) ->
        let ysv = fst(dest_forall w) in
        (X_GEN_TAC ysv THEN
         STRUCT_CASES_TAC(ISPEC ysv list_CASES_v)) gl) THEN
     GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [xb] THEN
     EVERY_CASE_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
     TRY(DISCH_THEN(SUBST1_TAC o SYM)) THEN
     REWRITE_TAC[LENGTH; LE_SUC; SUC_INJ] THEN
     FIRST_ASSUM(fun st -> FIRST_ASSUM(fun ih ->
       ACCEPT_TAC(MATCH_MP ih st)))]));;

(* [local] *)
let xor_bytes_drop = prove
 (`!n xs ys zs.
     xor_bytes xs ys = SOME zs ==>
     xor_bytes (DROP n xs) (DROP n ys) = SOME (DROP n zs)`,
  (* dropping from both lists drops from the xor as well, by the
     induction of the definition *)
  (let xb = xor_bytes_def in
   SUBGOAL_THEN
     `!xs n ys zs. xor_bytes xs ys = SOME zs
