  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[word_str_cmp_loop_def; find_diff_def] THEN
     TRY ASM_ARITH_TAC)));;

