let compoare_aux_append_xs = prove
 (`!zs z xs ys r.
     LENGTH xs <= LENGTH ys ==>
     compare_aux (implode (z :: (zs ++ xs)))
                 (implode (z :: (zs ++ ys))) r (LENGTH zs + 1)
                   (STRLEN xs) =
     compare_aux (implode (zs ++ xs)) (implode (zs ++ ys)) r
       (LENGTH zs) (STRLEN xs)`,
  (* the same character in front of both strings and the index one
     further on compare the same characters: the induction is on the
     length that is left to compare, and the premise about the two
     lengths is not needed *)
  (let shift_lemma = prove
    (`!len start r (zz:char) l1 l2.
        compare_aux (implode (CONS zz l1)) (implode (CONS zz l2)) r
          (start + 1) len =
        compare_aux (implode l1) (implode l2) r start len`,
     let el_suc = prove
      (`!n h (t:A list). EL (n + 1) (CONS h t) = EL n t`,
       REWRITE_TAC[GSYM ADD1; EL; TL]) in
     INDUCT_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[compare_aux_def] THEN
     REWRITE_TAC[NOT_SUC; SUC_SUB1; strsub_def; el_suc] THEN
     ASM_REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN DISCH_TAC THEN MATCH_ACCEPT_TAC shift_lemma));;

(* [local] *)
let compoare_aux_append_ys = prove
 (`!zs z xs ys r.
     LENGTH ys <= LENGTH xs ==>
     compare_aux (implode (z :: (zs ++ xs)))
                 (implode (z :: (zs ++ ys))) r (LENGTH zs + 1)
                   (STRLEN ys) =
     compare_aux (implode (zs ++ xs)) (implode (zs ++ ys)) r
       (LENGTH zs) (STRLEN ys)`,
  (* and the same of the shorter second string *)
  (let shift_lemma = prove
    (`!len start r (zz:char) l1 l2.
        compare_aux (implode (CONS zz l1)) (implode (CONS zz l2)) r
          (start + 1) len =
        compare_aux (implode l1) (implode l2) r start len`,
     let el_suc = prove
      (`!n h (t:A list). EL (n + 1) (CONS h t) = EL n t`,
       REWRITE_TAC[GSYM ADD1; EL; TL]) in
     INDUCT_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[compare_aux_def] THEN
     REWRITE_TAC[NOT_SUC; SUC_SUB1; strsub_def; el_suc] THEN
     ASM_REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN DISCH_TAC THEN MATCH_ACCEPT_TAC shift_lemma));;

let compare_same = prove
 (`compare (implode (x :: xs)) (implode (x :: ys)) =
   compare (implode xs) (implode ys)`,
  (* the first characters are the same, so the comparison steps over
     them: the index goes up by one, which the shift of
     compoare_aux_append_xs takes off again, and the lengths are one
     less on both sides *)
  (let shift_lemma = prove
    (`!len start r (zz:char) l1 l2.
        compare_aux (implode (CONS zz l1)) (implode (CONS zz l2)) r
          (start + 1) len =
        compare_aux (implode l1) (implode l2) r start len`,
     let el_suc = prove
      (`!n h (t:A list). EL (n + 1) (CONS h t) = EL n t`,
       REWRITE_TAC[GSYM ADD1; EL; TL]) in
     INDUCT_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[compare_aux_def] THEN
     REWRITE_TAC[NOT_SUC; SUC_SUB1; strsub_def; el_suc] THEN
     ASM_REWRITE_TAC[]) in
   let first_eq = prove
    (`!r (zz:char) l1 l2 n.
        compare_aux (implode (CONS zz l1)) (implode (CONS zz l2)) r 0
          (SUC n) =
        compare_aux (implode l1) (implode l2) r 0 n`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [compare_aux_def] THEN
     REWRITE_TAC[NOT_SUC; SUC_SUB1; strsub_def; EL; HD;
                 char_lt; LT_REFL; shift_lemma]) in
   REWRITE_TAC[mlstring_compare_def; strlen_def;
               LENGTH; LT_SUC; first_eq]));;

let str_cmp_cons = prove
 (`str_cmp b cmp (implode (x :: xs)) (implode (x :: ys)) =
   str_cmp b cmp (implode xs) (implode ys)`,
  (* each of the eight comparisons is the one of mlstring_compare,
     which compare_same takes off the first character, or a
     comparison of the lengths, which are one less *)
  (REWRITE_TAC[str_cmp_def] THEN
   CASES_ON_NAME "b" THEN CASES_ON_NAME "cmp" THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[mlstring_lt_def; mlstring_le_def;
               mlstring_gt_def; mlstring_ge_def;
               fast_lt_def; fast_le_def;
               fast_gt_def; fast_ge_def;
               compare_same; strlen_def;
               LENGTH; SUC_INJ; LT_SUC; LE_SUC;
               GT; GE; ARITH_RULE `SUC m >= SUC n <=> m >= n`;
               ARITH_RULE `SUC m > SUC n <=> m > n`]));;

let find_diff_str_cmp_thm1 = prove
 (`!vals1 vals2.
     LENGTH (vals1:word8 list) = LENGTH (vals2:word8 list) /\
     good_dimindex (:'a) ==>
     (?(r1:'a word) (r2:'a word).
       find_diff vals1 vals2 (n2w l) (n2w l) = (r1,r2) /\
       (str_cmp T cmp (implode (MAP (CHR o w2n) vals1)) (implode (MAP
         (CHR o w2n) vals2)) <=>
        num_cmp cmp (w2n r1) (w2n r2)))`,
  (* the attempt: the proof of the source names find_diff_def,
     str_cmp_cons, dimword, good_dimindex_def, str_cmp_def,
     fast_lt_def.  What is here rewrites with them and closes by
     arithmetic, and the cheat is behind it until the proof is
     written.  A MESON over them is what the next round adds; it
     costs a load ten minutes to have it in every attempt and it
     closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[find_diff_def; str_cmp_cons; dimword;
       good_dimindex_def; str_cmp_def; fast_lt_def] THEN
     TRY ASM_ARITH_TAC)));;

let MIN_SUC_SUC = prove
 (`MIN (SUC m) (SUC n) = SUC (MIN m n)`,
  (ARITH_TAC));;

let find_diff_str_cmp_thm2 = prove
 (`!k vals1 vals2 l1 l2.
     Abbrev (l1 = LENGTH vals1 + 2 EXP backend_common_word_shift
       (:'a)) /\
     Abbrev (l2 = LENGTH vals2 + 2 EXP backend_common_word_shift
       (:'a)) /\
     k + l1 < dimword (:'a) /\ k + l2 < dimword (:'a) /\
       good_dimindex (:'a) ==>
     (?(r1:'a word) (r2:'a word).
       find_diff (TAKE (MIN (LENGTH vals1) (LENGTH vals2))
         (vals1:word8 list))
                 (TAKE (MIN (LENGTH vals1) (LENGTH vals2)) vals2)
                 (n2w (k + l1))
                 (n2w (k + l2)) = (r1,r2) /\
       (str_cmp F cmp (implode (MAP (CHR o w2n) vals1))
                      (implode (MAP (CHR o w2n) vals2)) <=>
        num_cmp cmp (w2n r1) (w2n r2)))`,
  (* the attempt: the proof of the source names find_diff_def,
     num_cmp_def, str_cmp_def, fast_lt_def, fast_gt_def,
     fast_le_def.  What is here rewrites with them and closes by
     arithmetic, and the cheat is behind it until the proof is
     written.  A MESON over them is what the next round adds; it
     costs a load ten minutes to have it in every attempt and it
     closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[find_diff_def; num_cmp_def; str_cmp_def;
       fast_lt_def; fast_gt_def; fast_le_def] THEN
     TRY ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_str_cmp = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((RefPtr bl1 p1,(v1:'a word_loc)) :: (RefPtr bl2 p2,(v2:'a
         word_loc)) :: vars) /\
     lookup p1 refs = SOME (ByteArray fl1 vals1) /\
     lookup p2 refs = SOME (ByteArray fl2 vals2) /\
     good_dimindex (:'a) ==>
     (?w1 a1 w2 a2 x1 m1 r1 r2.
       v1 = wordLang_Word w1 /\
       v2 = wordLang_Word w2 /\
       get_real_addr c st w1 = SOME a1 /\
       get_real_addr c st w2 = SOME a2 /\
       word_str_cmp b a1 a2 dm m be c = SOME (r1,r2) /\
       str_cmp b cmp (implode (MAP (CHR o w2n) vals1))
                     (implode (MAP (CHR o w2n) vals2)) =
       semanticPrimitives_num_cmp cmp (w2n r1) (w2n r2))`),
  (* the attempt: the proof of the source names
     memory_rel_ByteArray_IMP, memory_rel_tl, word_str_cmp_def,
     isWord_def, theWord_def, make_byte_header_def.  What is here
     rewrites with them and closes by arithmetic, and the cheat is
     behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_ByteArray_IMP; memory_rel_tl;
       word_str_cmp_def; isWord_def; theWord_def;
       make_byte_header_def] THEN
     TRY ASM_ARITH_TAC)));;

